window.PM_DATA={"secciones":[{"nombre":"Základy","grupos":[{"nombre":"Základy kineziologie","icono":"🧭","temas":[1,2,3,4]},{"nombre":"Vyšetření","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"Speciální testy podle regionů","grupos":[{"nombre":"Rameno","icono":"💪","temas":[10,11,12]},{"nombre":"Loket, zápěstí a ruka","icono":"✋","temas":[13,14]},{"nombre":"Páteř a pánev","icono":"🦴","temas":[15,16,17]},{"nombre":"Kyčel a koleno","icono":"🦵","temas":[18,19,20]},{"nombre":"Hlezno a noha","icono":"🦶","temas":[21]},{"nombre":"Neurologické testy","icono":"🧠","temas":[22]}]},{"nombre":"Zranění a rehabilitace","grupos":[{"nombre":"Rameno","icono":"💪","temas":[23,24,25]},{"nombre":"Sport, šlachy a svaly","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"Ortopedie a traumatologie","icono":"🦴","temas":[31,32,33]},{"nombre":"Páteř","icono":"🧍","temas":[34,35,36]},{"nombre":"Neurologie","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"Léčba a intervence","grupos":[{"nombre":"Techniky a fyzioterapie","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"Pohybová terapie a odbornosti","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"Klinické kazuistiky","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"Roviny a osy","lead":"Pohyby těla popisujeme pomocí tří základních rovin a na ně kolmých os pohybu. Párování rovin a os je základem každého vyšetření, dokumentace a analýzy pohybu.","sheet":{"kind":"basics","items":[{"h":"Východisková poloha","t":"Roviny a osy definujeme z anatomické polohy. 0° měření ROM je v neutrální nulové poloze (předloktí ve středním postavení), proto dbejte na rozdíl mezi nimi."},{"h":"Sagitální rovina","t":"Dělí tělo na pravou a levou polovinu. Probíhá zde flexe–extenze a dorzální a plantární flexe hlezna; osou pohybu je frontální (příčná) osa."},{"h":"Frontální rovina","t":"Dělí tělo na přední a zadní část. Probíhá zde abdukce–addukce a úklon trupu; osou pohybu je sagitální osa."},{"h":"Transverzální rovina","t":"Dělí tělo na horní a dolní část. Probíhá zde vnitřní a zevní rotace, rotace trupu, horizontální flexe a extenze ramene; osou je podélná (vertikální) osa."},{"h":"Vztah roviny a osy","t":"Osa pohybu prochází rovinou pohybu vždy kolmo. Pokud se rovinu a osu učíte v páru, snadno zařadíte i neznámý pohyb."},{"h":"Složené pohyby","t":"Skutečné pohyby probíhají ve více rovinách. Chůzi nebo hod sledujeme v rovinách zvlášť a poté je analyzujeme společně."}]},"keypoints":["Sagitální rovina = flexe–extenze, osa: frontální (příčná) osa","Frontální rovina = abdukce–addukce, osa: sagitální osa","Transverzální rovina = rotace, osa: podélná (vertikální) osa","Osa pohybu je vždy kolmá na rovinu pohybu","Při analýze pohybu sledujte jednotlivé roviny zvlášť"],"case":{"text":"20letý atlet. V lehu na zádech zvedá nataženou dolní končetinu dopředu (kyčelní kloub). Chcete tento pohyb dokumentovat. Ve které rovině a kolem jaké osy jej popíšete?","answer":"Zvednutí kyčle vpřed je flexe: pohyb v sagitální rovině, osou je frontální (příčná) osa. Abyste si jej nezpletli s abdukcí ve frontální rovině, sledujte, zda pohyb probíhá v rovině dělící tělo na pravou a levou polovinu."},"questions":[{"level":"Základní","q":"Ve které rovině dochází k abdukci a addukci?","options":["Sagitální rovina","Frontální rovina","Transverzální rovina","Šikmá rovina"],"answer":1,"exp":"Frontální rovina dělí tělo na přední a zadní část; probíhá v ní abdukce–addukce. Osou pohybu je sagitální osa."},{"level":"Základní","q":"Jaká je osa pohybu rotace probíhající v transverzální rovině?","options":["Frontální (příčná) osa","Sagitální osa","Šikmá osa","Podélná (vertikální) osa"],"answer":3,"exp":"Pohyb v transverzální rovině (rotace) probíhá kolem podélné (vertikální) osy kolmé na rovinu."},{"level":"Pokročilý","q":"Který pohyb probíhá v sagitální rovině?","options":["Úklon trupu","Dorzální flexe hlezna","Zevní rotace kyčle","Abdukce ramene"],"answer":1,"exp":"Dorzální a plantární flexe probíhají podobně jako flexe a extenze v sagitální rovině. Úklon a abdukce jsou ve frontální rovině, zevní rotace v transverzální rovině."},{"level":"Pokročilý","q":"Ve které rovině probíhá horizontální flexe ramene?","options":["Sagitální rovina","Frontální rovina","Transverzální rovina","Nepatří do žádné roviny"],"answer":2,"exp":"Během horizontální flexe a extenze se horní končetina v 90° abdukci pohybuje v transverzální rovině, osou je podélná osa."},{"level":"Klinický","q":"Zevní rotaci ramene měříte s paží podél těla a loktem ohnutým do 90°. Který pár rovina–osa je správný?","options":["Sagitální rovina – frontální osa","Frontální rovina – sagitální osa","Transverzální rovina – podélná (vertikální) osa","Transverzální rovina – frontální (příčná) osa"],"answer":2,"exp":"Rotace v rameni při visící paži dovnitř a ven je pohyb v transverzální rovině kolem podélné osy paže (longitudinální osy)."},{"level":"Klinický","q":"Při pozorování chůze v oporné fázi klesá pánev směrem ke švihové straně. Kterou rovinu sledujete především?","options":["Frontální rovina","Sagitální rovina","Transverzální rovina","Rovinu nelze určit"],"answer":0,"exp":"Boční náklon pánve je pohyb ve frontální rovině, sledujeme ho zepředu nebo zezadu. Ukazuje na slabost m. gluteus medius."}],"seccion":"Základy","grupo":"Základy kineziologie","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"Biomechanika","lead":"Biomechanika vysvětluje pohyb těla prostřednictvím vztahu mezi silou a pohybem. Znalost pákového systému, točivého momentu a těžiště zpřesňuje dávkování zátěže v terapeutických cvičeních.","sheet":{"kind":"basics","items":[{"h":"Točivý moment","t":"Účinek otáčející kloub je točivý moment. Je to součin velikosti síly a ramena síly (kolmé vzdálenosti mezi osou otáčení a linií působení síly)."},{"h":"Tři typy pák","t":"U páky prvního řádu je uprostřed bod otáčení, u druhého břemeno a u třetího síla. Většina svalů funguje jako páka třetího řádu: je výhodná pro rychlost a rozsah pohybu."},{"h":"Těžiště","t":"Vstoji se těžiště těla nachází v pánvi, mírně před obratlem S2. Čím více těžnice spadá do opěrné plochy, tím je držení těla stabilnější."},{"h":"Kinetický řetězec","t":"V otevřeném kinetickém řetězci (OKC) se distální část volně pohybuje, v uzavřeném (CKC) je fixována k podložce nebo jinému povrchu. Volíme podle cíle."},{"h":"Způsoby svalové činnosti","t":"Při koncentrické kontrakci sval vyvíjí sílu při zkracování, při excentrické při prodlužování. Izometrická kontrakce probíhá bez pohybu v kloubu."},{"h":"Klinické použití","t":"Čím distálněji je závaží umístěno, tím delší je rameno síly a větší zátěž. Zátěž cviku lze regulovat nejen hmotností, ale i jejím umístěním."}]},"keypoints":["Točivý moment = síla × rameno síly","Většina svalů je páka 3. řádu (příznivá pro rychlost)","Držení těla je stabilní, pokud těžnice spadá do opěrné plochy","Většinu brzděných pohybů řídí excentrická kontrakce","Zátěž lze regulovat i umístěním závaží"],"case":{"text":"65letá žena, artróza kolene. V lehu na zádech provádí cvičení SLR se zátěžovou manžetou upevněnou na kotníku, ale rychle se unavuje a objevují se kompenzační pohyby.","answer":"Pokud umístíte závaží na proximální část bérce, rameno síly se zkrátí, a tím se při stejné hmotnosti sníží točivý moment flexe kyčle. Sledujíce bolest a kompenzace, postupně zvyšujte zátěž; nezvyšujte pouze počet opakování."},"questions":[{"level":"Základní","q":"U kterého typů páky se nachází bod otáčení mezi silou a břemenem?","options":["Páka 1. řádu","Páka 2. řádu","Páka 3. řádu","Kolo a osa"],"answer":0,"exp":"U páky prvního řádu je bod otáčení uprostřed; typickým příkladem je rovnováha hlavy při pohybu dopředu a dozdu."},{"level":"Základní","q":"Který typ páky je typickým příkladem flexe v lokti s účastí m. biceps brachii?","options":["Páka 1. řádu","Páka 2. řádu","Páka 3. řádu","Kladka"],"answer":2,"exp":"Úpon svalu (síla) se nachází mezi loketním kloubem (bod otáčení) a závažím v ruce (břemeno), proto jde o páku třetího řádu."},{"level":"Pokročilý","q":"Která dvojice veličin určuje velikost kloubního krouticího momentu?","options":["Velikost síly a rychlost","Délka svalu a průřez","Velikost síly a rameno síly","Hmotnost a teplota"],"answer":2,"exp":"Krouticí moment je součinem velikosti síly a kolmé vzdálenosti osy otáčení od nositelnosti síly (rameno síly)."},{"level":"Pokročilý","q":"Jakou kontrakci provádí hlavně m. quadriceps femoris ve fázi spouštění při dřepu?","options":["Koncentrická kontrakce","Izometrická kontrakce","Izokinetická kontrakce","Excentrická kontrakce"],"answer":3,"exp":"Při spouštění se koleno flektuje, m. quadriceps brzdí pohyb a drží tělesnou hmotnost, což je excentrická kontrakce."},{"level":"Klinický","q":"Starší pacient zavrávorá, když sahá pro předmět před sebou. Jaké je nejlepší vysvětlení z hlediska těžiště?","options":["Linie těžiště se přiblížila k okraji opěrné báze","Opěrná plocha se stala příliš širokou","Těžiště kleslo příliš níízko","Zvýšila se koncentrická kontrakce"],"answer":0,"exp":"Při natažení dopředu se linie těžiště blíží k přednímu okraji opěrné báze, čímž se snižuje stabilita."},{"level":"Klinický","q":"Zadáte pacientovi v sedě extenzi kolene se závažovou manžetou. Jak snížíte zátěž bez změny hmotnosti závaží?","options":["Umístím závaží na kotník","Umístím závaží na proximální část bérce","Zrychlím pohyb","Podržím v koncové poloze déle"],"answer":1,"exp":"Pokud posunete závaží blíže ke koleni, rameno síly se zkrátí, takže při stejné hmotnosti bude krouticí moment menší."}],"seccion":"Základy","grupo":"Základy kineziologie","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"Rozsah pohybu (goniometrie)","lead":"Při měření rozsahu pohybu (ROM) zaznamenáváme rozsah kloubního pohybu goniometrem ve stupních. To je základem posouzení poškození, stanovení cílů a hodnocení efektivity.","sheet":{"kind":"basics","items":[{"h":"Základní pravidla","t":"Neutrální nulová poloha je 0° a měření zaznamenáváme v krocích po 5°. Měříme především pasivním pohybem; pokud jste měřili aktivně, označte to zvlášť."},{"h":"Fixní a pohyblivé rameno","t":"Přiložte obě ramena goniometru k fixnímu a pohyblivému ramenu určenému pro daný kloub a jeho střed nasaďte na osu pohybu kloubu."},{"h":"Referenční hodnoty","t":"Obecné referenční hodnoty (metoda neutrální nulové polohy): flexe a abdukee ramene 180°, flexe lokte 150°, flexe kyčle 120°, abdukce 45°, flexe kolene 135°. Vždy porovnejte s opačnou stranou."},{"h":"Kompenzační pohyby","t":"Záklon trupu nebo náklon pánve poskytuje zkreslené hodnoty. Stabilně fixujte proximální část a měřte bez kompenzací."},{"h":"Konečný pocit v limitu (end feel)","t":"Zkontrolujte charakter odporu v koncovém poli (kostní, měkkotkáňový, vazivový) a bolest, a z toho usduďte na faktor omezující pohyb."},{"h":"Dokumentace, opakované měření","t":"Zaznamenejte polohu při měření, zda šlo o pasivní či aktivní měření, a úhel objevení bolesti. Opakované měření ve stejné poloze a metodou je porovnatelné."}]},"keypoints":["0° je neutrální nulová poloha, zaznamenávejte v 5° krocích","Standardně jde o pasivní měření; pokud je aktivní, označte to","Fixujte proximální část, vylučte kompenzaci","Referenční hodnota je pouze orientační, vždy ji porovnejte s kontralaterální stranou","Z koncového pocitu a bolesti usduďte na omezující faktor"],"case":{"text":"40letý muž, periarthritis humeroscapularis. Během měření flexe ramene se trup záklání a naměřená hodnota se téměř shoduje se zdravou stranou.","answer":"Hodnota je pravděpodobně příliš velká kvůli kompenzaci extenzí trupu. Fixujte trup a měřte znovu, zaznamenejte i úhel výskytu bolesti a koncový pocit. Na základě hodnoty měřené s kompenzací netvrďte, že došlo ke zlepšení."},"questions":[{"level":"Základní","q":"Jaká je referenční hodnota flexe ramene?","options":["90°","120°","150°","180°"],"answer":3,"exp":"Referenční hodnota flexe a abdukce ramene je shodně 180°."},{"level":"Základní","q":"Jaká je referenční hodnota dorzální flexe hlezna?","options":["10°","20°","30°","45°"],"answer":1,"exp":"Referenční hodnota dorzální flexe hlezna je 20° (plantární flexe 50°). Měřte vždy z neutrální nulové polohy (0°)."},{"level":"Pokročilý","q":"Který je správný základní princip měření ROM?","options":["Měříme aktivním pohybem","Zaznamenáváme v 1° krocích","Neutrální nulová poloha je 0°","Není třeba porovnávat s kontralaterální stranou"],"answer":2,"exp":"Neutrální nulová poloha je 0°; standardně měříme pasivně, v 5° krocích a porovnáváme s kontralaterální stranou."},{"level":"Pokročilý","q":"Co signalizuje v koncové poloze tvrdý, náhle se zastavující kostní koncový pocit?","options":["Svalový spazmus","Kontakt kost-kost","Napětí kloubního pouzdra","Kontakt měkkých tkání"],"answer":1,"exp":"Kostní koncový pocit je zastavení pociťované při nárazu kostí; normálně je typickým příkladem extenze lokte."},{"level":"Klinický","q":"Během měření abdukce kyčle se pánvová oblast naklání a dostanete příliš velkou hodnotu. Jaký je váš první krok?","options":["Hodnotu zaznamenám takto","Fixuji pánev a měřím znovu","Měřím aktivním pohybem","Měření ukončím"],"answer":1,"exp":"Kompenzace pánve dává příliš velký úhel abdukce. Fixujte pánev a měřte znovu."},{"level":"Klinický","q":"Po operaci kolene se v koncové poloze pasivní flexe objevuje bolest. Jaká je nejvhodnější dokumentace?","options":["Zaznamenám pouze úhel","Zaznamenám hodnotu zdravé strany","Dokud to bolí, nezaznamenávám","Zaznamenám i úhel objevení bolesti"],"answer":3,"exp":"Vedle hodnoty ROM pomáhá úhel a charakter začátku bolesti při posouzení omezujícího faktoru a při reevaluaci."}],"seccion":"Základy","grupo":"Základy kineziologie","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"Svalový test 0–5","lead":"Manuální svalový test (MMT) hodnotí svalovou sílu pomocí gravitace a manuálního odporu na šestistupňové škále 0–5. Ukazuje míru a distribuci slabosti.","sheet":{"kind":"basics","items":[{"h":"Šest stupňů","t":"0: žádná kontrakce; 1: pouze kontrakce; 2: plný ROM s eliminací gravitace; 3: plný ROM proti gravitaci; 4: proti střednímu odporu; 5: proti maximálnímu odporu, normální síla."},{"h":"Postup vyšetření","t":"Nejprve v antigravitační poloze zkontrolujte, zda pacienti zvládnou stupeň 3. Pokud ano, odporem rozhodněte o stupni 4 a 5; pokud ne, v poloze bez gravitace o stupni 2 nebo nižším."},{"h":"Způsob působení odporu","t":"Odpor působte proti směru pohybu na distální část tělesného segmentu. Zvyšujte jej postupně, nikoliv náhle, a sledujte, zda jej pacient dokáže udržet."},{"h":"Fixace a kompenzace","t":"Fixujte proximální část a sledujte, zda se neobjeví kompenzatorní pohyb jiných svalů. Pokud se pohyb provedl s kompenzací, daný stupeň nelze udělit."},{"h":"Význam stupně 3","t":"Stupeň 3 je hranicí, kde lze tělesný segment pohybovat proti vlastní váze: jedná se o „gravitační hranici“. Je směrodatný i při posouzení funkčních pohybů."},{"h":"Omezení","t":"MMT obsahuje subjektivní prvky, rozdíly nad stupeň 4 detekuje obtížně. V případě bolesti nebo patologického svalového tonusu toto rovněž zaznamenejte do nálezu."}]},"keypoints":["Nejprve zkontrolujte stupeň 3 proti gravitaci","Stupeň 3 je „gravitační hranice“","Odpor působte proti pohybu, distálně","Fixujte proximální část, nezapomeňte na kompenzaci","U onemocnění centrální nervové soustavy by MMT nemělo být jediným měřením"],"case":{"text":"70letý muž, inaktivita v důsledku hospitalizace. V sedě provádí extenzi kolene v plném rozsahu, ale mírný odpor působený na distální část bérce již nedokáže udržet.","answer":"Pohybuje se v plném ROM proti gravitaci, nikoliv však proti odporu, proto se jedná o stupeň 3. Nepůsobte náhle silným odporem a dávejte pozor na kompenzaci, například záklon trupu."},"questions":[{"level":"Základní","q":"Který stupeň: „kontrakce je viditelná, hmatatelná, ale k pohybu v kloubu nedochází“?","options":["Stupeň 0","Stupeň 1","Stupeň 2","Stupeň 3"],"answer":1,"exp":"U 1. stupně je svalová kontrakce viditelná nebo hmatatelná, ale nedochází k pohybu v kloubu."},{"level":"Základní","q":"Který stupeň: plný ROM proti gravitaci, ale nikoliv proti odporu?","options":["Stupeň 4","Stupeň 2","Stupeň 3","Stupeň 5"],"answer":2,"exp":"U 3. stupně se pohybuje v plném ROM proti gravitaci; jedná se o „gravitační hranici“."},{"level":"Pokročilý","q":"Který stupeň obvykle kontrolujeme jako první během MMT?","options":["Stupeň 1","Stupeň 5","Stupeň 0","Stupeň 3"],"answer":3,"exp":"Nejprve sledujeme stupeň 3 v antigravitační poloze; od toho se odvíjí, zda přidáme odpor, nebo přejdeme do polohy bez gravitace."},{"level":"Pokročilý","q":"Kam působíte odporem během MMT?","options":["Těsně nad kloub","Na proximální část tělesného segmentu","Na distální část tělesného segmentu","Na fixovanou část těla"],"answer":2,"exp":"Odpor působíme proti směru pohybu na distální část tělesného segmentu, kde je delší rameno páky."},{"level":"Klinický","q":"V boční leži nedokáže provést abdukci a zvednout dolní končetinu, v lehu na zádech však abdukuje v celém rozsahu pohybu (ROM). O jaký stupeň se jedná?","options":["Stupeň 1","Stupeň 2","Stupeň 3","Stupeň 4"],"answer":1,"exp":"V antigravitační poloze (v boku) to nejde, bez gravitace (v lehu na zádech) v plném ROM ano: stupeň 2."},{"level":"Klinický","q":"Měřili byste sílu horní končetiny u silně spastického hemiparetického pacienta. Jaký je nejlepší přístup?","options":["MMT je samo o sobě obtížně hodnotitelné","Stupeň 5 by měl být vaším cílem","Rozhoduji na základě silného odporu","Zdravou stranu není nutné vyšetřovat"],"answer":0,"exp":"U onemocnění centrální nervové soustavy nejsou kvůli svalovému tonu a synergiím splněny podmínky pro MMT; k hodnocení parézy použijte jinou škálu."}],"seccion":"Základy","grupo":"Základy kineziologie","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"Anamnéza","lead":"Během anamnézy se zeptejte na průběh a charakter potíží i životní podmínky pacienta a stanovte hypotézu. Ta určuje výběr dalších vyšetření a bezpečnostní screening.","sheet":{"kind":"basics","items":[{"h":"Cíl","t":"Z hlavní obtíže a průběhu stanovíme hypotézu a seřadíme vyšetření podle priorit. Mezitím také screeningově sledujeme varovné příznaky vyžadující odeslání k lékaři."},{"h":"Hlavní obtíž, nynější onemocnění","t":"Zaznamenejte hlavní obtíž slovy pacienta. Zeptejte se na začátek a vyvolávající příčinu (trauma nebo pozvolný nástup) a následně na průběh (zlepšuje se, zhoršuje se, beze změny)."},{"h":"Vyšetření bolesti","t":"Upřesněte místo, charakter a intenzitu bolesti (např. NRS), zhoršující a zmírňující faktory, denní fluktuaci a noční bolest."},{"h":"Anamnéza, léky","t":"Zeptejte se na dřívější onemocnění, operace, komorbidity a užívané léky. Užívání antikoagulancií a kortikosteroidů vyžaduje při terapii opatrnost."},{"h":"Životní podmínky","t":"Zeptejte se na práci, rodinnou roli, bytové podmínky a aktivitu. Do stanovení cílů zahrňte potřeby a cíle pacienta a jeho rodiny."},{"h":"Tazatelská technika","t":"Začněte otevřenými otázkami, uzavřenými otázkami upřesněte detaily. Vyhněte se odborným termínům; shrnutím a zopakováním předejdete nedorozuměním."}]},"keypoints":["Zaznamenejte hlavní obtíž vlastními slovy pacienta","Vždy se zeptejte na vyvolávající příčinu a průběh","Sledujte varovné příznaky: noční bolest, úbytek hmotnosti","Léky (např. antikoagulancia) vyžadují opatrnost","Začněte otevřenou otázkou, uzavřenou upřesněte"],"case":{"text":"55letý muž, bolesti v bederní oblasti trvající 2 měsíce. Uvádí: „V poslední době nemohu kvůli bolesti spát ani v noci. Přitom jsem nic nedělal, a přesto jsem zhubnul 5 kilo.“","answer":"Noční bolest neustupující v klidu a nevysvětlitelný úbytek hmotnosti jsou červenými vlajkami. Před zahájením pohybové terapie to nahlaste a konzultujte s lékařem. Varovný příznak nalezený v anamnéze nesmí být přehlušen pozdějším výsledkem vyšetření."},"questions":[{"level":"Základní","q":"Na co se zeptáte jako první a zaznamenáte to vlastními slovy pacienta?","options":["Dřívější onemocnění","Hlavní obtíž","Rodinná anamnéza","Léky"],"answer":1,"exp":"Hlavní obtíž je to, co pacienta trápí nejvíce; zaznamenáváme ji bez interpretace, vlastními slovy pacienta."},{"level":"Základní","q":"Kterou metodou požádáte pacienta, aby označil intenzitu bolesti číslem 0–10?","options":["MMT","ROM","NRS","ADL"],"answer":2,"exp":"NRS (numerická škála bolesti) vyjadřuje intenzitu bolesti číslem 0–10."},{"level":"Pokročilý","q":"Která otázka je otevřená?","options":["„Bolí vás to na pravé straně?“","„Bolí vás to v noci?“","„Užíváte nějaké léky?“","„Kdy vás to obvykle bolí?“"],"answer":3,"exp":"Na otevřenou otázku nelze odpovědět ano nebo ne, takže získáte od pacienta více informací."},{"level":"Pokročilý","q":"Kterou informaci musíte v anamnéze obzvláště objasnit, protože vyžaduje opatrnost při léčbě?","options":["Užívání antikoagulancií","Dominantní ruka","Způsob docházení do práce","Koníčky"],"answer":0,"exp":"Antikoagulační léčba s sebou nese riziko krvácení a hematomů, proto vyžaduje opatrnost, například při manuálních technikách."},{"level":"Klinický","q":"Pacient s bolestmi zad: „Nemohu ani spát bolestí a zhubnul jsem 5 kilo.“ Jaký je nejvhodnější postup?","options":["Okamžitě zahájím pohybovou terapii","Budu sledovat průběh pomocí tepelné terapie","Nahlásím to a projednám to s lékařem","Počkám do příští návštěvy"],"answer":2,"exp":"Noční bolest neustupující v klidu a nevysvětlitelný úbytek hmotnosti jsou červené vlajky; před zahájením terapie se poradit s lékařem."},{"level":"Klinický","q":"70letá žena s osteoporózou. Od pádu ji bolí kyčel a nemůže chodit. Co vás napadne jako první?","options":["Bolest způsobená svalovou slabostí","Možnost zlomeniny","Zhoršení artrózy","Psychické faktory"],"answer":1,"exp":"U osteoporózy v případě bolesti a neschopnosti chůze po pádu myslete na zlomeninu a na prvním místě je lékařské vyšetření."}],"seccion":"Základy","grupo":"Vyšetření","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"Červené vlajky","lead":"Červené vlajky jsou varovné příznaky, které mohou poukazovat na závažné, skryté onemocnění. Pokud je zaznamenáte, před pokračováním fyzioterapie se poraďte s lékařem.","sheet":{"kind":"basics","items":[{"h":"Definice","t":"Příznaky poukazující na urgentní stav (nádor, infekce, zlomenina, syndrom cauda equina). Samostatně méně, při společném výskytu mají větší závažnost."},{"h":"Nádor","t":"Zeptejte se na dřívější onkologické onemocnění, nevysvětlitelný úbytek hmotnosti a noční bolest neustupující v klidu. Vezměte v úvahu také věk a celkový stav."},{"h":"Infekce","t":"Věnujte pozornost bolesti zad provázené horečkou, imunokompromitovanému stavu, nedávné infekci nebo invazivnímu zákroku."},{"h":"Zlomenina","t":"Po silném traumatu, případně u osteoporózy již po menším pádu myslete na zlomeninu. Zeptejte se také na dlouhodobé užívání kortikosteroidů."},{"h":"Syndrom cauda equina","t":"Poruchy močení a defekace, ztráta citlivosti v sedlové oblasti a progredující slabost dolních končetin jsou urgentní stav: okamžitě informujte lékaře."},{"h":"Postup","t":"Zdokumentujte nález i průběh, nahlaste je a konzultujte s lékařem. Pacienta nestraště; klidně mu vysvětlete, proč je nutné lékařské vyšetření."}]},"keypoints":["Noční bolest, která neustupuje ani v klidu, je varovným signálem.","Nevysvětlitelný úbytek hmotnosti může ukazovat na nádorové onemocnění.","Poruchy močení a stolice, hypestezie v sedlové oblasti: urgentní stav","V případě úrazu nebo osteoporózy myslete na zlomeninu.","Při výskytu červené vlajky před zahájením terapie vše konzultujte s lékařem."],"case":{"text":"45letá žena, bolest v bederní oblasti a bolest pravé dolní končetiny. Uvádí, že od dnešního rána má potíže s močením a cítí mravenčení v okolí konečníku.","answer":"Poruchy močení a stolice a porucha citlivosti v sedlové oblasti ukazují na syndrom caudy equinae. Nepokračujte ve vyšetření ani ve cvičení, okamžitě informujte lékaře. Přístup „vyčkejme a uvidíme“ je zde nepřípustný."},"questions":[{"level":"Základní","q":"Která červená vlajka se pojí s bolestí zad?","options":["Bolest beder zhoršující se pohybem","Nevysvětlitelný úbytek hmotnosti","Bolest zhoršující se dlouhým sezením","Svalová bolest po tréninku"],"answer":1,"exp":"Nevysvětlitelný úbytek hmotnosti je jednou z červených vlajek, může ukazovat na nádorové onemocnění."},{"level":"Základní","q":"Jaký je správný postup při zjištění červené vlajky?","options":["Budu pokračovat se sníženou intenzitou","Přejdu na fyzikální terapii","Počkám do příští návštěvy","Před léčbou se poradím s lékařem"],"answer":3,"exp":"V případě červené vlajky se před pokračováním v cvičení poradíte s lékařem."},{"level":"Pokročilý","q":"Která dvojice nálezů ukazuje na syndrom caudy equinae?","options":["Poruchy močení a stolice a výpadek citlivosti v sedlové oblasti","Bolest krku a tuhost ramen","Otok kolene a bolest při chůzi po schodech","Noční bolest ramene a omezení zvedání paže"],"answer":0,"exp":"Poruchy močení a stolice a výpadek citlivosti v sedlové oblasti (hráz, okolí konečníku) jsou urgentním známkama komprese caudy equinae."},{"level":"Pokročilý","q":"V jaké situaci nejvíce pomýšlíte na zlomeninu?","options":["Napětí v bederní oblasti po práci v kanceláři","Svalová bolest po tréninku","Bolest zad u pacienta s osteoporózou po pádu","Tuhost kolen objevující se v chladných dnech"],"answer":2,"exp":"Při osteoporóze se kost může zlomit i při malém působení síly, proto při bolesti po pádu myslete na zlomeninu."},{"level":"Klinický","q":"Pacient s bolestmi beder: „Od dnešního rána se mi špatně močí a mravenčí mě kolem konečníku.“ Co je vaším úkolem?","options":["Dokončím vyšetření","Zahájím cvičení na stabilizaci trupu","Okamžitě informuji lékaře","Budu vývoj sledovat jeden týden"],"answer":2,"exp":"Poruchy močení a stolice a porucha citlivosti v sedlové oblasti ukazují na syndrom caudy equinae: okamžitě informujte lékaře."},{"level":"Klinický","q":"68letý muž, v anamnéze onkologické onemocnění. Již měsíc má noční bolesti zad, které neustupují ani v klidu. Jaký je váš závěr?","options":["Bolest způsobená vadným držením těla","Příznak vyžadující konzultaci s lékařem","Bolest zlepšující se posilováním","Bolest zvládnutelná termoterapií"],"answer":1,"exp":"Nádorová anamnéza a noční bolest neustupující v klidu nevylučují metastázu, proto je nutná konzultace s lékařem."}],"seccion":"Základy","grupo":"Vyšetření","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"Vyšetření postoje","lead":"Během vyšetření postoje ve stoji a v sedě sledujte linii těla a hledejte vodítka k danému problému. Souvislost s příznaky je vždy nutné potvrdit dalšími vyšetřeními.","sheet":{"kind":"basics","items":[{"h":"Cíl","t":"Vyhodnotíme odchylky držení těla a vytvoříme hypotézu o jejich vztahu ke zkrácení svalů, svalové slabosti a bolesti."},{"h":"Referenční bod při pohledu z boku","t":"V ideálním stoji prochází linie těžiště ušním lalůčkem, akromionem, velkým trochanterem, přední částí kolenního kloubu (za patellou) a před vnějším kotníkem."},{"h":"Pohled zezadu","t":"Sledujte sklon hlavy, výšku ramen a pánve, boční odchylku páteře a asymetrii dolních končetin. V případě potřeby zkontrolujte i v předklonu."},{"h":"Vadné držení těla","t":"Patří sem kulatá záda, předsunuté držení hlavy, držení těla se zvýšeným náklonem pánve a bederní lordózou a plochá záda. Hodnoťte společně se zkrácením či oslabením postižených svalů."},{"h":"Interpretace","t":"Mnoho lidí má odchylky držení těla bez příznaků, proto nález sám o sobě nedokazuje příčinu bolesti. Ověřte pomocí vyšetření ROM a svalové síly."},{"h":"Dokumentace","t":"Zaznamenejte směr pozorování, polohu těla a pozici orientačních bodů. U fotografie pořiďte snímek vždy za stejných podmínek pro porovnání."}]},"keypoints":["Pozorujte z boku, zezadu i zepředu","Linie těžiště prochází přes ušní lalůček, akromion a velký trochanter","Zezadu sledujte stranový rozdíl ve výšce ramen a pánve","Při předklonu poukazuje žebrový hrb na strukturální skoliózu","Na základě postury nestanovujte příčinu bolesti"],"case":{"text":"30letá žena, kancelářská práce. Má bolesti krku, při pohledu z boku je ušní lalůček jednoznačně před akromionem.","answer":"Toto je předsunuté držení hlavy. Na základě postury však nestanovujte příčinu: vyšetřete krční ROM, pohyby vyvolávající příznaky a neurologické známky (mravenčení, slabost). Při neurologických příznacích se poraďte s lékařem."},"questions":[{"level":"Základní","q":"Kudy prochází linie těžiště při pohledu z boku v ideálním stoji?","options":["Po špičce nosu","Po dolním úhlu lopatky","Přes ušní lalůček","Po zadním okraji patní kosti"],"answer":2,"exp":"V ideálním případě prochází linie těžiště ušním lalůčkem, akromionem, velkým trochanterem, přední částí kolene a před vnějším kotníkem."},{"level":"Základní","q":"Co vyšetřujete hlavně při pohledu zezadu?","options":["Předsunuté držení hlavy","Výškový rozdíl ramen a pánve","Míru bederní lordózy","Hyperextenzi kolene"],"answer":1,"exp":"Zezadu sledujeme stranové rozdíly: výšku ramen a pánve, boční odchylku páteře."},{"level":"Pokročilý","q":"Co platí pro čáru těžiště při bočním pohledu v ideálním postoji?","options":["Prechází za zevním kotníkem","Pochází za kolenním kloubem","Prochází vnitřním okrajem lopatky","Prochází přes trochanter major"],"answer":3,"exp":"Čára těžiště prochází přes trochanter major, přední část kolenního kloubu a před zevní kotník."},{"level":"Pokročilý","q":"Jaká je správná interpretace vyšetření držení těla?","options":["Odchylka je příčinou bolesti","Souvislost potvrdím dalším vyšetřením","Stačí pozorovat z jednoho směru","Fotografie pořizuji vždy za jiných podmínek"],"answer":1,"exp":"Odchylka držení těla se vyskytuje i u bezpříznakových osob, proto souvislost ověřte vyšetřením ROM a svalové síly."},{"level":"Klinický","q":"U pacienta s bolestmi krční páteře je ušní lalůček zřetelně před acromiem. Jaký je nejvhodnější další krok?","options":["Vyšetřím krční ROM a neurologické příznaky","Poskytnu pouze rady pro správné držení těla","Okamžitě aplikuji trakci","Průběh pouze sleduji"],"answer":0,"exp":"Předsunuté držení hlavy je pouze vodítko. Vyšetřete ROM a neurologické příznaky a vyhodnoťte souvislost s příznaky."},{"level":"Klinický","q":"Zezadu je vidět výškový rozdíl ramen a pánve, při předklonu jednostranný žeberní hrb. Na co pomyslíte?","options":["Předsunuté držení hlavy","Kulatá záda","Strukturální skolióza","Plochá záda"],"answer":2,"exp":"Žeberní hrb viditelný při předklonu poukazuje na strukturální skoliózu doprovázenou rotací obratlů; je nutné lékařské vyšetření."}],"seccion":"Základy","grupo":"Vyšetření","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"Analýza chůze","lead":"Během analýzy chůze sledujeme v jednotlivých fázích cyklu chůze kloubní pohyby a svalovou funkci a identifikujeme problém. To dává směr prevenci pádů a zlepšení pohybu.","sheet":{"kind":"basics","items":[{"h":"Cyklus chůze","t":"Jeden cyklus trvá od počátečního dopadu jedné nohy po další dopad téže nohy. Dělí se na stojnou a švihovou fázi a obsahuje dvě fáze oboustranné opory."},{"h":"Fáze","t":"Stojná fáze: počáteční dopad, akceptace zátěže, střední a konečná stojná fáze, předšvihová fáze. Švihová fáze: časná, střední a pozdní švihová fáze."},{"h":"Postup vyšetření pozorováním","t":"Zkontrolujte chůzi zepředu, zezadu a z boku, přičemž se soustřeďte vždy na jeden kloub nebo fázi. Zaznamenejte rychlost, délku kroku, rytmus a případné pomůcky."},{"h":"Typické patologické stereotypy chůze","t":"Trendelenburgova chůze (m. gluteus medius), steppáž (kompenzace padající špičky nohy), cirkumdunkce, freezing (porucha startu chůze), chůze s drobnými kroky."},{"h":"Svalová činnost","t":"Při akceptaci zátěže brzdí m. quadriceps excentricky flexi v koleni a m. tibialis anterior pokles nohy. V konečné stojné fázi pracuje m. triceps surae."},{"h":"Měřitelná vyšetření","t":"Pomocí 10metrového testu chůze a testu TUG můžete kvantifikovat rychlost a mobilitu. Spolu s pozorováním posoudíte také riziko pádu."}]},"keypoints":["Jeden cyklus: od dopadu po další dopad téže nohy","Stojná fáze cca 60 %, švihová fáze cca 40 %","Sledujte ze tří směrů, vždy na jeden bod","Při Trendelenburgově chůzi myslete na m. gluteus medius","Steppáž je kompenzací padající špičky nohy (slabý m. tibialis anterior)"],"case":{"text":"60letý muž, obrna n. peroneus. Ve švihové fázi silně flexuje kyčel a koleno, našlapuje vysoko. Stále častěji zakopává.","answer":"Jedná se o steppáž kompenzující padající špičku. Vyšetřete svalovou sílu dorzální flexe, citlivost a riziko pádu. Ortézu konzultujte s lékařem a ortopedickým protetikem, nerozhodujte sami."},"questions":[{"level":"Základní","q":"Přibližně jakou část chůzového cyklu tvoří stojná fáze?","options":["Cca 40 %","Cca 50 %","Cca 60 %","Cca 80 %"],"answer":2,"exp":"Při normální chůzi tvoří stojná fáze cca 60 % a švihová fáze cca 40 %."},{"level":"Základní","q":"Ve které fázi nese tělesnou hmotnost na jedné noze a těžiště je nejvýše?","options":["Počáteční kontakt s podložkou","Střední stojná fáze","Předšvihová fáze","Střední švihová fáze"],"answer":1,"exp":"Ve střední stojné fázi přechází tělo nad opěrnou nohou, tehdy je těžiště nejvýše."},{"level":"Pokročilý","q":"Který sval excentricky brzdí flexi v koleni při akceptaci zátěže?","options":["M. quadriceps femoris","Hamstringy","M. iliopsoas","M. triceps surae"],"answer":0,"exp":"Při akceptaci zátěže se koleno mírně flexuje ke tlumení nárazu, což excentricky brzdí m. quadriceps."},{"level":"Pokročilý","q":"Z achylické slabosti kterého svalu máte podezření při Trendelenburgově chůzi?","options":["M. gluteus maximus","M. quadriceps femoris","M. tibialis anterior","M. gluteus medius"],"answer":3,"exp":"Při slabosti m. gluteus medius dochází ve stojné fázi k poklesu pánve na straně švihu: Trendelenburgovo znamení."},{"level":"Klinický","q":"Ve švihové fázi nadměrně flektuje kyčel a koleno, přičemž došlapuje vysoko. Jaká může být příčina?","options":["Slabost m. quadriceps","Slabost m. tibialis anterior","Slabost m. gluteus medius","Slabost m. gluteus maximus"],"answer":1,"exp":"Při slabosti m. tibialis anterior nožka padá; aby se prsty nezachytávaly o zem, pacient ji vysoko zvedá: kohoutí chůze."},{"level":"Klinický","q":"U pacienta s Parkinsonovou nemocí se zdá, že se noha při zahájení chůze a otáčení přilepila k podlaze a nechce vykročit. Co to je?","options":["Cirkumdukční chůze","Kohoutí chůze","Zablokování chůze (freezing)","Kachní chůze"],"answer":2,"exp":"Freezing je typický pro Parkinsonovu nemoc; projevuje se zejména při zahájení chůze, otáčení a ve stísněných prostorech."}],"seccion":"Základy","grupo":"Vyšetření","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"Neurologické vyšetření","lead":"Během neurologického vyšetření vyšetřujeme po segmentech čití, svalovou sílu a reflexy a usuzujeme na místo a úroveň poškození. Je rovněž nepostradatelné pro včasné odhalení progredujících neurologických příznaků.","sheet":{"kind":"basics","items":[{"h":"Cíl","t":"Společným hodnocením nálezů čití, svalové síly a reflexů určíme, zda se poškození nachází v periferním nervu, kořenu, míchě nebo v mozku."},{"h":"Vyšetření čití","t":"Zkontrolujte dotek, vnímání bolesti, tepla, polohy a vibrací a podél dermatomů porovnejte obě strany a také proximální a distální část."},{"h":"Indikační svaly","t":"C5: abdukce ramene; C6: dorzální flexe (extenze) zápěstí; C7: extenze lokte; L4: dorzální flexe hlezna; L5: extenze palce nohy; S1: plantární flexe hlezna."},{"h":"Hluboké reflexy","t":"Základní reflexy: bicipitální reflex (C5), brachioradiální reflex (C6), tricipitální reflex (C7), patelární reflex (L4), Achillův reflex (S1)."},{"h":"Horní a dolní motoneuron","t":"Při poškození horního motoneuronu jsou vidět zvýšené šlachové reflexy a patologické reflexy, při poškození dolního motoneuronu oslabené nebo nevýbavné reflexy a svalová atrofie."},{"h":"Varování","t":"V případě rychle se zhoršující svalové síly, šířící se poruchy čití nebo potíží s močením a stolicí neprodleně informujte lékaře. Nálezy včas dokumentujte."}]},"keypoints":["Čití, sílu a reflexy vždy porovnejte na obou stranách","Patelární reflex: L4, Achillův reflex: S1","L5 posuďte na základě síly extenze palce a čití","Zvýšený reflex a patologický reflex: horní motoneuron","Při progredující svalové slabosti okamžitě informujte lékaře"],"case":{"text":"50letý muž, bolesti v kříži, mravenčení od vnější strany pravého bérce po hřbet nohy. Na pravé straně je oslabená extenze palce, na patelárním a Achillově reflexu není rozdíl mezi stranami.","answer":"Je pravděpodobné poškození nervového kořene L5. L5 nemá typický šlachový reflex, proto se rozhodujete na základě čití a síly extenze palce. V případě zhoršující se svalové síly nebo potíží s močením či stolicí okamžitě informujte lékaře."},"questions":[{"level":"Základní","q":"Který patologický reflex poukazuje na poškození horního motoneuronu?","options":["Patelární reflex","Břišní reflex","Babinského reflex","Rohovkový reflex"],"answer":2,"exp":"Babinského reflex je patologický reflex: při podráždění plosky nohy jde palec do dorzální flexe; ukazuje na poškození horního motoneuronu."},{"level":"Základní","q":"Při kterém vyšetření porovnáváte obě strany podél dermatomů?","options":["Šlachové reflexy","Vyšetření čití","MMT","Měření ROM"],"answer":1,"exp":"Dermatotem je oblast kůže inervovaná jednotlivými segmenty; při vyšetření citlivosti porovnáváme strany mezi sebou a proximodistálně."},{"level":"Pokročilý","q":"Který segment odráží především Achillův reflex?","options":["L3","L4","L5","S1"],"answer":3,"exp":"Achillův reflex odráží hlavně segment S1, patelární reflex hlavně segment L4."},{"level":"Pokročilý","q":"Který nález odpovídá poškození dolního motoneuronu?","options":["Zvýšené šlachové reflexy","Pozitivní patologický reflex","Svalová atrofie","Spasticita"],"answer":2,"exp":"Při poškození dolního motoneuronu jsou patrné oslabené nebo vyhaslé šlachové reflexy, svalová atrofie a snížený svalový tonus."},{"level":"Klinický","q":"Brnění od vnější strany bérce až po hřbet nohy, oslabená extenze palce, v reflexech není stranový rozdíl. Jaká je úroveň poškození?","options":["L3","L4","L5","S1"],"answer":2,"exp":"Citlivost od vnější strany bérce po hřbet nohy a extenze palce je nález pro L5. L5 nemá typický šlachový reflex."},{"level":"Klinický","q":"Při bolesti krku a brnění obou rukou jsou na dolních končetinách zvýšené šlachové reflexy a je pozitivní Babinského příznak. Co předpokládáte?","options":["Poškození krční míchy (myelopatie)","Poškození jednoho nervového kořene","Syndrom karpálního tunelu","Myofasciální bolest"],"answer":0,"exp":"Zvýšené reflexy na dolních končetinách a patologický reflex značí poškození horního motoneuronu; myslete na kompresi krční míchy a odešlete pacienta k lékaři."}],"seccion":"Základy","grupo":"Vyšetření","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"Rotátorová manžeta","lead":"Rotátorová manžeta jsou šlachy čtyř svalů, které stabilizují ramenní kloub. Odlišení pomocí testů, který sval je poškozen, je výchozím bodem vyšetření a fyzioterapie.","sheet":{"kind":"tests","tests":[{"name":"Jobeův test","alias":"Empty can test","steps":"Pacient drží paži v rovině lopatky v 90° abdukci, vnitřní rotaci a s palcem směřujícím dolů; vyšetřující klade odpor shora dolů.","positive":"Bolest nebo slabost: pacient neudrží paži proti odporu","tissue":"m. supraspinatus","point":"Bolest a slabost zaznamenejte odděleně. Při impingementu může také způsobovat bolest."},{"name":"Zevní rotace proti odporu","alias":"","steps":"S loktem ohnutým v 90° a paží podél těla pacient rotuje zevně; vyšetřující klade odpor na předloktí směrem dovnitř.","positive":"Bolest při zevní rotaci nebo síla jednoznačně menší než na zdravé straně","tissue":"m. infraspinatus a m. teres minor","point":"Pokud pacient neudrží pasivně nastavenou zevní rotaci (external rotation lag), myslete na rozsáhlou rupturu."},{"name":"Lift-off test","alias":"Gerberův lift-off test","steps":"Pacient má hřbet ruky opřený o bedra; požádejte ho, aby odtáhl ruku dozadu od zad.","positive":"Nedokáže odtáhnout ruku od zad nebo se objeví bolest","tissue":"m. subscapularis","point":"Pokud ruka nedosáhne za záda kvůli chybějícímu ROM vnitřní rotace, nahraďte test belly press testem."},{"name":"Drop arm test","alias":"","steps":"Vyšetřující pasivně zvedne paži do cca 90° abdukce, poté ji pacient pomalu spouští.","positive":"Během spouštění ji nedokáže udržet a paže spadne, nebo silná bolest","tissue":"Ruptura rotátorové manžety (zejména m. supraspinatus)","point":"Znamení poukazující na velkou rupturu. Nestanovujte diagnózu sami; porovnejte s dalšími testy a zobrazením."}]},"keypoints":["Bolest a slabost zaznamenejte zvlášť a vždy porovnejte se zdravou stranou","Jobeův test vyšetřuje m. supraspinatus v rovině lopatky s palcem směřujícím dolů","Zevní rotace proti odporu: m. infraspinatus a teres minor; lift-off: m. subscapularis","Nevvozujte konečný závěr z jediného testu; kombinujte nálezy","Pokud pacient po traumatu náhle nedokáže zvednout paži, odesílejte ho k lékařskému vyšetření"],"case":{"text":"58letý muž. Upadl a opřel se o pravou ruku, od té doby nedokáže zvednout pravé rameno. Pasivní ROM je téměř zachován, aktivní zvedání je obtížné. Jobeův test: slabost; drop arm test pozitivní.","answer":"Jelikož je pasivní ROM zachován a obtížný je pouze aktivní pohyb, myslete spíše na rupturu rotátorové manžety než na kontrakturu. Na základě testů nestanovujte diagnózu; odešlete pacienta k lékařskému vyšetření a zobrazovacímu vyšetření. Vyhněte se opakování silných odporových cvičení vyvolávajících bolest."},"questions":[{"level":"Základní","q":"Který sval vyšetřuje především Jobeův test (90° v rovině lopatky, palec směřující dolů)?","options":["m. supraspinatus","m. infraspinatus","m. subscapularis","m. teres minor"],"answer":0,"exp":"V abdukci 90° v rovině lopatky s palcem směřujícím dolů a odporem vyšetřujeme m. supraspinatus."},{"level":"Základní","q":"Který sval vyšetřuje Gerberův lift-off test, ve kterém se má hřbet ruky přiložený k bedrům odtáhnout?","options":["m. teres major","m. supraspinatus","m. subscapularis","m. deltoideus"],"answer":2,"exp":"Odtáhnutí ruky od zad je vnitřní rotace, takže se vyšetřuje hlavní vnitřní rotátor, m. subscapularis."},{"level":"Pokročilý","q":"Co vyšetřuje zevní rotace prováděná proti odporu s loktem ohnutým v úhlu 90° a visící paží?","options":["Pouze m. supraspinatus","m. infraspinatus a m. teres minor","m. subscapularis","Dlouhou hlavu m. biceps brachii"],"answer":1,"exp":"Zevní rotace proti odporu ukazuje bolest a slabost zevních rotátorů, m. infraspinatus a m. teres minor."},{"level":"Pokročilý","q":"Na co nejvíce poukazuje pozitivní drop arm test?","options":["Přední nestabilita ramene","Tendinitida dlouhé hlavy bicep","Poškození akromioklavikulárního kloubu","Ruptura rotátorové manžety"],"answer":3,"exp":"Pokud pacient nedokáže pomalu spustit zvednutou paži a ta spadla, poukazuje to na rupturu rotátorové manžety (zejména m. supraspinatus)."},{"level":"Klinický","q":"62letá žena. Dokáže dát ruku za záda, ale nedokáže ji odtáhnout od zad. Zevní rotace proti odporu je normální. Kde je poranění nejpravděpodobnější?","options":["m. supraspinatus","m. subscapularis","m. infraspinatus","m. teres minor"],"answer":1,"exp":"Lift-off test je pozitivní, zevní rotace je normální. Nejvíce myslíme na poškození vnitřního rotátoru m. subscapularis."},{"level":"Klinický","q":"65letý muž, obtížně zvedá rameno. Pasivní ROM je zachován, na Jobeově testu výrazná slabost. Jaký je nejvhodnější postup?","options":["Zahájení posilování s maximálním odporem","Informování a žádost o lékařské vyšetření","Opakování intenzivního protahování","Doporučení vyčkat"],"answer":1,"exp":"Existuje podezření na rupturu rotátorové manžety; pro diagnostiku a plán je nutné lékařské vyšetření a zobrazovací metody. Vyhněte se vysoké zátěži."}],"seccion":"Speciální testy podle regionů","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"Jobeův test","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"Jobeův test","rotulo":"Vyšetřuje","texto":"m. supraspinatus","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"Impingement a instabilita","lead":"Bolest při zvedání ukazuje na subakromiální impingement, pocit nejistoty při zevní rotaci na přední instabilitu. Je důležité, abyste bolest a pocit nejistoty odlišili.","sheet":{"kind":"tests","tests":[{"name":"Neerův test","alias":"Neerův impingement příznak","steps":"Fixujte lopatku shora a s paží ve vnitřní rotaci pasivně maximálně elevujte horní končetinu.","positive":"Bolest v přední-horní části ramene při zvedání","tissue":"Subakromiální rotátorová manžeta a burza","point":"Tuberculum majus se vtlačuje pod akromion a způsobuje bolest. Ani pozitivní test neurčí, zda je přítomna ruptura."},{"name":"Hawkinsův–Kennedyho test","alias":"","steps":"Rameno a loket v 90° flexi; vyšetřující tlačí předloktí dolů a pasivně provádí vnitřní rotaci ramene.","positive":"Bolest při vnitřní rotaci v přední-horní nebo boční části ramene","tissue":"Šlacha m. supraspinatus a subakromiální burza","point":"Hodnoťte společně s Neerovým testem. Zkontrolujte místo bolesti a její reprodukovatelnost."},{"name":"Apprehension test","alias":"Přední apprehension test","steps":"Vleže na zádech, rameno v 90° abdukci, loket v 90° flexi; vyšetřující pomalu provádí zevní rotaci ramene.","positive":"Strach z vykloubení, obranné svalové napětí","tissue":"Přední pouzdro ramenního kloubu a labrum","point":"Nerozhoduje bolest, ale pocit nejistoty. Po luxaci provádějte pomalu a šetrně."},{"name":"Relocation test","alias":"","steps":"V pozici apprehension testu tlačte hlavici humeru zepředu dozadu a proveďte zevní rotaci.","positive":"Pocit nejistoty se snižuje a zevní rotaci lze dále zvětšit","tissue":"Přední instabilita ramenního kloubu","point":"Proveďte po apprehension testu; změna nejistoty potvrzuje přední instabilitu."}]},"keypoints":["Neerův a Hawkinsův–Kennedyho test vyšetřují bolest při subakromiálním impingementu","U testů instability je výskyt pocitu nejistoty důležitější než bolest","Ani pozitivní test neukáže, zda je přítomna ruptura rotátorové manžety a jak je velká","Ve stavu po luxaci provádějte zevní rotaci pomalu, bez násilí","Anamnézu, další testy a zobrazovací metody vyhodnoťte společně"],"case":{"text":"19letý ragbista. Při skládce byla jeho paže vynuceně uvedena do abdukce a zevní rotace; od té doby má v této pozici pocit, že mu rameno „vypadává“. Apprehension test vyvolává pocit nejistoty, relocation test jej snižuje.","answer":"Nálezy svědčící pro přední nestabilitu ramene; odlište od bolesti při impingementu. Vyhněte se pohybům vynucujícím abdukci a zevní rotaci; na základě lékařského vyšetření postupujte stabilizací rotátorové manžety a periskapulárních svalů."},"questions":[{"level":"Základní","q":"Která struktura je nejčastěji utlačována při subakromiálním impingementu?","options":["Šlacha m. triceps brachii","m. teres major","Šlacha m. supraspinatus","m. latissimus dorsi"],"answer":2,"exp":"Při elevaci dochází pod akromionem k útlaku šlachy m. supraspinatus a subakromiální bursy, což způsobuje bolest."},{"level":"Základní","q":"Jaký pohyb provádíte ramenem při Hawkins–Kennedyho testu?","options":["Vnitřní rotace v 90° flexi","Zevní rotace s paží podél těla","Horizontální abdukce","Extenze"],"answer":0,"exp":"Pasivní vnitřní rotace z 90° flexe ramene a lokte vtlačuje tuberculum majus pod korakoakromiální oblouk."},{"level":"Pokročilý","q":"Co je pozitivním nálezem apprehension testu?","options":["Bolest v přední horní části ramene při elevaci","Strach z vykloubení","Bolest při flexi lokte","Pokles paže"],"answer":1,"exp":"Strach z vykloubení nebo obranné svalové napětí při abdukci a zevní rotaci je pozitivní a svědčí pro přední nestabilitu."},{"level":"Pokročilý","q":"Na co ukazuje, pokud se při relocation testu sníží pocit nejistoty?","options":["Ruptura rotátorové manžety","Poškození akromioklavikulárního skloubení","Zmrzlé rameno","Přední nestabilita ramene"],"answer":3,"exp":"Pokud se při tlaku na hlavici humeru směrem dozadu sníží nejistota, potvrzuje to přední nestabilitu."},{"level":"Klinický","q":"45letý muž, bolest ramene v přední horní části při práci nad hlavou. Neerův a Hawkinsův test jsou bolestivé, síla je zachována. Co je nejpravděpodobnější?","options":["Přední nestabilita","Subakromiální impingement","Cervikální radikulopatie","Akromioklavikulární luxace"],"answer":1,"exp":"Na základě bolesti v přední horní části při elevaci a vnitřní rotaci a zachované síly je nejpravděpodobnější subakromiální impingement."},{"level":"Klinický","q":"20letá žena měla dvakrát přední luxaci ramene. Co je nejvhodnější při provádění apprehension testu?","options":["Rychle provést maximální zevní rotaci","Přestat, jakmile se objeví nejistota","Pokračovat v zevní rotaci až do bolesti","Provádět švihem"],"answer":1,"exp":"Cílem je zaznamenat pocit nejistoty, proto při jeho výskytu přestaňte. Při násilném provedení hrozí riziko reluxace."}],"seccion":"Speciální testy podle regionů","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"Neerův test","img":"img/fichas/neer.jpg"},{"nombre":"Hawkinsův–Kennedyho test","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"Biceps a labrum glenoidale","lead":"Šlacha dlouhé hlavy m. biceps brachii probíhá v sulcus intertubercularis a upíná se na horní labrum. Při hodu a tahu se často poškodí; šlachu a labrum vyšetřujte odděleně.","sheet":{"kind":"tests","tests":[{"name":"Speedův test","alias":"","steps":"S nataženým loktem a supinovaným předloktím pacient provádí flexi ramene; vyšetřující klade odpor proti směru dolů na předloktí.","positive":"Bolest v oblasti sulcus intertubercularis","tissue":"Šlacha dlouhé hlavy m. biceps brachii","point":"Poškození horního labra může také způsobit bolest. Vyhodnoťte spolu s citlivým bodem na tlak."},{"name":"Yergasonův test","alias":"","steps":"S 90° flexí v lokti a předloktím v pronaci pacient supinuje předloktí proti odporu vyšetřujícího.","positive":"Bolest v sulcus intertubercularis nebo pocit vyskakování šlachy","tissue":"Šlacha dlouhé hlavy a lig. transversum humeri","point":"Subluxaci šlachy může doprovázet loupnutí. Vždy zkontrolujte místo bolesti."},{"name":"O’Brienův test","alias":"Aktivní kompresní test","steps":"Rameno v 90° flexi, mírné horizontální addukci, s palcem dolů zatlačte dolů; poté opakujte s dlaní nahoru.","positive":"Palec dolů: hluboká bolest nebo loupnutí; dlaň nahoru: poleaví","tissue":"Horní labrum a akromioklavikulární kloub","point":"Bolest na vrcholu ramene poukazuje na AC kloub, hluboká bolest na labrum. Odlište jejich lokalizaci."},{"name":"Crank test","alias":"","steps":"Při vysoce zvednutém rameni vyviňte tlak podél podélné osy humeru a proveďte vnitřní a zevní rotaci.","positive":"Vyvolání bolesti nebo loupnutí (pocitu blokády)","tissue":"Labrum glenoidale","point":"Poranění labra lze samotným testem jen obtížně potvrdit; vyhodnoťte je společně se zobrazením."}]},"keypoints":["Šlacha dlouhé hlavy probíhá v sulcu a úpon má na tuberculum supraglenoidale a horním labru","Speedův a Yergasonův test prověřují bolest v sulcus intertubercularis","O’Brienův test odlišuje labrum a AC kloub na základě místa bolesti","Zaznamenejte také, zda je přítomno loupnutí nebo pocit blokády","Poranění labra nepotvrzujte jen testem; porovnejte jej se zobrazením"],"case":{"text":"22letý muž, hráč baseballu. Při nadhozu hluboká bolest ramene a pocit blokády. O’Brienův test s palcem dolů vyvolává hlubokou bolest, s dlaní nahoru poleaví. Speedův test je rovněž bolestivý.","answer":"Máme podezření na poranění horního labra (SLAP). Pokud je bolest na vrcholu ramene, myslete na původ v AC kloubu. O pokračování v házení nerozhodujte sami; odešlete pacienta k lékaři a doporučte mu vyhnout se pohybům při nadhozu, které vyvolávají bolest."},"questions":[{"level":"Základní","q":"Ve kterém žlábku probíhá šlacha dlouhé hlavy m. biceps brachii?","options":["Cavitas glenoidalis","Sulcus intertubercularis","Sulcus nervi radialis","Akromion"],"answer":1,"exp":"Šlacha dlouhé hlavy probíhá do kloubu v sulcus intertubercularis mezi tuberculum majus a minus humeru."},{"level":"Základní","q":"Kromě tuberculum supraglenoidale se šlacha dlouhé hlavy bicepsu upíná na kterou strukturu?","options":["Horní labrum","Lig. glenohumerale inferius","Lig. acromioclaviculare","Lig. coracoclaviculare"],"answer":0,"exp":"Dlouhá hlava odstupuje z tuberculum supraglenoidale a horního labra, proto bývá poškození šlachy a labra často sdružené."},{"level":"Pokročilý","q":"Proti jakému pohybu poskytnete odpor při Yergasonově testu?","options":["Abdukce ramene","Dorzální flexe zápěstí","Supinace předloktí","Extenze lokte"],"answer":2,"exp":"Odpor proti supinaci předloktí při 90° flexi lokte; bolest v sulcus intertubercularis poukazuje na poškození šlachy dlouhé hlavy."},{"level":"Pokročilý","q":"Co si myslíte, když O’Brienův test způsobuje bolest na vrcholu ramene?","options":["Poranění horního labra","Poškození akromioklavikulárního skloubení","Ruptura rotátorové manžety","Přední nestabilita"],"answer":1,"exp":"Bolest v horní části ramene poukazuje na AC skloubení, hluboká bolest v rameni na poranění horního labra."},{"level":"Klinický","q":"25letý muž, volejbalista. Při smeči hluboká bolest v rameni a loupnutí; O’Brienův test vyvolává hlubokou bolest. Co je nejpravděpodobnější?","options":["Poškození AC skloubení","Zmrzlé rameno","Cervikální spondylóza","SLAP léze"],"answer":3,"exp":"Při pohybu nad hlavou hluboká bolest a loupnutí a pozitivní O’Brienův test (hluboká bolest): podezříváme SLAP lézi."},{"level":"Klinický","q":"40letý muž při zvedání těžkého předmětu uslyšel prasknutí na přední straně paže a svalové bříško bicepsu pokleslo. Jaký je nejlepší postup?","options":["Posilování s maximálním odporem","Opakování Yergasonova testu","Odeslání k lékařskému vyšetření","Zahřátí a vyčkávání"],"answer":2,"exp":"Příznaky poukazující na rupturu šlachy dlouhé hlavy; nejdříve je nutné lékařské vyšetření. Vyhněte se zátěžovým testům a cvičení."}],"seccion":"Speciální testy podle regionů","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"Loket","lead":"Bolest lokte promyslete rozdělením na laterální extenzory, mediale flexory a vazivový aparát a n. ulnaris. Propojte místo bolesti s příslušným testem.","sheet":{"kind":"tests","tests":[{"name":"Thomsenův test","alias":"","steps":"S nataženým loktem a mírnou dorzální flexí zápěstí pacient zatne pěst; vyšetřující tlačí hřbet ruky do palmární flexe.","positive":"Bolest kolem epicondylus lateralis humeri","tissue":"Úpon m. extensor carpi radialis brevis","point":"Vyšetření laterální epicondylitidy. Kombinujte s testem extenze prostředníku a židlovým testem."},{"name":"Test extenze prostředníku","alias":"","steps":"S propnutým loktem pacient provede extenzi prostředníku; vyšetřující tlačí na proximální článek prstu palmárním směrem.","positive":"Bolest kolem epicondylus lateralis humeri","tissue":"Odstup m. extensor carpi radialis brevis a m. extensor digitorum","point":"Podobně jako u Thomsenova testu je pozitivní při laterální epikondylitidě. Zkontrolujte, kde se bolest projevuje."},{"name":"Valgozní zátěžový test","alias":"","steps":"Při mírně pokrčeném lokti zafixujte paži a na předloktí vyviňte zátěž ve valgózním směru.","positive":"Bolest vnitřní strany lokte nebo větší rozsah otevření oproti zdravé straně","tissue":"Lig. collaterale ulnare (vnitřní postranní vaz)","point":"K vyšetření „házejícího lokte“. Vždy porovnejte se zdravou stranou; bolest a laxitu zaznamenejte odděleně."},{"name":"Tinelův příznak (kubitální tunel)","alias":"","steps":"Kubitální tunel mezi epicondylus medialis a olecranonem lehce poklepejte bříškem prstu nebo reflexním kladívkem.","positive":"Brnění vystřelující do malíčku a ulnární strany prsteníčku","tissue":"n. ulnaris (kubitální tunel)","point":"Vyšetření syndromu kubitálního tunelu. Hodnoťte společně s testem flexe lokte a Fromentovým příznakem."}]},"keypoints":["Při bolesti v oblasti epicondylus lateralis myslete na odstup natahovačů zápěstí a prstů","Valgózní zátěžový test provádějte v mírné flexi a porovnejte se zdravou stranou","Příznaky postižení n. ulnaris signalizuje brnění malíčku a ulnární strany prsteníčku","Bolest a laxitu (instabilitu) zaznamenejte odděleně","Při přetrvávajícím brnění nebo atrofii svalů ruky odešlete pacienta k lékaři"],"case":{"text":"45letá žena, administrativní pracovnice. Při ždímání ručníku a zvedání tašky ji bolí loket z boku. Epicondylus lateralis je citlivý na tlak, Thomsenův test a test extenze prostředníku vyvolávají bolest.","answer":"Nálezy svědčící pro epicondylitis lateralis humeri. Vyhněte se opakování úchopových pohybů vyvolávajících bolest a dávkujte zátěž. Pokud se přidá brnění, otok nebo silná noční bolest, pomýšlejte i na jiná onemocnění a odešlete pacienta k lékaři."},"questions":[{"level":"Základní","q":"Která svalová skupina odstupuje od epicondylus lateralis humeri?","options":["Flexory zápěstí","Extenzory zápěstí","m. biceps brachii","m. pronator teres"],"answer":1,"exp":"Od epicondylus lateralis odstupují extenzory zápěstí a prstů, od mediálního pak flexory a m. pronator teres."},{"level":"Základní","q":"Který nerv prochází kubitálním tunelem?","options":["n. medianus","n. radialis","n. ulnaris","n. musculocutaneus"],"answer":2,"exp":"n. ulnaris probíhá kubitálním tunelem za epicondylus medialis, proto poklep na vnitřní stranu lokte vyvolává brnění směrem do malíčku."},{"level":"Pokročilý","q":"Proti kterému pohybu kladete odpor při Thomsenově testu?","options":["Dorzální flexe zápěstí","Palmární flexe zápěstí","Pronace předloktí","Flexe lokte"],"answer":0,"exp":"Odpor kladený proti dorzální flexi zápěstí vyvolává bolest v okolí epicondylus lateralis (odstup extenzorů)."},{"level":"Pokročilý","q":"Kterou strukturu vyšetřuje primárně valgózní zátěžový test?","options":["Zevní postranní vaz","Lig. anulare radii","Caput radii","Vnitřní postranní vaz"],"answer":3,"exp":"Valgózní zátěž vyvinutá na předloktí napíná vnitřní stranu lokte, čímž se vyšetřuje bolest a laxita vnitřního postranního vazu."},{"level":"Klinický","q":"14letý chlapec, baseballový nadhazovač. Při hodu bolest vnitřní strany lokte; valgus stress test vyvolává bolest mediálně. Co je nejpravděpodobnější?","options":["Epicondylitis lateralis humeri","Mediální typ „nadhazovačského lokte“","Radiální subluxace (chůvičkový loket)","Zlomenina hlavičky radia"],"answer":1,"exp":"Opakovaný nadhazovací pohyb a vnitřní bolest při valgusové zátěži svědčí pro mediální „nadhazovačský loket“ (poškození vazů, epifýzy)."},{"level":"Klinický","q":"50letý muž. Při poklepu na vnitřní stranu lokte vystřeluje brnění do malíku a jemná motorika prstů je obtížná. Co je nejlepší udělat?","options":["Dlouhodobé držení lokte ve flexi","Sledování brnění","Informování lékaře","Silná masáž vnitřní strany lokte"],"answer":2,"exp":"Při poškození n. ulnaris spojeném se sníženou obratností je nutné lékařské vyšetření. Dlouhodobá flexe lokte a tlak příznaky zhoršují."}],"seccion":"Speciální testy podle regionů","grupo":"Loket, zápěstí a ruka","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"Zápěstí a ruka","lead":"Při brnění a bolesti ruky usuzujte podle distribuce, který nerv nebo šlacha jsou postiženy. Syndrom karpálního tunelu a zánět šlach jsou v klinické praxi i u státní závěrečné zkoušky časté.","sheet":{"kind":"tests","tests":[{"name":"Phalenův test","alias":"","steps":"Pacient drží hřbety rukou u sebe v maximální palmární flexi zápěstí; sledujte výskyt brnění.","positive":"Brnění od palce k radiální straně prsteníčku nebo jeho zhoršení","tissue":"n. medianus (karpální tunel)","point":"Vyšetření syndromu karpálního tunelu. Zkontrolujte, zda brnění odpovídá inervační oblasti n. medianus."},{"name":"Tinelův příznak (zápěstí)","alias":"","steps":"Na palmární straně zápěstí lehce poklepejte na karpální tunel konečkem prstu nebo reflexním kladívkem.","positive":"Brnění vystřelující do konečků prstů v oblasti n. medianus","tissue":"n. medianus (karpální tunel)","point":"Lze použít k odhadu místa útlaku nervu i k posouzení regenerace. Nepoklepávejte příliš silně."},{"name":"Finkelsteinův test","alias":"","steps":"Pacient sevře palec do pěsti ostatními prsty (nebo vyšetřující drží palec), poté pasivně proveďte ulnární deviaci zápěstí.","positive":"Silná bolest v oblasti processus styloideus radii","tissue":"m. abductor pollicis longus a m. extensor pollicis brevis","point":"Vyšetření de Quervainovy nemoci. Varianta se sevřením do pěsti se nazývá Eichhoffův test. Porovnejte se zdravou stranou."},{"name":"Fromentův příznak","alias":"","steps":"Pacient drží papír mezi palcem a ukazovákem obou rukou, vyšetřující jej vytahuje.","positive":"IP kloub palce se ohýbá, aby papír udržel","tissue":"n. ulnaris (m. adductor pollicis)","point":"Slabý m. adductor pollicis je kompenzován m. flexor pollicis longus, který je inervován n. medianus."}]},"keypoints":["Na základě distribuce brnění odlište n. medianus, n. ulnaris a n. radialis","Phalenův test a Tinelův příznak vyšetřují n. medianus v karpálním tunelu","Finkelsteinův test slouží k vyšetření zánětu šlach palce","Proveďte na obou stranách a hodnoťte porovnáním se zdravou stranou","Při atrofii thenaru nebo přetrvávajícím brnění odešlete pacienta k lékaři"],"case":{"text":"52letá žena. Nad ránem brní palec, ukazovák a prostředník, po protřepání ruky potíže ustupují. Phalenův test vyvolává brnění ve stejné oblasti a Tinelův příznak nad karpálním tunelem je pozitivní.","answer":"Podezříváme syndrom karpálního tunelu. Pokud se brnění šíří i do malíčku nebo se mění při pohybu krku, pomýšlejte i na jinou úroveň. Při atrofii thenaru nebo slabosti odešlete k lékaři; vyhněte se silné kompresi zápěstí."},"questions":[{"level":"Základní","q":"Který nerv prochází karpálním tunelem?","options":["n. ulnaris","n. medianus","n. radialis","n. musculocutaneus"],"answer":1,"exp":"Karpálním tunelem probíhají šlachy flexorů prstů a n. medianus; jejich komprese zde způsobuje syndrom karpálního tunelu."},{"level":"Základní","q":"Kde se objevuje bolest při Finkelsteinově testu?","options":["Processus styloideus radii","Processus styloideus ulnae","Os pisiforme","Hlavička V. metakarpu"],"answer":0,"exp":"Bolest je v oblasti proc. styloideus radii, kde probíhají šlachy palce (m. abductor pollicis longus, m. extensor pollicis brevis)."},{"level":"Pokročilý","q":"Který nerv vyšetřuje Fromentův příznak?","options":["n. medianus","n. radialis","n. axillaris","n. ulnaris"],"answer":3,"exp":"Pokud je m. adductor pollicis inervovaný n. ulnaris slabý, m. flexor pollicis longus kompenzuje a IP kloub se ohne."},{"level":"Pokročilý","q":"Co je pozitivní nález Phalenova testu?","options":["Brnění malíčku","Bolest celého hřbetu ruky","Brnění I.–IV. prstu radiální strany","Pocit nestability zápěstí"],"answer":2,"exp":"Udržovaná palmární flexe zvyšuje tlak v tunelu, čímž vzniká brnění v oblasti n. medianus (od palce po radiální stranu IV. prstu)."},{"level":"Klinický","q":"30letá žena. Od porodu při péči o dítě bolí zápěstí na straně palce; bolest při sevření palce v pěst a ulnární dukci. Co je pravděpodobné?","options":["Syndrom karpálního tunelu","Poranění TFCC","De Quervainova nemoc","Skákavý prst"],"answer":2,"exp":"Přetížení palce a bolest v oblasti proc. styloideus radii při sevření v pěst a ulnární dukci ukazuje na De Quervainovu nemoc."},{"level":"Klinický","q":"60letý muž. Brní malíček a ulnární strana prsteníčku, při testu sevření papíru se ohýbá IP kloub palce. Který nerv je pravděpodobně poškozen?","options":["n. medianus","n. radialis","n. interosseus posterior","n. ulnaris"],"answer":3,"exp":"Brnění malíčku a ulnární strany prsteníčku spolu s pozitivním Fromentovým příznakem ukazuje na poškození n. ulnaris."}],"seccion":"Speciální testy podle regionů","grupo":"Loket, zápěstí a ruka","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"Phalenův test","img":"img/fichas/phalen.jpg"},{"nombre":"Finkelsteinův test","img":"img/fichas/finkelstein.jpg"},{"nombre":"Tinelův příznak na zápěstí","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"Krční páteř","lead":"Bolest a brnění vystřelující z krku do paže může způsobovat komprese nervového kořene. Provokačními a odlehčovacími testy ověřte, zda jde o radikulární příznaky.","sheet":{"kind":"tests","tests":[{"name":"Spurlingův test","alias":"Foraminální kompresní test","steps":"V sedě ukloňte krk na bolestivou stranu (mírná extenze a rotace), poté vyviňte tlak shora na temeno hlavy.","positive":"Vyvolání bolesti nebo brnění vyzařujícího do bolestivé paže","tissue":"Krční nervový kořen (foramen intervertebrale)","point":"Vyvolání pouze bolesti v krku není pozitivní. Při silné bolesti nebo závratích ihned přestaňte."},{"name":"Jacksonův test","alias":"Jacksonův kompresní test","steps":"V sedě, v mírné krční extenzi, vyviňte tlak shora na temeno hlavy.","positive":"Vyvolání bolesti nebo brnění vyzařujícího do paže","tissue":"Krční nervový kořen","point":"Využívá toho, že v extenzi se foramen zužuje. Kombinujte se Spurlingovým testem."},{"name":"Krční distrakční test","alias":"Distrakční test","steps":"V sedě, s oporou pod čelistí a za týlem, pomalu tahejte hlavu směrem vzhůru.","positive":"Ustupuje bolest nebo brnění vyzařující do paže","tissue":"Krční nervový kořen (foraminální komprese)","point":"Při ústupu příznaků je test pozitivní. Pokud tah příznaky zhoršuje, myslete na jinou příčinu a přestaňte."},{"name":"Test abdukce ramene","alias":"Bakodyho příznak","steps":"V sedě si pacient položí ruku na bolestivé straně na temeno hlavy; sledujte změnu příznaků v paži.","positive":"Ustupuje bolest nebo brnění vyzařující do paže","tissue":"Krční nervový kořen","point":"Napětí nervového kořene klesá, příznaky ustupují. Pacient může tuto polohu zaujmout i spontánně."}]},"keypoints":["Vyvolání bolesti nebo brnění vyzařujícího do paže ukazuje na radikulární příznak","Kompresní testy provádějte šetrně, při silných příznacích přestaňte","Zkontrolujte také, zda příznaky ustupují při tahu nebo abdukci ramene","Na základě dermatomů, svalové síly a šlachových reflexů odhadněte úroveň","Oboustranné brnění rukou nebo porucha chůze: podezření na myelopatii, odešlete k lékaři"],"case":{"text":"48letý muž, sedavé zaměstnání. Bolest krku a brnění od pravého palce po radiální stranu předloktí. Spurlingův test vyvolává brnění v pravé paži, při tahu za hlavu ustupuje.","answer":"Podezříváme krční radikulopatii; na základě distribuce brnění jde o oblast C6. Zkontrolujte také šlachové reflexy a svalovou sílu. Pokud se zhoršuje obratnost obou rukou nebo je přítomna porucha chůze, myslete na myelopatii a odešlete k lékaři. Vyhněte se opakování silné komprese."},"questions":[{"level":"Základní","q":"V jaké poloze krku vyvíjíte tlak na hlavu při Spurlingově testu?","options":["Laterální flexe na bolestivou stranu","Laterální flexe na zdravou stranu","Maximální flexe","Střední poloha s tahem"],"answer":0,"exp":"Při úklonu na bolestivou stranu (s mírnou extenzí) se foramen zužuje; stlačení hlavy vyvolá radikulární příznak."},{"level":"Základní","q":"Která oblast se zužuje při krční extenzi a úklonu na bolestivou stranu, čímž snadno utlačuje nervový kořen?","options":["Přední okraj obratlového těla","Foramen intervertebrale","Meziprostor trnových výběžků","Hrot příčného výběžku"],"answer":1,"exp":"Nervový kořen vystupuje skrze foramen intervertebrale, proto jej extenze a lateroflexe snadno komprimují zúžením prostoru."},{"level":"Pokročilý","q":"Co je pozitivním nálezem u cervikálního distrakčního testu?","options":["Zhoršení symptomů v horní končetině","Výskyt závratě","Úleva od symptomů v horní končetině","Zvětšení rozsahu pohybu (ROM) krční páteře"],"answer":2,"exp":"Trakce rozšiřuje foramen a snižuje kompresi nervového kořene; pokud bolest či brnění v paži ustoupí, je test pozitivní."},{"level":"Pokročilý","q":"Na základě jakého nálezu hodnotíte Spurlingův test jako pozitivní?","options":["Pouze bolest v oblasti krku","Pocit ztuhlosti ramene","Svalové napětí v oblasti krku","Bolest vystřelující do paže na bolestivé straně"],"answer":3,"exp":"Pozitivní, pokud lze vyvolat bolest nebo brnění vystřelující do paže. Pouze lokální bolest krku není pozitivním nálezem."},{"level":"Klinický","q":"50letá žena, bolest krku a brnění levého prostředníku. Reflex tricepsu vlevo je snížený. Který nervový kořen máte v podezření?","options":["C5","C6","C7","C8"],"answer":2,"exp":"Porucha citlivosti prostředníku a snížený reflex tricepsu ukazují na poškození nervového kořene C7."},{"level":"Klinický","q":"65letý muž. Obě ruce brní, má potíže se zapínáním knoflíků a je nejistý při chůzi. Jaký je nejvhodnější postup?","options":["Informování lékaře","Silná trakce krku","Opakování Spurlingova testu","Manuální korekce krční páteře"],"answer":0,"exp":"Oboustranná ztráta obratnosti a porucha chůze ukazují na cervikální myelopatii. Vyhněte se provokačním testům, odešlete pacienta k lékaři."}],"seccion":"Speciální testy podle regionů","grupo":"Páteř a pánev","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"Bederní páteř","lead":"Pokud bolest beder doprovází bolest nebo brnění dolní končetiny, vyšetřete postižení nervového kořene. Na základě symptomů vyvolaných testy a neurologického nálezu odhadněte úroveň poškození.","sheet":{"kind":"tests","tests":[{"name":"SLR test","alias":"Lasègueův příznak","steps":"Vleže na zádech s propnutým kolenem vyšetřující pomalu a pasivně zvedá dolní končetinu.","positive":"Vyvolání bolesti nebo mravenčení vyzařujícího do hýždě a bérce","tissue":"Kořeny L5 a S1, n. ischiadicus","point":"Odlište napětí v zadní části stehna od protažení hamstringů. Zaznamenejte úhel a příznak."},{"name":"Femorální napínací test","alias":"Test obráceného Lasègueova příznaku (FNS)","steps":"V lehu na břiše pasivně ohněte koleno, v případě potřeby uveďte do extenze i kyčel.","positive":"Bolest vyzařující do přední části stehna","tissue":"Horní bederní nervové kořeny (L2–L4), n. femoralis","point":"Odlište od protažení m. quadriceps a bolesti kyčelního původu."},{"name":"Kempův test","alias":"","steps":"Ve stoje nebo v sedu vyšetřující provede extenzi trupu vzad a současně jej ukloní a zrotuje na bolestivou stranu.","positive":"Bolest v kříži nebo bolest vyzařující do nohy na bolestivé straně","tissue":"Facetové klouby a nervový kořen (foramen)","point":"Při lokální bolesti dolní části zad myslete na postižení facetových kloubů, při bolesti vyzařující do nohy na kořenové postižení."},{"name":"Bragardův test","alias":"","steps":"Z úhlu vyvolávajícího příznak při SLR končetinu mírně spusťte níže a poté pasivně proveďte dorzální flexi v hleznu.","positive":"Bolest vyzařující do nohy se znovu objevuje nebo zesiluje","tissue":"n. ischiadicus a lumbosakrální nervové kořeny","point":"Pomáhá odlišit bolest z protažení hamstringů od neurogenních příznaků."}]},"keypoints":["Nejprve odlište: jde pouze o bolest zad, nebo je provázena příznaky v končetině?","SLR vyšetřuje dolní, test femorálního natažení horní bederní nervové kořeny","Zaznamenejte zvlášť pocit svalového protažení a neurogenní vystřelující bolest","Na základě dermatomů, svalové síly a šlachových reflexů odhadněte úroveň","Poruchy močení nebo defekace, brnění v oblasti hradby: naléhavě k lékaři"],"case":{"text":"35letý muž. Od zvedání těžkého předmětu pociťuje bolest v kříži a brnění od vnější strany pravého bérce po hřbet nohy. Test SLR vyvolává bolest vyzařující do pravé nohy, Bragardův test ji zesiluje. Síla dorzální flexe palce je snížená.","answer":"Podezíráme radikulární příznak L5 (např. výhřez bederní ploténky). Vyhněte se zátěži v předklonu, která bolest zhoršuje. V případě poruchy močení či defekace, brnění v oblasti hradby nebo rychle slabnoucí svalové síly jej neprodleně odešlete k lékaři."},"questions":[{"level":"Základní","q":"Který nerv napíná test SLR především?","options":["n. femoralis","n. ischiadicus","n. obturatorius","n. pudendus"],"answer":1,"exp":"Flexe v kyčli při nataženém koleni napíná n. ischiadicus probíhající v zadní části končetiny a nervové kořeny L5–S1."},{"level":"Základní","q":"Které úrovně nervových kořenů vyšetřuje test femorálního natažení především?","options":["L2–L4","L5–S1","S2–S4","C5–C6"],"answer":0,"exp":"Nerv n. femoralis vychází z kořenů L2–L4, proto jej používáme k vyšetření horních bederních radikulárních příznaků."},{"level":"Pokročilý","q":"Jaký úkon provádíte při Bragardově testu?","options":["Plantární flexe hlezna","Zevní rotace kyčle","Flexe kolene","Dorzální flexe hlezna"],"answer":3,"exp":"Z úhlu, který při SLR vyvolává příznak, nohu mírně spustíte a následně dorzální flexí hlezna nerv dále napnete."},{"level":"Pokročilý","q":"Na co pomýšlíte především, pokud Kempův test způsobuje pouze lokální bolest zad bez příznaků v dolní končetině?","options":["Komprese kořene nervu","Poškození n. femoralis","Bolest facetových kloubů","Syndrom m. piriformis"],"answer":2,"exp":"Extenze a rotace zatěžují facetové klouby. Při lokální bolesti myslete na facetový původ."},{"level":"Klinický","q":"40letá žena, bolest v kříži, mravenčení od vnější strany levé nohy po plosku. Levý Achillesreflex je snížený. Jaké kořenové postižené podezíráte?","options":["L3","L4","L5","S1"],"answer":3,"exp":"Porucha citlivosti vnější strany nohy a plosky a snížený Achillesreflex ukazují na poškození kořene S1."},{"level":"Klinický","q":"U 50letého muže se vedle bolesti v kříži objevilo náhlé mravenčení v hýždích a potíže s močením. Co je nejlepší postup?","options":["Okamžitě odeslat k lékaři","Opakované vyšetření SLR","Zahájení bederních cviků","Tepelná terapie a vyčkávání"],"answer":0,"exp":"Mravenčení v hýždích a porucha svěračů jsou červené vlajky ukazující na syndrom cauda equina; je nutná urgentní péče."}],"seccion":"Speciální testy podle regionů","grupo":"Páteř a pánev","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"Sakroiliakální skloubení","lead":"Bolest sakroiliakálního (SI) skloubení lze snadno zaměnit za bolest zad. Vyvozujte závěry kombinací ukázání místa bolesti a více provokačních testů.","sheet":{"kind":"tests","tests":[{"name":"FABER (Patrickův) test","alias":"","steps":"V lehu na zádech položte chodidlo bolestivé strany na opačné koleno, fixujte opačnou pánvi a zatlačte koleno dolů.","positive":"Bolest v hýždi nad SI skloubením (bolest v třísle: kyčelní kloub)","tissue":"Sakroiliakální skloubení a kyčelní kloub","point":"Odlište na základě místa bolesti: tříslo značí kyčelní kloub, hýždě a SI skloubení značí SI skloubení."},{"name":"Gaenslenův test","alias":"","steps":"V lehu na zádech visí jedna dolní končetina přes okraj stolu (extenze kyčle), pacient si druhá koleno v pokrčení objímá k sobě.","positive":"Bolest nad SI skloubením na extendované straně","tissue":"Sakroiliakální skloubení","point":"Vyhněte se hyperextenzi bederní páteře; podepřete trup, abyste zabránili pádu."},{"name":"Thigh thrust test","alias":"Test komprese stehna","steps":"V lehu na zádech a při 90° flexi kyčle vyvíjíte tlak směrem dolů podél podélné osy stehna.","positive":"Bolest v hýždi na téže straně nad SI skloubením","tissue":"Sakroiliakální skloubení","point":"Požádejte pacienta, aby ukázal místo bolesti, a ověřte, zda jde o jeho obvyklou bolest."},{"name":"Test komprese pánve","alias":"","steps":"V bočním lehu vyviňte kompresi na horní crista iliaca směrem shora dolů.","positive":"Bolest nad SI skloubením","tissue":"Sakroiliakální skloubení","point":"Samotný test nestačí. K určení bolesti SI původu využijte kombinaci více provokačních testů."}]},"keypoints":["Požádejte pacienta, aby jedním prstem ukázal místo bolesti","Při bolesti v okolí spina iliaca posterior superior pomýšlejte na SI původ","Nerozhodujte se na základě jediného, ale více provokačních testů","Při bolesti v tříslech myslete na kyčel, při bolesti vyzařující do nohy myslete i na nervový kořen","Při horečce nebo silné klidové bolesti odešlete pacienta k lékaři"],"case":{"text":"32letá žena, 3 měsíce po porodu. Jednostranná bolest hýždě, která se zhoršuje při otáčení a stoji na jedné noze. Jedním prstem ukazuje na oblast spina iliaca posterior superior. Thigh thrust a Gaenslenův test vyvolávají bolest.","answer":"Podezříváme bolest SI původu. Při bolesti vyzařující do nohy nebo neurologických příznacích pomýšlejte i na bederní původ. Při horečce nebo silné klidové bolesti odešlete k lékaři. Postupujte stabilizací pánevního pletence a dávkováním zátěže."},"questions":[{"level":"Základní","q":"Kterou oblast pacient typicky ukazuje při testu jedním prstem u bolesti SI původu?","options":["Oblast spina iliaca ant. sup.","Oblast spina iliaca post. sup.","Symphysis pubica","Tuber ischiadicum"],"answer":1,"exp":"U bolesti SI původu pacient často ukazuje jedním prstem na oblast spina iliaca posterior superior."},{"level":"Základní","q":"Které kosti tvoří sacroiliakální skloubení?","options":["Křížová kost a kyčelní kost","Křížová kost a sedací kost","Kyčelní kost a stydká kost","Obratel L5 a křížová kost"],"answer":0,"exp":"SI skloubení je kloub mezi křížovou kostí a dvěma kostmi kyčelními; tvoří zadní část pánevního prstence."},{"level":"Pokročilý","q":"Na který kloub pomýšlíte, pokud FABER (Patrickův) test vyvolá tříselnou bolest?","options":["Sakroiliakální skloubení","Kyčelní kloub","Kolenní kloub","Fazetové klouby"],"answer":1,"exp":"Pokud při flexi, abdukci a zevní rotaci bolí tříslo, pomýšlejte na kyčelní kloub, pokud zadní část hýždě, na SI skloubení."},{"level":"Pokročilý","q":"V jakém směru vyvíjíte tlak při thigh thrust testu?","options":["Stehno směrem ven","Pánev směrem vpřed","Podél podélné osy stehna směrem dolů","Koleno směrem dovnitř"],"answer":2,"exp":"Při 90° flexi kyčle vyvíjí tlak podél podélné osy stehna střižné zatížení na SI skloubení."},{"level":"Klinický","q":"28letá žena, po porodu jednostranná bolest hýždě. Gaenslenův, thigh thrust a kompresní test pánve vyvolávají bolest. Co je nejpravděpodobnější?","options":["Kyčelní kloub","Nervový kořen L5","m. piriformis","Sakroiliakální skloubení"],"answer":3,"exp":"Více provokačních testů SI vyvolává stejnou bolest, proto pomýšlíme především na bolest SI původu."},{"level":"Klinický","q":"45letý muž, jednostranná bolest hýždě. Pouze FABER (Patrickův) test vyvolal bolest hýždě. Jaký je nejvhodnější další krok?","options":["Stanovení diagnózy dysfunkce SI skloubení","Další provokační testy","Vynechání vyšetření bederní páteře a kyčle","Silná manuální korekce"],"answer":1,"exp":"Podle jediného pozitivního testu se nemůžete rozhodnout. Kombinujte více provokačních testů s vyšetřením bederní páteře a kyčle."}],"seccion":"Speciální testy podle regionů","grupo":"Páteř a pánev","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"Kyčel","lead":"Bolest původem v kyčelním kloubu se často projevuje v třísle, přičemž kontraktura a svalová slabost jsou viditelné při chůzi. Testy ověřte vliv na vnitroskloubní poměry, svaly a chůzi.","sheet":{"kind":"tests","tests":[{"name":"Thomasův test","alias":"","steps":"V lehu na zádech pacient přitáhne jedno koleno k hrudníku, čímž zruší bederní lordózu; sledujte, zda se kontralaterální stehno zvedá.","positive":"Kontralaterální stehno se zvedá z podložky (kontraktura v flexi kyčle)","tissue":"Zkrácení m. iliopsoas (flexory kyčle)","point":"Pokud se koleno natahuje, myslete také na zkrácení m. rectus femoris. Hodnoťte po zrušení lordózy."},{"name":"FABER (Patrickův) test","alias":"","steps":"V lehu na zádech uveďte kyčel do flexe, abdukce a zevní rotace (chodidlo na kontralaterálním koleni) a poté zatlačte koleno dolů.","positive":"Bolest v třísle nebo omezený pokles kolene","tissue":"Kyčelní kloub a sakroiliakální skloubení","point":"Při bolesti v třísle myslete na kyčel, při bolesti v zadní části hýždě na SI skloubení. Porovnejte se zdravou stranou."},{"name":"Test předního impingementu","alias":"FADIR test","steps":"V lehu na zádech z 90° flexe kyčle provedete pasivně addukci a vnitřní rotaci.","positive":"Vyvolání bolesti v třísle","tissue":"Přední část kyčelního kloubu (labrum, okraj acetabula)","point":"Často pozitivní při femoroacetabulárním impingementu a poranění labra. Porovnejte se zobrazením."},{"name":"Trendelenburgův příznak","alias":"","steps":"Pacient stojí na jedné noze na bolestivé končetině; zezadu sledujte výšku kontralaterální (zvednuté) pánve.","positive":"Zvednutá pánev klesá","tissue":"m. gluteus medius stojné nohy (abduktory kyčle)","point":"Pokud trup kompenzuje úklonem ke stojné noze, jedná se o Duchenneovo znamení. Podepřete pacienta, abyste předešli pádu."}]},"keypoints":["Bolest původem v kyčelním kloubu se často objevuje v třísle","Thomasův test vyšetřuje flexní kontrakturu po zrušení lordózy","Trendelenburgův příznak ukazuje sílu m. gluteus medius stojné nohy","Odlište také od bolesti původem v bederní páteři a SI skloubení","Neschopnost zatížení po úrazu nebo zhoršující se klidová bolest: k lékaři"],"case":{"text":"68letá žena, koxartróza. Při chůzi bolest v pravém třísle. Při stoju na pravé noze levá pánev klesá; při přitažení levého kolene k hrudníku se pravé stehno zvedá z podložky.","answer":"Myslíme na slabost pravého m. gluteus medius a kontrakturu flexorů pravé kyčle. Sledujte také kompenzace při chůzi; s ohledem na bolest provádějte posílení abduktorů a ROM cvičení. V případě náhle se zhoršující klidové bolesti odesílejte k lékaři."},"questions":[{"level":"Základní","q":"Kterého svalu zkrácení vyšetřuje primárně Thomasův test?","options":["m. gluteus maximus","m. iliopsoas","m. gluteus medius","Hamstringy"],"answer":1,"exp":"Zvednutí kontralaterální stehna ukazuje na flexní kontrakturu kyčle, a tím poukazuje na zkrácení hlavního flexoru kyčle m. iliopsoas."},{"level":"Základní","q":"Slabost kterého svalu signalizuje Trendelenburgův příznak, když při stoji na jedné noze klesá kontralaterální pánev?","options":["m. gluteus medius švihové nohy","m. quadriceps femoris stojné nohy","m. gluteus medius stojné nohy","m. iliopsoas švihové nohy"],"answer":2,"exp":"Pokud je m. gluteus medius stojné nohy slabý, nedokáže udržet pánev v horizontální rovině a kontralaterální (zvednutá) strana poklesne."},{"level":"Pokročilý","q":"Na zkrácení kterého svalu pomyslíte, pokud se při Thomasově testu koleno extenduje?","options":["m. rectus femoris","m. sartorius","m. adductor magnus","m. biceps femoris"],"answer":0,"exp":"m. rectus femoris je dvoukloubový sval přemosťující kyčelní i kolenní kloub; při jeho zkrácení dochází k extenzi kolene."},{"level":"Pokročilý","q":"Jakou kombinaci pohybů provádíte při předním impingement (FADIR) testu?","options":["Flexe, abdukce, zevní rotace","Extenze, abdukce, vnitřní rotace","Extenze, addukce, zevní rotace","Flexe, addukce, vnitřní rotace"],"answer":3,"exp":"Z 90° flexe v kyčli provedete addukci a vnitřní rotaci a sledujete, zda lze vyvolat přední bolest kyčle."},{"level":"Klinický","q":"70letý muž. Kdykolivšlápne na pravou nohu, při chůzi silně naklání trup doprava. Jak se nazývá tato chůze?","options":["Brodivá (kohoutí) chůze","Cirkumdukční chůze","Freezing (zamrznutí)","Duchennova chůze"],"answer":3,"exp":"Pokud pacient kompenzuje slabost m. gluteus medius nakloněním trupu k stojné noze, jedná se o Duchennovu chůzi."},{"level":"Klinický","q":"30letý fotbalista. Při hlubokém dřepu ho bolí v třísle a flexe, addukce a vnitřní rotace kyčle vyvolávají bolest. Co je nejpravděpodobnější?","options":["Gonartróza","Femoroacetabulární impingement","L5 radikulopatie","Syndrom m. piriformis"],"answer":1,"exp":"Bolest v třísle objevující se v hluboké flexi a pozitivní test předního impingementu poukazují na femoroacetabulární impingement."}],"seccion":"Speciální testy podle regionů","grupo":"Kyčel a koleno","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"Koleno: vazy","lead":"Testy kolenních vazů slouží k odlišení poranění předního a zadního zkříženého vazu a vnitřního a zevního postranního vazu. Základem rozhodnutí je mechanismus úrazu a porovnání se zdravou stranou.","sheet":{"kind":"tests","tests":[{"name":"Lachmanův test","alias":"","steps":"Leh na zádech, koleno ve flexi 20–30°. Jedna ruka drží distální část stehna, druhá proximální část tibie a tahá tibii dopředu.","positive":"Větší přední posun než na zdravé straně nebo nejistý konečný pocit.","tissue":"Přední zkřížený vaz (ACL)","point":"Citlivý test na poranění ACL. Nevyžaduje 90° flexi kolene, proto jej lze dobře provést i v akutním stadiu."},{"name":"Přední zásuvkový test","alias":"","steps":"Leh na zádech, kyčle do 45°, kolena do 90° flexe. Zafixujte nohu, proximální část tibie uchopte oběma rukama a táhněte dopředu.","positive":"Větší přední posun tibie ve srovnání se zdravou stranou.","tissue":"Přední zkřížený vaz (ACL)","point":"Obranné napětí svalů může způsobit falešně negativní výsledek. Dbejte také na zadní pokles způsobený zraněním PCL."},{"name":"Zadní zásuvkový test","alias":"","steps":"Leh na zádech, kyčle do 45°, kolena do 90° flexe. Zafixujte nohu a proximální část tibie zatlačte směrem dozadu.","positive":"Větší zadní posun tibie než na zdravé straně, nejistý koncový pocit.","tissue":"Zadní zkřížený vaz (PCL)","point":"Před zahájením zkontrolujte zadní pokles tibie (sag sign), abyste nezkreslili počáteční polohu."},{"name":"Valgózní a varózní zátěžový test","alias":"","steps":"Leh na zádech, kolena v 0° a 30° flexi. Zafixujte distální část stehna a působte na bérec silou ve valgózním nebo varózním směru.","positive":"Bolest v kloubní štěrbině nebo větší rozevření než na zdravé straně.","tissue":"Valgus = MCL, varus = LCL","point":"Pozitivní pouze ve 30°: izolované poranění postranního vazu. I v 0°: podezření na sdružené (např. zkříženého vazu) poranění."}]},"keypoints":["Pro vyšetření ACL je Lachmanův test první volbou, vždy ve srovnání se zdravou stranou","V anamnéze se zeptejte na vyskočení kolene, lupnutí a rychlý otok","Před zadním zásuvkovým testem zkontrolujte pozici tibie pomocí sag sign","Zatěžujte postranní vazy v 0° a také ve 30° flexi","Obranné napětí dává falešně negativní výsledek, proto vyšetřujte v uvolněné polopenzi"],"case":{"text":"20letá žena. Při dopadu při basketbalu se jí koleno podlomilo dovnitř. Slyšela lupnutí, koleno ihned oteklo. Při Lachmanově testu je přední posun větší než na zdravé straně, koncový pocit je nejistý.","answer":"Nález poukazující na poranění ACL. Vyšetřete také sdružené poranění menisku a postranních vazů a odešlete pacientku k lékařskému zobrazovacímu vyšetření. Při silném otoku a bolesti neopakujte silné zátěžové testy."},"questions":[{"level":"Základní","q":"Který test na obrázku táhne tibii dopředu při 20–30° flexi kolene?","options":["Přední zásuvkový test","Lachmanův test","Zadní zásuvkový test","Valgozní zátěžový test"],"answer":1,"exp":"Lachmanův test táhne tibii dopředu při 20–30° flexi kolene a vyšetřuje ACL. Přední zásuvkový test provádíme při 90° v koleni."},{"level":"Základní","q":"Který vaz vyšetřuje varózní zátěžový test na obrázku?","options":["Vnitřní postranní vaz (MCL)","Přední zkřížený vaz (ACL)","Zevní postranní vaz (LCL)","Zadní zkřížený vaz (PCL)"],"answer":2,"exp":"Varózní zátěž otevírá zevní stranu kolene, a vyšetřuje tak zevní postranní vaz (LCL). Valgózní zátěž vyšetřuje MCL."},{"level":"Pokročilý","q":"Na jaké poranění poukazuje pozitivní zadní zásuvkový test?","options":["Poranění PCL","Poranění ACL","Poranění LCL","Luxace čéšky"],"answer":0,"exp":"Zadní zásuvkový test tlačí tibii dozadu při 90° flexi kolene a vyšetřuje zadní zkřížený vaz (PCL)."},{"level":"Pokročilý","q":"Pokud je valgózní zátěžový test pozitivní i v 0° flexi kolene, na co pomyslíte jako první?","options":["Mírné, izolované poranění MCL","Pouze poranění zevního menisku","Nestabilita čéšky","Sdružené poranění (např. zkříženého vazu)"],"answer":3,"exp":"V extenzi stabilizují i zkřížené vazy a kloubní pouzdro. Pokud se štěrbina otevírá i v 0°, existuje podezření na sdružené poranění, nikoli izolované MCL."},{"level":"Klinický","q":"25letý muž. Při fotbale utrpěl silný úder na přední stranu tibie při pokrčeném koleni. Při 90° flexi tibie poklesla dozadu. Co je nejpravděpodobnější?","options":["Poranění ACL","Poranění PCL","Poranění MCL","Poranění vnitřního menisku"],"answer":1,"exp":"Síla působící na přední povrch holenní kosti a sag signál jsou typické pro poranění PCL. Potvrďte zadním zásuvkovým testem a odesílejte k lékařské diagnostice."},{"level":"Klinický","q":"30letá žena. Při lyžování se jí koleno otočilo do valgusu. Při valgózním stresu ve 30° flexi je přítomna bolest a rozevření, v 0° je stabilní. Co je nejpravděpodobnější?","options":["Izolované poranění ACL","Poranění LCL","Izolované poranění MCL","Poranění PCL"],"answer":2,"exp":"Valgózní mechanismus a pozitivní test pouze ve 30° poukazují na izolované poranění MCL. Pokud je pozitivní i v 0°, je nutno předpokládat sdružené poranění."}],"seccion":"Speciální testy podle regionů","grupo":"Kyčel a koleno","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"Lachmanův test","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"Koleno: menisky a čéška","lead":"Testy menisků a čéšky hledají příčinu bolesti kolene, blokád a pocitu nestability při rotaci nebo dopadu. Rozhodnutí přináší souhrn více nálezů.","sheet":{"kind":"tests","tests":[{"name":"McMurrayův test","alias":"","steps":"Leh na zádech, maximálně flektujte koleno a následně postupně extendujte bérce za současné zevní nebo vnitřní rotace.","positive":"Lupnutí nebo bolest v kloubní štěrbině.","tissue":"Meniskus (vnitřní a zevní)","point":"Zevní rotací vyšetřujete vnitřní, vnitřní rotací zevní meniskus. Samo o sobě není průkazné."},{"name":"Apleyův test","alias":"Apleyův kompresní test","steps":"Leh na břiše, koleno ve 90° flexi. Tlakem směrem dolů od paty rotujte bérce dovnitř a ven.","positive":"Bolest v kloubní štěrbině při kompresi a rotaci.","tissue":"Meniskus","point":"Pokud při rotaci s distrakcí pociťujete bolest, myslete spíše na vazivovou nebo jinou strukturu než na meniskus."},{"name":"Thessaly test","alias":"","steps":"Vyšetřující drží obě ruce pacienta. V jednonohém stoju, ve 20° flexi kolene pacient rotuje trupem a kolenem dovnitř a ven. Začněte na zdravé straně.","positive":"Bolest v kloubní štěrbině, pocit zablokování nebo zaskakování.","tissue":"Meniskus","point":"Test v zatížené pozici. Dbejte na riziko pádu, zajistěte oporu obou rukou."},{"name":"Patelární apprehenzní test","alias":"","steps":"Leh na zádech, mírně pokrčené koleno. M. quadriceps femoris je uvolněný, čéšku pomalu posunujte do strany (laterálně).","positive":"Objevuje se strach, pacient se brání napnutím quadricepsu.","tissue":"Patelární stabilizátory (lig. patellofemorale med.)","point":"Užitečné k potvrzení dřívější dislokace nebo subluxace čéšky. Provádějte opatrně, neprovokujte luxaci."}]},"keypoints":["Bolest v kloubní štěrbině je důležitým nálezem poukazujícím na poranění menisku","Testy menisků nejsou samostatně průkazné, porovnejte více nálezů","Zablokování bránící plné extenzi (locking) vyžaduje konzultaci s lékařem.","U patelárních testů sledujte reakci strachu a provádějte je opatrně","U testů v zatížené pozici zajistěte oporu jako prevenci pádu"],"case":{"text":"35letý muž. Došlo k otočení s pokrčeným kolenem, za několik hodin koleno oteklo. Na schodech pociťuje blokádu na vnitřní straně kolene. Vnitřní kloubní štěrbina je citlivá na tlak, McMurrayův test je bolestivý s lupnutím.","answer":"Pozdřeni na poranění vnitřního menisku. Vyšetřete i sdružené poranění vazů a odešlete pacienta k lékařskému zobrazovacímu vyšetření. V případě blokády neuvolňujte extenzi násilím."},"questions":[{"level":"Základní","q":"Který test na obrázku provádí kompresi a rotaci v lehu na břiše při 90° v koleni?","options":["McMurrayův test","Thessaly test","Apleyův test","Patelární apprehenzní test"],"answer":2,"exp":"Apleyův test v lehu na břiše při 90° flexi kolene rotuje za současného tlaku na patu a vyšetřuje meniskus."},{"level":"Základní","q":"Který nález podle souhrnu na obrázku poukazuje na poranění menisku?","options":["Bolest v kloubní štěrbině","Bolest nad čéškou","Bolest v oblasti tuberositas tibiae","Bolest na zadní straně stehna"],"answer":0,"exp":"Bolest kloubní štěrbiny (mezi stehenní a holenní kostí) poukazuje na poranění menisku."},{"level":"Pokročilý","q":"Co primárně vyšetřuje extenze bérce za současné zevní rotace v rámci McMurrayova testu?","options":["Zevní meniskus","Vnitřní meniskus","Přední zkřížený vaz","Patelární vaz"],"answer":1,"exp":"Zevní rotací vyšetřujeme vnitřní meniskus, vnitřní rotací zevní meniskus."},{"level":"Pokročilý","q":"Jaký je pozitivní nález při testu patelární aprehence?","options":["Lupnutí v oblasti čéšky","Bolest vnitřní kloubní štěrbiny","Omezená extenze kolene","Strach a stažení m. quadriceps"],"answer":3,"exp":"Pokud pacient při laterálním posunu čéšky pociťuje strach a aktivuje m. quadriceps, je test pozitivní: poukazuje na instabilitu čéšky."},{"level":"Klinický","q":"18letá žena. Při dopadu po skoku měla pocit vykloubení čéšky, která se sama vrátila na místo. Které vyšetření je nejvhodnější?","options":["Patelární apprehenzní test","Zadní zásuvkový test","Thompsonův test","Varózní zátěžový test"],"answer":0,"exp":"Průběh poukazující na luxaci nebo subluxaci čéšky. Instabilitu ověřte pomocí testu patelární aprehence."},{"level":"Klinický","q":"40letý muž. Již delší dobu ho v koleni „lupká“ na vnitřní straně, od dnešního rána ho nemůže zcela natáhnout. Jaký je správný postup?","options":["Provést násilnou pasivní extenzi k nápravě","Obratit se na lékaře a vyžádat si vyšetření","Opakovat Thessalyho test","Okamžitě zahájit posilování"],"answer":1,"exp":"Zablokování bránící extenzi může poukazovat na vklíněný meniskus, je nutné lékařské vyšetření. Vyhněte se násilné extenzi a opakování testů."}],"seccion":"Speciální testy podle regionů","grupo":"Kyčel a koleno","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"McMurrayův test","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"Hlezno a noha","lead":"Pomocí testů hlezna a nohy odlišujeme poranění vazů způsobené podvrtnutím a rupturu Achillovy šlachy. Je nutné vždy myslet na možnost zlomeniny.","sheet":{"kind":"tests","tests":[{"name":"Thompsonův test","alias":"Simmondsův test","steps":"Bříchem dolů, nohy visí přes okraj lůžka. Stiskněte svalové bříško m. triceps surae.","positive":"Žádná plantární flexe v gležni nebo je zřetelně menší než na zdravé straně.","tissue":"Achillova šlacha","point":"I při ruptuře může být aktivní plantární flexe (např. ohýbači prstů), proto je tento test užitečný."},{"name":"Test přední zásuvky (hlezno)","alias":"","steps":"Sedo nebo leh na zádech, hlezno v mírné plantární flexi. Fixujte distální tibii, uchopte patu a táhněte talus dopředu.","positive":"Větší přední posun než na zdravé straně, nejistý koncový pocit.","tissue":"Lig. talofibulare anterius","point":"Vyšetřuje vaz nejčastěji poraněný při inverzním zvrtnutí. V akutní fázi provádějte s ohledem na bolest."},{"name":"Test talární klapky (tilt test)","alias":"Varózní zátěžový test","steps":"Fixujte distální bérec, uchopte calcaneus a naklánějte hlezno do inverze.","positive":"Větší náklon talu než na zdravé straně, bolest.","tissue":"Lig. calcaneofibulare (lig. talofib. ant.)","point":"Závažnost poranění postranního vazu posuďte společně s testem přední zásuvky."},{"name":"Squeeze test (stlačovací test)","alias":"","steps":"Leh na zádech. Oběma rukama stiskněte tibii a fibulu uprostřed bérce.","positive":"Bolest nad hleznem, mezi tibii a fibulou.","tissue":"Distální tibiofibulární vazy (syndesmóza)","point":"Použijte při podezření na vysoký podvrtnutí kotníku. Důležité je také vyloučit zlomeninu."}]},"keypoints":["Při inverzním zvrtnutí se nejčastěji poraní lig. talofibulare anterius","I při ruptuře Achillovy šlachy může být přítomna aktivní plantární flexe","Při kostní citlivosti na tlak nebo neschopnosti zatížení myslete na zlomeninu, odesílejte k lékaři","Vazivové testy hodnotte vždy v porovnání se zdravou stranou","Bolest mezi tibii a fibulou může ukazovat na vysoký podvrtnutí kotníku"],"case":{"text":"45letý muž. Při tenisu měl pocit, že ho někdo kopnul zezadu. Nemůže stoupnout na špičky. V bříšku dolů při stlačení m. triceps surae není přítomna plantární flexe.","answer":"Pozitivní Thompsonův test: Podezření na rupturu Achillovy šlachy. Urychleně odesílejte k lékařskému vyšetření. Přítomnost aktivní plantární flexe nevylučuje rupturu."},"questions":[{"level":"Základní","q":"Kterou strukturu vyšetřuje Thompsonův test?","options":["Lig. talofibulare anterius","Achillova šlacha","Lig. calcaneofibulare","Plantární aponeuróza"],"answer":1,"exp":"Při stlačení m. triceps surae sledujeme, zda dojde k plantární flexi: vyšetřuje kontinuitu Achillovy šlachy."},{"level":"Základní","q":"Který vaz se nejčastěji poraní při inverzním zvrtnutí?","options":["Lig. talofibulare posterius","Lig. deltoideum","Lig. calcaneofibulare","Lig. talofibulare anterius"],"answer":3,"exp":"Poranění vzniká nejčastěji při inverzi spojené s plantární flexí, nejčastěji se poraní lig. talofibulare anterius. V těžších případech i lig. calcaneofibulare."},{"level":"Pokročilý","q":"Který vaz vyšetřuje test talární klapky především?","options":["Lig. calcaneofibulare","Lig. deltoideum","Achillova šlacha","Šlacha m. tibialis posterior"],"answer":0,"exp":"Nakloněním calcaneu do inverze sledujeme náklon talu, čímž vyšetřujeme především lig. calcaneofibulare."},{"level":"Pokročilý","q":"Při squeeze testu se objevuje bolest nad hleznem. Co si myslíte?","options":["Ruptura Achillovy šlachy","Plantární fasciitida","Poranění distálních tibiofibulárních vazů","Hallux valgus"],"answer":2,"exp":"Pokud stlačení střední části bérce v oblasti distálního tibiofibulárního kloubu vyvolává bolest, existuje podezření na poranění syndesmózy (vysoký výron hlezna)."},{"level":"Klinický","q":"22letý muž, inverzní poranění. Otok a bolestivost na tlak před zevním kotníkem; kostní citlivost přítomna není. Který test vyšetřuje lig. talofibulare anterius?","options":["Test přední zásuvky (hlezno)","Thompsonův test","Lachmanův test","Squeeze test (stlačovací test)"],"answer":0,"exp":"Lig. talofibulare anterius brzdí dopředný posun talu. Vyšetřujete ho předním zásuvkovým testem hlezna v porovnání se zdravou stranou."},{"level":"Klinický","q":"60letá žena. Upadla a vykloubila si kotník. Na zevním kotníku je přítomna kostní citlivost na tlak, při zátěži nemůže chodit. Jaký je správný postup?","options":["Opakovat přední zásuvkový test","Odeslat k lékaři s podezřením na zlomeninu","Okamžitě zahájit rovnovážná cvičení","Nácvik chůze s tejpem"],"answer":1,"exp":"Kostní citlivost na tlak a neschopnost zatížení poukazují na zlomeninu. Před prováděním zátěžových testů a cvičení je nutné lékařské vyšetření."}],"seccion":"Speciální testy podle regionů","grupo":"Hlezno a noha","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"Thompsonův test","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"Thompsonův test","rotulo":"Vyšetřuje","texto":"Achillova šlacha","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"Neurologické a neurodynamické testy","lead":"Při neurodynamických testech nervový systém postupně protahujeme a sledujeme reprodukci příznaků. Pomáhají odlišit bolest kořenového a periferního nervového původu.","sheet":{"kind":"tests","tests":[{"name":"Lasègueův příznak (SLR test)","alias":"Test zvedání natažené dolní končetiny","steps":"V lehu na zádech pasivně zvedáte dolní končetinu s nataženým kolenem. Zaznamenáte úhel objevení příznaků a dorzální flexí ověříte jejich zesílení.","positive":"Příznaky se reprodukují, např. bolest vyzařující z hýždě do zadní plochy dolní končetiny.","tissue":"N. ischiadicus, kořeny L5 a S1 atd.","point":"K odlišení zkrácení hamstringů je užitečné přidat dorzální flexi hlezna nebo flexi krku."},{"name":"Test protažení n. femoralis","alias":"FNST (obrácený Lasègue)","steps":"V leže na břiše pasivně flektujte koleno. V případě potřeby přidejte extenzi kyčle.","positive":"Bolest vyzařující na přední plochu stehna.","tissue":"N. femoralis, nervové kořeny L2–L4","point":"Odlište od zkrácení kvadricepsu. Používá se k vyšetření postižení horních bederních nervových kořenů."},{"name":"Slump test","alias":"","steps":"V sedu postupně: flexe trupu → flexe krku → extenze kolena → dorzální flexe hlezna, poté uvolněte flexi krku a sledujte změnu.","positive":"Příznaky se reprodukují a uvolněním flexe krku mírní.","tissue":"Nervový systém od páteřního kanálu po dolní končetinu","point":"Postupujte po krocích a při objevení příznaků se zastavte. Porovnejte obě strany."},{"name":"Test horní končetiny na napětí nervu","alias":"ULNT1 (n. medianus)","steps":"Záda: deprese ramenního pletence, abdukce ramene, supinace předloktí, extenze zápěstí a prstů, zevní rotace, extenze lokte; nakonec úklon krku.","positive":"Příznaky na horní končetině se reprodukují a mění při bočním úklonu krku.","tissue":"N. medianus, krční kořeny","point":"Porovnejte se zdravou stranou. Pokud pohyb vzdálené části těla mění příznak, je pravděpodobnější nervový původ."}]},"keypoints":["Testy nervů posuzujte na základě reprodukce příznaků a stranového rozdílu","Pokud pohyb vzdálené části těla mění příznak, myslete na nervový původ","Svalové napětí a příznak nervového původu dokumentujte zvlášť","Při objevení příznaku se zastavte, neprovokujte silnou bolest","Při progredující paréze nebo potížích s močením a stolicí ihned k lékaři"],"case":{"text":"42letý muž. Po zvednutí těžkého břemene se objevila bolest v bederní oblasti a na zadní ploše pravé dolní končetiny. SLR test reprodukuje vyzařující bolest na zadní ploše pravé dolní končetiny, při dorzální flexi se zesiluje.","answer":"Nález poukazující na příznaky kořenového původu v bederní oblasti. Na základě svalové síly, citlivosti a reflexů určete postižený segment. V případě poruchy sfinkterů nebo progredující parézy ihned odešlete pacienta k lékaři."},"questions":[{"level":"Základní","q":"Který nerv protahuje SLR test především?","options":["N. medianus","N. femoralis","N. ischiadicus","N. ulnaris"],"answer":2,"exp":"Při zvedání dolní končetiny s nataženým kolenem se protahuje n. ischiadicus probíhající po zadní ploše a dolní bederní kořeny."},{"level":"Základní","q":"V jaké polohách provádíme test protažení n. femoralis?","options":["Břicho","Záda","Sed s nataženýma nohama","Stoj"],"answer":0,"exp":"V lehu na břiše flexí kolene protahujeme n. femoralis probíhající na přední ploše stehna."},{"level":"Pokročilý","q":"V SLR testu dorzální flexe kotníku zesílila příznaky. Na co to poukazuje?","options":["Zkrácení hamstringů","Příznak nervového původu","Kontraktura kyčle","Podvrtnutí kotníku"],"answer":1,"exp":"Dorzální flexe zvyšuje napětí nervu bez změny délky svalu. Pokud se příznak zesiluje, poukazuje to na nervový původ."},{"level":"Pokročilý","q":"Ve slump testu se při uvolnění flexe krku zmírnily příznaky na dolní končetině. Co si myslíte?","options":["Bolest při protažení svalu","Kloubní nestabilita","Bolest psychického původu","Zvýšená citlivost nervového systému"],"answer":3,"exp":"Pohyb krku nepůsobí na svaly dolní končetiny, takže změna příznaku poukazuje na postižení nervového systému."},{"level":"Klinický","q":"50letá žena. Mravenčení od přední strany stehna po vnitřní stranu kolene. V lehu na břiše flexe kolene reprodukuje bolest přední strany stehna. Který segment je podezřelý?","options":["L2–L4","L5","S1","C6"],"answer":0,"exp":"Pozitivní test protažení n. femoralis a příznaky na přední straně stehna: podezření na postižení horních bederních (L2–L4) kořenů."},{"level":"Klinický","q":"38letý muž. SLR test reprodukuje bolest dolní končetiny. V poslední době se mu špatně močí, v oblasti hradby je snížená citlivost. Jaký je správný postup?","options":["Opakovaně zkontrolovat SLR test","Posilování bederních svalů","Odeslat ihned k lékaři","Pokračovat v neurodynamických mobilizacích"],"answer":2,"exp":"Poruchy močení a snížená citlivost v oblasti hýždí a perineu představují červenou vlajku odkazující na syndrom cauda equina. Je nutné provést okamžité lékařské vyšetření."}],"seccion":"Speciální testy podle regionů","grupo":"Neurologické testy","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"Lasègueův příznak (SLR test)","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"Lasègueův příznak","rotulo":"Vyšetřuje","texto":"n. ischiadicus (L4–S1)","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"Subakromiální impingement a ruptura rotátorové manžety","lead":"Při subakromiálním impingementu dochází při zvedání paže k dráždění rotátorové manžety a bursa subacromialis, což vyvolává bolest. Je důležité odlišit jej od ruptury rotátorové manžety a zařadit postupné cvičební intervence.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Při elevaci paže dochází k dráždění a bolesti rotátorové manžety (především šlachy m. supraspinatus) a bursa subacromialis. V důsledku věku, přetížení nebo úrazu může dojít k ruptuře rotátorové manžety."},{"h":"Hlavní příznaky","t":"Bolest při elevaci (bolestivý oblouk), noční bolest, obtížné ležení na postižené straně. Při ruptuře je snížena síla při zvedání a zevní rotaci."},{"h":"Vyšetřovací hlediska","t":"Impingement vyšetřete Neerovým a Hawkinsův–Kennedyho testem, funkci rotátorové manžety posuďte Jobe testem a silou zevní rotace. Zhodnoťte také pohyb lopatky a držení těla."},{"h":"Průběh léčby","t":"Tlumení bolesti a regulace aktivity → zlepšení rozsahu pohybu (ROM) → postupposilování rotátorové manžety a periskapulárních svalů → nácvik pohybu, návrat do práce a sportu."},{"h":"Opatrnost, kontraindikace","t":"Vyhněte se opakovanému zvedání vyvolávajícímu bolest. Zátěž přizpůsobte rozsahu ruptury a lékařskému plánu, protahování neprovádějte násilně."},{"h":"Indikace k odeslání k lékaři","t":"Neschopnost zvednout paži po úrazu, progresivní slabost, zhoršující se klidová bolest, horečka nebo otok, mravenčení a další neurologické příznaky."}]},"keypoints":["Bolestivý oblouk a noční bolest jsou častými potížemi","Slabost při elevaci a zevní rotaci může odkazovat na rupturu rotátorové manžety","Zhodnoťte také pohyb lopatky a držení těla","Zátěž cvičení zvyšujte postupně v mezích bez bolesti","Při náhlé neschopnosti zvednout paži po úrazu odešlete pacienta k lékaři"],"case":{"text":"62letý muž. Již několik měsíců jej bolí rameno při abdukci, trpí i noční bolestí. Ve středním rozsahu elevace je bolest silná, Jobe test je pozitivní a bolestivý, patrná je i slabost.","answer":"Podezření na poškození šlachy m. supraspinatus nebo rupturu rotátorové manžety. Vyžádejte si výsledky lékařského zobrazovacího vyšetření a léčebný plán, v rozsahu pohybu (ROM) a při cvičení rotátorové manžety a periskapulárních svalů postupujte v mezích bez bolesti. Vyhněte se opakovanému zvedání zhoršujícímu bolest."},"questions":[{"level":"Základní","q":"Která šlacha probíhá pod akromionem a při elevaci se snadno dráždí?","options":["Šlacha m. supraspinatus","Šlacha m. teres minor","Šlacha m. pectoralis major","M. triceps brachii ina"],"answer":0,"exp":"Šlacha m. supraspinatus probíhá pod acromionem, proto se při elevaci spolu s bursa subacromialis snadno dráždí."},{"level":"Základní","q":"Jak nazýváme stav, kdy se bolest objevuje pouze ve středním rozsahu elevace ramene?","options":["Ramenní-ruční syndrom","Noční bolest","Bolestivý oblouk","Příznak padající paže"],"answer":2,"exp":"Pokud se bolest objevuje během elevace a při dalším zvednutí ustupuje, hovoříme o bolestivém oblouku. Vidíme jej u subakromiálních odchylek."},{"level":"Pokročilý","q":"Co vyšetřuje především Hawkinsův–Kennedyho test?","options":["Přední nestabilita ramene","Subakromiální impingement","Akromioklavikulární luxace","Syndrom horního hruního otvoru (TOS)"],"answer":1,"exp":"Při 90° flexi ramene s vnitřní rotací sledujeme, zda dochází k úžinu struktur pod acromionem a zda to bolí: impingement test."},{"level":"Pokročilý","q":"Který nález nejvíce ukazuje na rupturu rotátorové manžety?","options":["Omezená flexe lokte","Zvýšená síla stisku","Pouze mravenčení prstů","Slabost při elevaci a zevní rotaci"],"answer":3,"exp":"Rotátorová manžeta se podílí na elevaci a zevní rotaci. Slabost může ukazovat na rupturu, což potvrzuje lékařské zobrazení."},{"level":"Klinický","q":"58letá žena. Od pádu nemůže zvednout paži. Pasivně ji lze zvednout, aktivně ne. Co je nejpravděpodobnější?","options":["Zmrzlé rameno","Ruptura rotátorové manžety","Cervikální spondylóza","Luxace ramene"],"answer":1,"exp":"Pokud se paže pohybuje pasivně, ale nelze ji aktivně zvednout, jde o poruchu funkce svalu a šlachy; po traumatu je podezření na rupturu rotátorové manžety. U zamrzlého ramene je omezený i pasivní pohyb."},{"level":"Klinický","q":"45letý muž, subakromiální impingement s přetrvávající bolestí při elevaci. Jaké je vhodné počáteční terapeutické cvičení?","options":["Opakovaná elevace s tolerancí bolesti","Zvedání těžké činky","Cvičení rotátorové manžety v rámci prahu bolesti","Udržování úplného klidu"],"answer":2,"exp":"Začněte cvičením rotátorové manžety a okolí lopatky, které nezhoršují bolest, a zátěž zvyšujte postupně."}],"seccion":"Zranění a rehabilitace","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"Zmrzlé rameno","lead":"U zamrzlého ramene vzniká bolest a omezení pohybu postupně; je časté ve středním a starším věku. Léčbu musíte přizpůsobit fázi onemocnění.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Zánět a fibróza kloubního pouzdra ramene způsobují bolest a omezení pohybu. Příčina bývá často nejasná; byla popsána souvislost s cukrovkou."},{"h":"Hlavní příznaky","t":"Noční bolest, potíže při česání vlasů a zvedání ruky za záda. Aktivní i pasivní ROM je omezený, zejména zevní rotace."},{"h":"Vyšetřovací hlediska","t":"Porovnejte aktivní a pasivní ROM, zhodnoťte míru bolesti, noční bolest a potíže v ADL. Důležité je odlišení od jiných patologií, např. ruptury rotátorové manžety."},{"h":"Rehabilitace po fázích","t":"Zánětlivá fáze: tlumení bolesti a šetrný pohyb. Tuhá fáze: protažení a ROM cvičení v rámci prahu bolesti. Rozpustná fáze: obnovení ROM a svalové síly."},{"h":"Opatrnost, kontraindikace","t":"V zánětlivé fázi může silné protažení bolest zhoršit. Vyhněte se násilnému pasivnímu pohybu vyžadujícímu snášení bolesti."},{"h":"Indikace k odeslání k lékaři","t":"Posttraumatický začátek, náhlá slabost, horečka nebo otok, celkové příznaky (např. úbytek hmotnosti), náhlé zhoršení klidové bolesti."}]},"keypoints":["Je charakteristické, že aktivní i pasivní ROM je omezený","Nápadné je zejména omezení zevní rotace","V zánětlivé fázi se vyhněte protažení zvyšujícímu bolest","Měňte cíl léčby podle jednotlivých fází","Odlište od jiných patologií, např. ruptury rotátorové manžety"],"case":{"text":"55letá žena. Bez vyvolávající příčiny začalo rameno bolet, v noci nemůže spát bolestí. Během několika měsíců se ztížilo česání vlasů a zvedání ruky za záda; zevní rotace je aktivně i pasivně silně omezena.","answer":"Pozdředení na zmrzlé rameno. Lékařskou diagnózou vylučte ostatní patologie a určete aktuální fázi. Při silné bolesti se vyhněte prudkému protahování; začněte tlumením bolesti a šetrným pohybem."},"questions":[{"level":"Základní","q":"Který pohyb je u zmrzlého ramene obzvláště omezen?","options":["Flexe lokte","Dorzální flexe zápěstí","Elevace lopatky","Zevní rotace ramene"],"answer":3,"exp":"U zmrzlého ramene je v důsledku zkrácení pouzdra rameno omezeno v mnoha směrech, zejména zevní rotace."},{"level":"Základní","q":"Ve které fázi zmrzlého ramene bolest ustupuje a do popředí vystupuje omezení pohybu?","options":["Zánětlivá fáze","Fáze tuhnutí","Fáze rozvolňování","Akutní fáze"],"answer":1,"exp":"Když silná bolest v zánětlivé fázi ustoupí, následuje tuhá fáze charakterizovaná omezením pohybu a poté rozpustná fáze."},{"level":"Pokročilý","q":"Který nález pomáhá odlišit zmrzlé rameno od ruptury rotátorové manžety?","options":["Přítomnost noční bolesti","Omezení pasivního ROM","Věk","Místo bolesti"],"answer":1,"exp":"U zmrzlého ramene je pasivní ROM také omezený. Při ruptuře rotátorové manžety se pasivně pohybuje relativně dobře, ale aktivně lze rameno zvednout jen obtížně."},{"level":"Pokročilý","q":"Jaká je nejvhodnější léčba v zánětlivé fázi zmrzlého ramene?","options":["Tlumení bolesti, šetrný pohyb","Silné pasivní protažení","Posilování s vysokou zátěží","Trénink návratu ke sportu"],"answer":0,"exp":"V zánětlivé fázi je bolest silná, silné protažení může stav zhoršit. Hlavním prvkem je tlumení bolesti a pohyb nezvyšující bolest."},{"level":"Klinický","q":"52letá žena, zmrzlé rameno v tuhé fázi. Bolest je mírná, zevní rotace a zvednutí ruky za záda jsou omezené. Jaká je správná léčba?","options":["Úplný klid","Fixace závěsným šátkem","ROM cvičení v rámci prahu bolesti","Silné protažení snášející bolest"],"answer":2,"exp":"V tuhé fázi již bolest ustoupila, proto postupujte s protažením a ROM cvičeními v rámci prahu bolesti."},{"level":"Klinický","q":"60letý muž. Kromě bolesti ramene a omezení pohybu v poslední době hubne a má silnou klidovou bolest. Jaký je správný postup?","options":["Odeslat k lékaři","Zvýšení rozsahu pohybu (ROM)","Pouze termoterapie a sledování","Zahájení posilování"],"answer":0,"exp":"Úbytek hmotnosti a silná klidová bolest jsou varovné příznaky (červené vlajky) poukazující na závažné onemocnění. Nejprve je odešlete k lékařskému vyšetření."}],"seccion":"Zranění a rehabilitace","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"Po sutuře rotátorové manžety","lead":"Rehabilitace po sutuře rotátorové manžety postupně obnovuje rozsah pohybu (ROM) a svalovou sílu při současné ochraně šlachy. Základní podmínkou je dodržení termínů a omezení stanovených lékařem.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Přetrženou rotátorovou manžetu vám chirurgicky přišijí zpět ke kosti. Hojení zašité šlachy ke kosti vyžaduje čas, předčasná zátěž může způsobit re-rupturu."},{"h":"Hlavní příznaky","t":"Pooperační a noční bolest, omezení pohybu, slabost. Kvůli ortéze může být ramenní pletenec a krk tuhý, pohyb v loktu a ruce může být také snížen."},{"h":"Vyšetřovací hlediska","t":"Zhodnoťte bolest, pasivní a aktivní rozsah pohybu (ROM), pohyb lopatky, svalovou sílu a ADL. Prostudujte operační protokol a pokyny lékaře (zakázané pozice, termíny)."},{"h":"Rehabilitace po fázích","t":"Ochranná fáze (ortéza, pasivní pohyb) → aktivní cvičení s asistencí a aktivní pohyb → postupné posilování → návrat k denním aktivitám, práci a sportu."},{"h":"Opatrnost, kontraindikace","t":"Vyhněte se aktivnímu zvedání a cvičení proti odporu před stanoveným termínem a také polohám silně protahujícím sešitou šlachu. Loket a prsty procvičujte i během fixace."},{"h":"Indikace k odeslání k lékaři","t":"Náhlé zhoršení bolesti nebo snížení síly v paži (podezření na re-rupturu), zarudnutí v okolí rány, otok, horkost, horečka, výskyt brnění."}]},"keypoints":["Zkontrolujte termíny a zakázané pozice v lékařské zprávě a operačním protokolu","V ochranné fázi chraňte sešitou šlachu, v centru pozornosti je pasivní pohyb","I během fixace procvičujte loket, prsty a lopatku","Cvičení proti odporu zařazujte postupně od předepsaného termínu","Při náhlém poklesu zvedací síly myslete na re-rupturu, odešlete pacienta k lékaři"],"case":{"text":"60letý muž, včasné pooperační období po sutuře rotátorové manžety, nosí ortézu. Protože se chce rychle vrátit do práce, cvičil zvedání paže sám.","answer":"Nepředepsané aktivní zvedání v ochranné fázi zatěžuje sešitou šlachu. Zkontrolujte pokyny lékaře, soustřeďte se na povolený pasivní pohyb a cvičení lokte a prstů a vysvětlete, proč je důležité dodržovat termíny."},"questions":[{"level":"Základní","q":"Jaký je hlavní cíl ortézy v časné fázi po sutuře rotátorové manžety?","options":["Zvýšení svalové síly","Zvětšení rozsahu pohybu (ROM)","Ochrana sešité šlachy","Prevence otoků"],"answer":2,"exp":"V ochranné fázi ortéza fixuje a chrání sešitou šlachu, dokud se nezhojí kosti."},{"level":"Základní","q":"Co zavádíme jako poslední v rehabilitaci po suturách rotátorové manžety?","options":["Fixace ortézou","Pasivní pohyb","Aktivní pohyb s asistencí","Cvičení proti odporu"],"answer":3,"exp":"Po fixaci a pasivním pohybu v ochranné fázi následuje aktivní asistovaný a aktivní pohyb, nakonec odporové posilování."},{"level":"Pokročilý","q":"Kterému pohybu se musíte vyhnout v ochranné fázi po sutuře?","options":["Aktivní elevace ramene před předepsaným termínem","Aktivní flexe–extenze lokte","Cvičení prstů","Předepsaný pasivní pohyb"],"answer":0,"exp":"V ochranné fázi zatěžuje nepředepsaná aktivní elevace ramene zašitou šlachu. Pohyb lokte a prstů je nutné pokračovat i během fixace."},{"level":"Pokročilý","q":"Co musíte zkontrolovat jako první, když plánujete postup pooperačních cvičení?","options":["Pouze přání pacienta","Lékařský pokyn a operační protokol","Svalovou sílu zdravé strany","Pouze věk"],"answer":1,"exp":"V závislosti na velikosti ruptury a technice sutury se termíny a zakázané pozice liší, proto zkontrolujte pokyny a protokol."},{"level":"Klinický","q":"65letá žena po sutuře rotátorové manžety pokročila dobře, ale při zvednutí předmětu pocítila bolest a náhle nedokáže zvednout paži. Co je nutné udělat?","options":["Zvýšení odporového cvičení","Pokračování ve stejném cvičení","Silný protažení","Nahlásit lékaři, vyžádat vyšetření"],"answer":3,"exp":"Náhlá bolest a pokles síly při zvedání mohou ukazovat na re-rupturu. Zastavte cvičení a vyžádejte si lékařské vyšetření."},{"level":"Klinický","q":"58letý muž po sutuře rotátorové manžety v ortéze. Stěžuje si na ztuhlost lokte a prstů. Jaký je správný postup?","options":["Nácvik cvičení lokte a prstů","Zahájení aktivní elevace ramene","Nic, pokračovat ve fixaci","Odporové cvičení ramene"],"answer":0,"exp":"Pohybujte loktem a prsty i během fixace, abyste předešli ztuhlosti. Aktivní elevace ramene a odpor musí počkat do předepsaného termínu."}],"seccion":"Zranění a rehabilitace","grupo":"Rameno","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"Tendinopatie","lead":"Při tendinopatii se šlacha nedokáže přizpůsobit opakované zátěži, což vede k bolesti a poklesu funkce. Klíčem k uzdravení není odpočinek, nýbrž regulace zátěže a její postupné zvyšování.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Opakovaná zátěž působící na šlachu přesahuje regeneraci, struktura a funkce šlachy se mění a objevuje se bolest. Častou spouštěcí příčinou je náhlé zvýšení objemu tréninku."},{"h":"Hlavní příznaky","t":"Bolest a ztuhlost na začátku pohybu a následující ráno, lokální citlivost šlachy na tlak. Během pohybu může polevit, po zátěži se může zhoršit."},{"h":"Vyšetřovací hlediska","t":"Vyšetřete citlivost šlachy na tlak, bolest při zátěži (výpon na jedné noze, dřep na jedné noze) a zeptejte se na změny v objemu tréninku, obuvi a povrchu."},{"h":"Průběh léčby","t":"Regulace zátěže → izometrické cviky → izotonické posilování (včetně excentriky) → rychlé pohyby, např. skoky → návrat ke sportu."},{"h":"Opatrnost, kontraindikace","t":"Úplný klid může snížit zatížitelnost šlachy. Vyhněte se zátěži, která výrazně zhoršuje bolest, a silné bolesti přetrvávající do druhého dne."},{"h":"Indikace k odeslání k lékaři","t":"Pocit náhlého prasknutí nebo lupnutí, jasná slabost, výrazný otok a hřejivost, nelepšící se noční bolest nebo bolest v klidu."}]},"keypoints":["Náhlé zvýšení objemu tréninku často vyvolává tendinopatii.","Místo úplného klidu regulujte zátěž s ohledem na bolest.","Množství zátěže upravte na základě bolesti po zátěži a následující den.","Od izometrických cviků postupujte pozvolna směrem k vyšší zátěži.","V případě pocitu prasknutí nebo náhlé slabosti odešlete pacienta k lékaři."],"case":{"text":"28letý běhající muž. Od chvíle, kdy náhle zvýšil běžeckou vzdálenost, má ráno dlouhodobě tuhou a bolestivou Achillovu šlachu. Na začátku běhu bolí, během něj to ustupuje. Ve střední části šlachy je citlivost na tlak.","answer":"Pozdřeni na tendinopatii achillovky. Neordinujte úplný klid, ale regulujte objem běhu a postupujte s progresivní zátěží přizpůsobenou bolesti, např. výponny na patách. V případě pocitu prasknutí nebo slabosti odešlete pacienta k lékaři."},"questions":[{"level":"Základní","q":"Která je typická vyvolávající příčina tendinopatie?","options":["Dlouhý odpočinek","Náhlé zvýšení objemu tréninku","Dostatek spánku","Zlepšující se flexibilita"],"answer":1,"exp":"Zátěž převyšující regeneraci šlachy, zejména náhlé zvýšení objemu tréninku, je typickou vyvolávající příčinou tendinopatie."},{"level":"Základní","q":"Jaká charakteristika bolesti je častá u tendinopatie?","options":["Pouze silná noční bolest","V klidu se neustále zhoršuje","Vždy stejné intenzity","Bolest na začátku pohybu, ranní tuhost"],"answer":3,"exp":"Na začátku pohybu a druhý den ráno se objevuje bolest a tuhost, které během pohybu často polevují."},{"level":"Pokročilý","q":"Co zavádíme při postupném zatěžování u tendinopatie poměrně pozdě?","options":["Izometrický cvik","Pomalé posilování svalů","Rychlé pohyby, např. skoky","Regulace zátěže"],"answer":2,"exp":"Pod kontrolou bolesti zvyšujete zatížitelnost izometrickými a izotonickými cviky a následně přecházíte na rychlé pohyby, např. skoky."},{"level":"Pokročilý","q":"Jaký je vhodný záchytný bod pro přehodnocení zátěže u tendinopatie?","options":["Změna bolesti druhý den","Změna tělesné hmotnosti","Teplota","Denní doba tréninku"],"answer":0,"exp":"Sledujte nejen bolest během pohybu, ale i změnu bolesti a tuhosti následující den, a podle toho upravte zátěž."},{"level":"Klinický","q":"22letá volejbalistka. Po skokech ji bolí dolní pól čéšky, patelární vaz je citlivý na tlak. Co je nejpravděpodobnější?","options":["Poranění předního zkříženého vazu","Patelární tendinopatie","Poranění menisku","Luxace čéšky"],"answer":1,"exp":"Opakované skoky a citlivost na tlak v oblasti dolního pólu čéšky a patelárního vazu jsou charakteristické pro patelární tendinopatii."},{"level":"Klinický","q":"40letý muž, kterého léčíte s achillovskou tendinopatií. Při tenisu měl pocit, že ho někdo kopnul zezadu; nedokáže stát na špičkách. Jaký je další postup?","options":["Pokračování v excentrických cvicích","Další zvyšování zátěže","Zvýšení protažení","Odeslat k lékaři při podezření na rupturu"],"answer":3,"exp":"Pocit náhlého úderu a neschopnost stoupnout si na špičku ukazují na rupturu Achillovy šlachy. Zastavte cvičební jednotku a odešlete pacienta k lékařskému vyšetření."}],"seccion":"Zranění a rehabilitace","grupo":"Sport, šlachy a svaly","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"Distorze hlezna","lead":"Podvrtnutí hlezna je jedno z nejčastějších sportovních zranění; většinou vzniká při inverzi spojené s plantární flexí. V prevenci opakovaného podvrtnutí je klíčový proprioceptivní trénink.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Při inverzi spojené s plantární flexí dochází k poškození zevních vazů. Nejčastěji se poraní lig. talofibulare anterius, v závažnějších případech i lig. calcaneofibulare."},{"h":"Hlavní příznaky","t":"Bolest, otok a podlitina v okolí zevního kotníku, bolest při zatížení. Pacient může referovat o pocitu nestability nebo opakovaných luxacích."},{"h":"Vyšetřovací hlediska","t":"Mechanismus úrazu, místo bolestivosti na tlak, zatížitelnost, test přední zásuvky a test talus tilt. Nepřehlédněte zlomeninu a poranění jiných vazů."},{"h":"Rehabilitace po fázích","t":"1 ochrana, chlazení, komprese, elevace → 2 mobilita a postupné zatěžování → 3 posílení svalů a propriocepce → 4 běh, skoky, návrat ke sportu."},{"h":"Opatrnost, kontraindikace","t":"V akutní fázi se vyhněte cvikům zvyšujícím bolest. Pokud vynecháte proprioceptivní a rovnovážná cvičení, podvrtnutí se snadno vrátí a přetrvá pocit nestability."},{"h":"Indikace k odeslání k lékaři","t":"Kostní citlivost na tlak nebo neschopnost zatížení (podezření na zlomeninu), výrazný otok či deformita, mravenčení, neustupující bolest nebo opakovaná nestabilita."}]},"keypoints":["Mechanismus úrazu je většinou inverze spojená s plantární flexí","Nejčastěji je poškozeno lig. talofibulare anterius","V případě kostní citlivosti na tlak nebo neschopnosti zatížení myslete na zlomeninu","Proprioceptivní trénink snižuje riziko recidivy","Návrat ke sportu je postupný, po kontrole pohybů na jedné končetině"],"case":{"text":"19letý muž. Během fotbalu se mu podvrtla noha dovnitř. Druhý den je před zevním kotníkem otok a citlivost na tlak, kostní citlivost na tlak přítomna není, nohu zatížit zvládne. U testu přední zásuvky je přední posun větší než na zdravé straně.","answer":"Podezření na inverzní podvrtnutí s poraněním lig. talofibulare anterius. Začněte ochranou, chlazením, kompresí, elevací a zátěží přizpůsobenou bolesti, následně po posílení svalů a proprioceptivním cvičení zajistěte postupný návrat ke sportu."},"questions":[{"level":"Základní","q":"Který je typický mechanismus úrazu podvrtnutí hlezna na obrázku?","options":["Everze spojená s dorzální flexí","Inverze spojená s plantární flexí","Inverze spojená s dorzální flexí","Everze spojená s plantární flexí"],"answer":1,"exp":"Podvrtnutí hlezna vzniká nejčastěji při inverzi spojené s plantární flexí a nejčastěji se poraní zevní lig. talofibulare anterius."},{"level":"Základní","q":"Jaký je obsah 3. fáze na obrázku?","options":["Ochrana, chlazení, komprese, elevace","Mobilita a postupné zatěžování","Posílení svalů a propriocepce","Běh, návrat ke sportu"],"answer":2,"exp":"1. fáze: ochrana, chlazení, komprese, elevace; 2.: mobilita a zátěž; 3.: posílení svalů a propriocepce; 4.: návrat ke sportu."},{"level":"Pokročilý","q":"Ve které fázi začíná postupné zatěžování?","options":["1. fáze","2. fáze","3. fáze","4. fáze"],"answer":1,"exp":"Po ochraně v 1. fázi ve 2. fázi spolu se zlepšením mobility postupně zvyšujete zátěž s ohledem na bolest."},{"level":"Pokročilý","q":"Které cvičení je obzvláště důležité v prevenci recidivy podvrtnutí hlezna?","options":["Dlouhá fixace","Úplný klid","Posílení svalů horní končetiny","Proprioceptivní trénink"],"answer":3,"exp":"Proprioceptivní trénink na rovnovážné desce nebo ve stoju na jedné noze snižuje riziko recidivy."},{"level":"Klinický","q":"24letá žena. 3 týdny po podvrtnutí téměř necítí bolest, ale při stoji na jedné noze se jí kotník kývá. Která léčba má přednost?","options":["Rovnovážná a proprioceptivní cvičení","Chlazení a polohování","Úplný klid","Okamžitý sprint v plné rychlosti"],"answer":0,"exp":"Bolest ustoupila, ale instabilita přetrvala. Přednost mají proprioceptivní a posilovací cvičení ve stoju na jedné noze, následované postupným návratem."},{"level":"Klinický","q":"20letý muž. Kotník si již mnohokrát podvrtnul a i v každodenním životě cítí nestabilitu. Co předpokládáte?","options":["Ruptura Achillovy šlachy","Plantární fasciitida","Chronická instabilita hlezna","Hallux valgus"],"answer":2,"exp":"Opakované vykloubení a pocit nestability poukazují na chronickou nestabilitu hlezna. Proprioceptivní a posilovací cvičení jsou důležitá, v případě potřeby konzultujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Sport, šlachy a svaly","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"Svalová poranění","lead":"Svalové zranění je sportovní úraz, jehož dvěma hlavními formami jsou svalové natažení (částečná ruptura) a pohmoždění svalu. Často recidivuje, proto je důležité postupné zatěžování a stanovení kritérií pro návrat.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Natažení vzniká hlavně při excentrické kontrakci (napnutý sval se prodlužuje), nejčastěji na svalovo-šlachovém přechodu. Pohmoždění je zranění způsobené přímou vnější silou, zejména v m. quadriceps femoris."},{"h":"Hlavní příznaky","t":"Bolest nebo pocit prasknutí při úrazu, citlivost na tlak, otok, krevní výron, bolest při protažení a odporu, pokles síly. V těžkých případech je hmatatelná retrakce."},{"h":"Vyšetřovací hlediska","t":"Mechanismus zranění, citlivé místo na tlak, bolest při protažení (např. stranový rozdíl úhlu SLR), bolest při odporu, vzor chůze. Závažnost posuzuje lékař spolu s nálezy zobrazovacích metod."},{"h":"Rehabilitace po fázích","t":"V akutní fázi ochrana a kontrola otoku. Podle bolesti izometrická → koncentrická → excentrická práce, běh také postupně. Před návratem zkontrolujte sportovní pohyby."},{"h":"Opatrnost, kontraindikace","t":"V akutní fázi se vyhněte silnému protažení a hluboké masáži. Silný podnět po pohmoždění stehna může vyvolat myositis ossificans. Necvičte přes bolest."},{"h":"Indikace k odeslání k lékaři","t":"Zřetelný hmatatelný defekt či pocit prasknutí, rychle narůstající otok, přetrvávající silná bolest, mravenčení nebo změna barvy kůže (podezření na compartment syndrom)."}]},"keypoints":["Natažení je nejčastější při excentrické kontrakci na svalovo-šlachovém přechodu","V akutní fázi ochrana a kontrola otoku, bez silného protažení","Pořadí zátěže: izometrická → koncentrická → excentrická","U hamstringů zařaďte excentrický trénink","O návratu rozhodujte na základě bolesti, flexibility, svalové síly a sportovního pohybu"],"case":{"text":"20letý muž, sprinter. Během sprintu v plné rychlosti pocítil bolest na zadní straně stehna a přerušil závod. Následující den citlivost na tlak nad m. biceps femoris a krevní výron, při SLR stranový rozdíl a bolest při protažení.","answer":"Předpokládáme natažení hamstringů. V akutní fázi je prioritou ochrana a kontrola otoku, vyhněte se silnému protažení a masáži. Podle bolesti začněte izometrickou prací a postupně zvyšujte zátěž. V případě retrakce nebo jiných závažných příznaků navštivte lékaře."},"questions":[{"level":"Základní","q":"Kde nejčastěji dochází k natažení svalu?","options":["Uprostřed svalového bříška","Na svalovo-šlachovém přechodu","V okostnici","V úponu šlachy na kost"],"answer":1,"exp":"Natažení vzniká nejčastěji na přechodu svalu a šlachy. U hamstringů postihuje zejména caput longum m. biceps femoris."},{"level":"Základní","q":"Při které formě kontrakce dochází nejčastěji k natažení svalu?","options":["Izometrická","Koncentrická","Excentrická","Izokinetická"],"answer":2,"exp":"Při excentrické kontrakci, kdy se napnutý sval prodlužuje; typickou situací je konec švihové fáze při sprintu."},{"level":"Pokročilý","q":"Jaké je obvyklé pořadí posilování po natažení svalu?","options":["Excentrická → koncentrická → izometrická","Izometrická → koncentrická → excentrická","Koncentrická → izometrická → excentrická","Ihned maximální excentrická práce"],"answer":1,"exp":"Podle bolesti začněte nízkozátěžovou izometrickou prací, poté následuje koncentrická a nakonec excentrická kontrakce."},{"level":"Pokročilý","q":"Proč se po kontuzi stehna vyhýbáme silné masáži a protažení?","options":["Může vyvolat myositis ossificans","Vymizí svalová atrofie","Šlacha se zkrátí","Zastaví se regenerace nervu"],"answer":0,"exp":"Časný silný podnět po kontuzi může zvýšit krvácení ve svalu a vést ke vzniku myositis ossificans."},{"level":"Klinický","q":"Fotbalista: při kopnutí se objevila bolesť na přední straně stehna, druhý den je citlivá na tlak a bolí při protažení. Jaký je správný postup v akutní fázi?","options":["Silný protažení","Ochrana a kontrola otoku","Kontrola plným sprintem","Hloubková masáž"],"answer":1,"exp":"V akutní fázi je prioritou ochrana a kontrola otoku. Silné protažení, masáž a maximální pohybový test mohou zranění zhoršit."},{"level":"Klinický","q":"Středoškolák, silný úder do stehna. Otok rychle narůstá, stěžuje si na silnou bolest a mravenčení v noze. Jaký je primární postup?","options":["Tepelná terapie","Nácvik protažení","Okamžité odeslání k lékaři","Zahájení posilování"],"answer":2,"exp":"Rychle rostoucí otok, silná bolest a mravenčení ukazují na compartment syndrom, je nutné urgentní lékařské vyšetření."}],"seccion":"Zranění a rehabilitace","grupo":"Sport, šlachy a svaly","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"Poranění předního zkříženého vazu a menisku","lead":"Poranění ACL je časté při sportu, při dopadu nebo změně směru a často je provázeno poraněním menisku. Prognózu určuje časné vyšetření a přeučení pohybových stereotypů.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Poranění ACL je většinou nekontaktní, vzniká při dopadu nebo změně směru, roli hraje valgozita kolene a rotace bérce. Meniskus se poraní při rotaci v zátěži, často spolu s ACL."},{"h":"Hlavní příznaky","t":"ACL: prasknutí či lupnutí při úrazu, otok způsobený hemartrózou, podvrtnutí či vyskočení kolene (giving way). Meniskus: bolest v kloubní štěrbině, pocit přeskakování, blokáda (locking), omezení pohybu."},{"h":"Vyšetřovací hlediska","t":"ACL: Lachmanův test, přední zásuvkový test, pivot shift test. Meniskus: bolestivost kloubní štěrbiny při tlaku, McMurrayův test. Konečnou diagnózu stanoví lékař."},{"h":"Průběh léčby","t":"V akutní fázi kontrola otoku, zajištění extenčního ROM a kontrakce kvadricepsu. O konzervativní léčbě nebo náhradě vazu rozhoduje lékař. Sílu a ROM budujte už před operací."},{"h":"Opatrnost, kontraindikace","t":"Opakované podvrtnutí kolene může dále poškodit meniskus a chrupavku. U zablokovaného kolene necvičte násilně ROM. Dbejte na vbočení kolene při pohybu."},{"h":"Indikace k odeslání k lékaři","t":"Koleno nelze natáhnout kvůli blokádě, rychlý rozvoj kloubního otoku ihned po úrazu, opakované podvrtnutí kolene, přetrvávající silná bolest, známky zlomeniny."}]},"keypoints":["Poranění ACL je většinou nekontaktní, nebezpečná situace je vbočení kolene dovnitř","Základem vyšetření ACL je Lachmanův test","Poranění menisku: bolestivost kloubní štěrbiny při tlaku a pocit přeskakování","Pokud nelze koleno natáhnout kvůli blokádě, navštivte lékaře","Jako prevenci vyučujte techniku dopadu a změny směru"],"case":{"text":"17letá basketbalistka. Při dopadu po výskoku jí koleno vbočilo dovnitř, uslyšela lupnutí a upadla. Během několika hodin jí oteklo koleno; Lachmanův test ukazuje zvýšený přední posun a chybějící pevný doraz.","answer":"Pozor na podezření na poranění ACL. V akutní fázi je primární kontrola otoku, zajištění extenčního ROM a kontrakce kvadricepsu. Vzhledem k přidruženému poranění menisku se zeptejte na blokády. O konzervativní léčbě nebo náhradě rozhoduje lékař; nevracejte se do sportu na vlastní paměť."},"questions":[{"level":"Základní","q":"Jaká je typická situace nekontaktního poranění ACL?","options":["Varozita kolene (kolena ven)","Valgozita kolene (kolena dovnitř)","Hyperflexe kolene","Přímý úder na čéšku"],"answer":1,"exp":"Nekontaktní poranění ACL typicky vzniká při dopadu nebo změně směru, kdy koleno vbočuje dovnitř (valgus)."},{"level":"Základní","q":"Který příznak je charakteristický pro poranění menisku?","options":["Blokáda (locking)","Pleskavá chůze (foot drop)","Výmadek patelárního reflexu","Snížená citlivost na přední straně stehna"],"answer":0,"exp":"Pokud se poškozená část menisku vklíní do kloubu, koleno se v určitém úhlu zablokuje: jedná se o blokádu."},{"level":"Pokročilý","q":"Který manuální test je nejcitlivější na poranění ACL?","options":["McMurrayův test","Zadní zásuvkový test","Lachmanův test","Valgozní zátěžový test"],"answer":2,"exp":"Lachmanův test při mírně pokrčeném koleni táhne holenní kost vpřed a vyšetřuje posun a doraz. Je základem vyšetření ACL."},{"level":"Pokročilý","q":"Jaký je nález pozitivního McMurrayova testu?","options":["Zvýšený přední posun tibie","Lupnutí a bolest při natahování za současné rotace","Pocit nestability čéšky","Otevření vnitřní kloubní štěrbiny"],"answer":1,"exp":"Z pokrčeného kolene natahujeme bérec s rotací; pokud se v kloubní štěrbině objeví lupnutí nebo bolest, máme podezření na poranění menisku."},{"level":"Klinický","q":"Fotbalista: při změně směru si podvrtnul koleno, od té doby se zasekává a nemůže ho zcela natáhnout. Co je nejpravděpodobnější?","options":["Patelární tendinopatie","Syndrom iliotibiálního traktu","Blokáda způsobená poraněním menisku","Osgoodova–Schlatterova choroba"],"answer":2,"exp":"Po rotačním zranění neschopnost provést natažení poukazuje na blokádu. Nesilte cvičení ROM, odešlete pacient(k)u k lékařskému vyšetření."},{"level":"Klinický","q":"2. den po zranění ACL, koleno je oteklé. Co je primární na začátku konzervativní léčby?","options":["Cvičení skoků","Kontrola otoku a zajištění extenze","Cvičení maximálních změn směru","Hluboký dřep se zátěží"],"answer":1,"exp":"Zpočátku řešte otok, zajistěte extenzní ROM a kontrakci quadricepsu. Velká zátěž může způsobit vykloubení kolene a sekundární poranění."}],"seccion":"Zranění a rehabilitace","grupo":"Sport, šlachy a svaly","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"Po rekonstrukci předního zkříženého vazu","lead":"Rehabilitace po plastice ACL postupně obnovuje ROM, svalovou sílu a pohybové vzorce při současné ochraně štěpu. První cíl: nesmí zůstat omezení extenze.","sheet":{"kind":"condition","items":[{"h":"Onemocnění a operace","t":"Vaz se nahrazuje vlastní šlachou (např. hamstringy nebo štěp kost–patelární šlacha–kost). Štěp se po operaci přestavuje a pevnost získává až časem."},{"h":"Pooperační úkoly","t":"Časně je častý otok, bolest, omezení extenze a slabá aktivace quadricepsu. Dbejte také na bolest a slabost v místě odběru štěpu."},{"h":"Vyšetřovací hlediska","t":"Otok, stranový rozdíl v extenzi a flexi kolene, volní kontrakce quadricepsu (extension lag), stereotyp chůze, svalová síla, funkční testy (např. hop testy)."},{"h":"Rehabilitace po fázích","t":"0.–2. týden: plná extenze, quadriceps. 2.–6. týden: normální chůze, zvětšování flexe. 6.–12. týden: síla, propriocepce. 3.–6. měsíc: postupný běh, skoky. Od 6. měsíce: návratové testy."},{"h":"Opatrnost, kontraindikace","t":"Nesmí zůstat omezení extenze. Začátek cvičení zatěžujících štěp určuje operační technika a pokyn lékaře. Pokud se otok zvětšuje, snižte zátěž; nepostupujte pouze podle času."},{"h":"Indikace k odeslání k lékaři","t":"Horečka, začervenání rány, horkost, hnisavý sekrec, náhle narůstající otok, bolest a otok lýtka (pozor na hlubokou žilní trombózu), pocit nestability/vykloubení kolene."}]},"keypoints":["Hlavním cílem je dosažení plné extenze","Aktivujte quadriceps volně již v časné fázi","Postupujte nejen podle času, ale i podle otoku, ROM a svalové síly","O návratu ke sportu rozhodují funkční testy a lékař","Pro prevenci zranění učte dopad a změnu směru"],"case":{"text":"22letý muž, 2 týdny po plastice ACL. Koleno je mírně oteklé, extenze −10°. Kontrakce quadricepsu je slabá, je patrný extension lag. Říká, že by chtěl co nejdříve běhat.","answer":"V této fázi je primární dosažení plné extenze a kontroly quadricepsu, na běh je ještě brzy. Přebývající omezení extenze vede k patologické chůzi a bolestem předního kolene. Ošetřete otok a pokračujte až po splnění kritérií."},"questions":[{"level":"Základní","q":"Jaký je primární cíl rehabilitace po plastice ACL?","options":["Časné cvičení skoků","Prvořadé je dosažení hluboké flexe","Obnovení plné extenze","Běh ihned po operaci"],"answer":2,"exp":"Zbývající omezení extenze vede k patologické chůzi a bolestem předního kolene, proto je obnovení plné extenze primární."},{"level":"Základní","q":"Ve které fázi provádíme testy pro návrat ke sportu?","options":["2. fáze (2.–6. týden)","3. fáze (6.–12. týden)","4. fáze (3.–6. měsíc)","5. fáze (od 6. měsíce)"],"answer":3,"exp":"Návratové testy provádíme v poslední, 5. fázi (od 6. měsíce) na základě výsledků silových a funkčních testů."},{"level":"Pokročilý","q":"Co znamená extension lag vyšetřovaný v časném pooperačním období?","options":["Anteriorní nestabilita kolene","Aktivní extenze zaostává za pasivní","Omezení pasivní flexe","Laterální pozice čéšky"],"answer":1,"exp":"Pasivně lze koleno plně propnout, aktivně však nikoliv: to značí sníženou aktivaci kvadricepsu."},{"level":"Pokročilý","q":"Na základě čeho je správné postoupit do další fáze rehabilitace?","options":["Na základě kritérií otoku, ROM a síly","Pouze na základě týdnů od operace","Podle plánu, i přes stupňující se bolest","Především podle přání pacienta"],"answer":0,"exp":"Čas je pouze orientační. Postupujeme tehdy, jsou-li splněna kritéria otoku, ROM, svalové síly a kvality pohybu."},{"level":"Klinický","q":"1 týden po náhradě se objeví náhlá bolest lýtka, otok a horkost v místě. Jaký je správný postup?","options":["Masáží rozptýlit otok","Zvýšit zátěž","Okamžitě informovat lékaře","Tepelná terapie"],"answer":2,"exp":"Příznak naznačující hlubokou žilní trombózu. Masáži se vyhněte, okamžitě informujte lékaře."},{"level":"Klinický","q":"4 měsíce po operaci je velký rozdíl v síle mezi stranami a při doskoku koleno padá dovnitř. Jaký je nyní správný postup?","options":["Okamžitý návrat k zápasům","Pokračovat v posilování a zlepšování doskoku","Ukončení rehabilitace","Návrat pouze s ortézou"],"answer":1,"exp":"Rozdíl v síle a padání kolene dovnitř jsou rizikové faktory pro znovuzranění. Pokračujte v posilování a úpravě pohybu; návrat je možný až po splnění kritérií."}],"seccion":"Zranění a rehabilitace","grupo":"Sport, šlachy a svaly","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"Artróza","lead":"Artróza je onemocnění spojené s degenerací kloubní chrupavky, při němž bolest a funkční zhoršení postupně progredují. Postihuje hlavně koleno a kyčel; základem konzervativní léčby je pohybová terapie a edukace pacienta.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Podstatou je degenerace a opotřebení kloubní chrupavky s tvorbou osteofytů, subchondrální sklerózou a synovitidou. Gonartróza je hlavně mediální, koxartróza často vzniká na podkladě dysplazie."},{"h":"Hlavní příznaky","t":"Startovací bolest, bolest při vstávání a chůzi po schodech, ztuhlost, kloubní výpotek, omezení pohybu. V pokročilém stadiu je patrná deformita (např. varozita) a porucha chůze."},{"h":"Vyšetřovací hlediska","t":"Místo a vyvolávající příčina bolesti, ROM (např. omezení extenze kolene, vnitřní rotace kyčle), svalová síla, chůze (laterální thrust, Trendelenburgův příznak), ADL."},{"h":"Průběh léčby","t":"Edukace pacienta, pohybová terapie (posílení kvadricepsu a abduktorů kyčle, udržení ROM), aerobní pohyb, kontrola hmotnosti, hůl, vložky do bot. Pokud konzervativní léčba nestačí, přichází v úvahu operace."},{"h":"Opatrnost, kontraindikace","t":"Při silném zánětu nebo výpotku snižte zátěž. Zátěž způsobující bolest přetrvávající do druhého dne je příliš vysoká. Hůl držte v ruce opačné k postižené straně."},{"h":"Indikace k odeslání k lékaři","t":"Náhlý silný otok a horkost (podezření na infekci nebo pseudodnu), horečka, stupňující se noční bolest, náhlá neschopnost chůze, silná bolest po pádu."}]},"keypoints":["Gonartróza je většinou mediální, často s varozitou","V pozadí koxartrózy často stojí acetabulární dysplazie","Základem konzervativní léčby je pohybová terapie a edukace pacienta","Hůl držte v ruce na opačné straně, než je postižení","Zkontrolujte zátěž, po které přetrvává bolest až do druhého dne"],"case":{"text":"70letá žena. Již léta ji bolí pravé koleno, zejména při vstávání, na začátku pohybu a při chůzi po schodech. Je patrná deformita do O, omezení extenze aboční výkyv kolena při chůzi (lateral thrust).","answer":"Myslíme na mediodestruktivní gonartrózu. Edukace pacienta, posílení kvadricepsu a svalů kolem kyčle, udržení ROM, kontroly tělesné hmotnosti; v případě potřeby hole v levé ruce. Při náhlém zahřátí nebo otoku navštivte lékaře."},"questions":[{"level":"Základní","q":"Který je nejčastější typ artrózy kolena?","options":["Laterální (valkózní – X nohy)","Mediodesetní (varózní – O nohy)","Pouze patelofemorální","Tibiofibulární"],"answer":1,"exp":"Artróza kolena nejčastěji postihuje mediální kloubní plošinu a často je provázena deformitou do O (varózní postavení)."},{"level":"Základní","q":"Jaký je typický nález na zobrazení u artrózy?","options":["Zšíření kloubní štěrbiny","Zšíření růstové chrupavky","Periostální reakce","Tvorba osteofytů"],"answer":3,"exp":"Typickými známkami artrózy jsou zúžení kloubní štěrbiny, osteofyty a subchondrální skleróza."},{"level":"Pokročilý","q":"Učíte pacienta s gonartrózou vpravo používat hůl. Ve které ruce má hůl držet?","options":["V pravé ruce","V levé ruce","V obou rukou","Je to jedno"],"answer":1,"exp":"Hůl standardně držte v ruce na opačné straně, než je postižená končetina, a posouvejte ji vpřed současně s postiženou nohou; tím se sníží zátěž na postižené straně."},{"level":"Pokročilý","q":"Který příznak je typický při koxartróze a slabosti m. gluteus medius?","options":["Příznak padající paže","Lasègueův příznak","Trendelenburgův příznak","Homansovo znamení"],"answer":2,"exp":"Při slabosti m. gluteus medius dochází při stoju na jedné noze na postižené straně k poklesu pánve na opačné straně: jedná se o Trendelenburgovo znamení."},{"level":"Klinický","q":"65letý muž, gonartróza. Po pohybové terapii přetrvávala silná bolest a otok až do druhého dne. Jaký je správný postup?","options":["Dále zvýšit zátěž","Zastavit veškerý pohyb","Snížit a znovu upravit dávkování zátěže","Doporučit pouze klid"],"answer":2,"exp":"Bolest a otok přetrvávající do druhého dne ukazují na přetížení. Nepřestávejte cvičit, ale pokračujte s upraveným množstvím a intenzitou."},{"level":"Klinický","q":"Koleno pacienta s gonartrózou náhle silně oteklo, je teplé a má i horečku. Jaký je primární postup?","options":["Kontaktovat lékaře","Intenzifikovat pohybovou terapii","Tepelná terapie","Nácvik protažení"],"answer":0,"exp":"Náhlý otok, teplo a horečka mohou ukazovat na infekci nebo dnu. Vyhněte se tepelné terapii a pohybu, kontaktujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Ortopedie a traumatologie","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"Endoprotéza kyčle a kolene","lead":"Kloubní náhrada nahrazuje poškozené kloubní plochy umělým materiálem za účelem snížení bolesti a zlepšení funkce. Klíčem k uzdravení je nácvik pohybu přizpůsobený operačnímu přístupu a časná mobilizovaná.","sheet":{"kind":"condition","items":[{"h":"Onemocnění a operace","t":"Náhrada kloubních ploch poškozených artrozou nebo jinou příčinou protézou za účelem snížení bolesti a zlepšení funkce. U náhrady kyčle (THA) závisí poloha riziková z hlediska luxace na způsobu operačního přístupu."},{"h":"Pooperační úkoly","t":"Bolest, otok, omezení rozsahu pohybu, svalová slabost, zhoršující se chůze. Hlavním úkolem po THA je prevence luxace, po náhradě kolene (TKA) dosažení flexe a extenze v ROM."},{"h":"Vyšetřovací hlediska","t":"Rána a otok, ROM, svalová síla (quadriceps, m. gluteus medius), vnímání rozdílu délky končetin, stereotyp chůze, rovnováha, ADL. Omezení zátěže a zakázané polohy konzultujte s lékařem."},{"h":"Průběh léčby","t":"Časná cvičení hlezna, izometrická cvičení, mobilizace a nácvik chůze. Cvičení ROM a posilovací cvičení, postupná změna kompenzační pomůcky při chůzi, nácvik ADL a soběstačnosti."},{"h":"Opatrnost, kontraindikace","t":"Po THA z 3zadního přístupu je nutno se vyvarovat kombinace flexe–addukce–vnitřní rotace, po předním přístupu kombinace extenze–addukce–zevní rotace. Po TKA dbejte na známky poškození n. peroneus."},{"h":"Indikace k odeslání k lékaři","t":"Náhlá bolest poukazující na luxaci, zkrácení a rotace končetiny, otok a bolest lýtka, náhle vzniklá dušnost nebo bolest na hrudi, zarudnutí rány, hnisání, horečka."}]},"keypoints":["Riziková poloha pro luxaci při THA závisí na způsobu operačního přístupu","U zadního přístupu se vyvarujte kombinace flexe–addukce–vnitřní rotace","Dorzální a plantární flexe hlezna pomáhají předcházet trombóze","Po TKA je důležité včasné dosažení flexe a extenze v ROM","Zátěž a zakázané polohy vždy konzultujte s lékařem"],"case":{"text":"75letá žena, 3. pooperační den po TEP kyčle z posterolaterálního přístupu pro coxartrózu. Trénuje s chodítkem a chce zvednout něco ze země: hluboce se předkloní s rotací trupu.","answer":"Kombinace hluboké flexe–addukce–vnitřní rotace je po THA ze zadního přístupu riziková z hlediska luxace, pohyb okamžitě zastavte. Učte bezpečné pohyby s pomocí pomůcky (např. kleští na sbírání předmětů). V případě náhlé bolesti, zkrácení nebo rotace končetiny ihned vyhledejte lékaře."},"questions":[{"level":"Základní","q":"Která poloha je riziková z hlediska luxace po THA ze zadního přístupu?","options":["Extenze, addukce, zevní rotace","Flexe, addukce, vnitřní rotace","Flexe, abdukce, zevní rotace","Extenze, abdukce, vnitřní rotace"],"answer":1,"exp":"Po THA ze zadního přístupu je větší riziko luxace v kombinaci flexe–addukce–vnitřní rotace kyčle."},{"level":"Základní","q":"Jaký je hlavní cíl náhrady kolenního kloubu (TKA)?","options":["Stimulace růstu kosti","Náhrada vazu","Obnovení funkce nervu","Snížení bolesti a zlepšení funkce"],"answer":3,"exp":"TKA nahrazuje poškozené kloubní plochy protézou; jejím cílem je snížení bolesti a zlepšení chůze a dalších funkcí."},{"level":"Pokročilý","q":"Které cvičení učíte včas k prevenci hluboké žilní trombózy?","options":["Rotace krku","Ohyb a natažení prstů","Dorzální a plantární flexe hlezna","Hluboký dřep"],"answer":2,"exp":"Dorzální a plantární flexe hlezna podporuje žilní návrat prostřednictvím svalové pumpy lýtka a pomáhá předcházet trombóze."},{"level":"Pokročilý","q":"Na obrnu kterého nervu je nutné dávat pozor po TKA?","options":["Obrna n. peroneus","Obrna n. medianus","Pohroza n. facialis","Pohroza n. radialis"],"answer":0,"exp":"Po TKA může v důsledku tlaku v okolí hlavičky fibuly dojít k obrně n. peroneus; všimněte si pokleslé nohy a mravenčení."},{"level":"Klinický","q":"5. den po THA z přístupu zezadu: pacient sedí na nízké židli a chce si prekřížit nohy. Jaký je správný postup?","options":["Pouze sledovat","Vyšší židle, vyhnutí se překřížení nohou","Cvičení překřížení nohou","Cvičení hlubokého ohnutí"],"answer":1,"exp":"Na nízké židli hrozí při hluboké flexi a překřížení nohou (addukce, vnitřní rotace) vykloubení. Používejte vysokou sedací plochu a nepřekřižujte nohy."},{"level":"Klinický","q":"2. den po TKA: během nácviku chůze se náhle objeví dušnost a bolest na hrudi. Jaký je primární postup?","options":["Pokračovat v nácviku chůze","Učit dechová cvičení","Okamžité zastavení, nahlásit lékaři","Uložit do klidu a sledovat"],"answer":2,"exp":"Příznak nasvědčující plicní embolii. Pohyb je nutno okamžitě zastavit a nahlásit lékaři."}],"seccion":"Zranění a rehabilitace","grupo":"Ortopedie a traumatologie","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"Časté zlomeniny","lead":"U seniorů jsou na podkladě osteoporózy časté zlomeniny způsobené pádem. Respektujte fázi hojení kosti a rámec povolený lékařem, abyste předešli inaktivitě a obnovili funkci.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"U starších osob na podkladě osteoporózy je po pádu častá zlomenina proximálního femuru, distálního rádiu, proximálního humeru a obratlového těla. U mladých lidí je typické vysokoenergetické trauma."},{"h":"Hlavní příznaky","t":"Bolest, otok, deformita, krevní výron, výpadek funkce. U zlomeniny proximálního femuru pacient nedokáže vstát, končetina je zkrácená a zevně rotovaná; u kompresivní zlomeniny bolest zad při pohybu."},{"h":"Vyšetřovací hlediska","t":"Odsouhlaste s lékařem typ zlomeniny, fixaci, rámec zátěže a ROM. Bolest, otok, ROM sousedních kloubů, síla, nervový a cévní stav, předúrazové ADL a kognice."},{"h":"Průběh léčby","t":"Během fixace pohybujte volnými klouby proti otoku a kontraktuře. Dle hojení kosti a povolení provádějte cvičení ROM, zátěže a posilovací. U starších osob časná mobilizace, prevence pádů."},{"h":"Opatrnost, kontraindikace","t":"Nepřekračujte povolenou zátěž a ROM. Při dlouhodobém klidu na lůžku dbejte na inaktivitu, zápal plic, proleženiny a delirium. Po zlomenině distálního rádia sledujte tuhost prstů."},{"h":"Indikace k odeslání k lékaři","t":"Silná bolest pod fixací, mravenčení, zbarvení prstů (podezření na oběhové potíže nebo compartment syndrom), náhle se zhoršující bolest nebo deformitase, otok lýtka, horečka."}]},"keypoints":["U starších lidí je po pádu častá zlomenina na podkladě osteoporózy","Povolka zátěže a ROM vždy konzultujte s lékařem","I během fixace aktivně pohybujte nefixovanými klouby","Po zlomenině proximálního femuru předcházejte inaktivitě časnou mobilizací","Proti další zlomenině: prevence pádů a léčba osteoporózy"],"case":{"text":"82letá žena upadla doma, bolí ji pravá kyčel, nemůže se postavit. Pravá dolní končetina je zkrácená a zevně rotovaná. Pro pertrochanterickou zlomeninu femur byla provedena osteosyntéza, první pooperační den byla nařízena rehabilitace.","answer":"Zkontrolujte s lékařem povolenou zátěž, začněte časnou mobilizaci a nácvik chůze, předcházejte inaktivitě, zápalu plic a deliriu. Cílem je ADL před úrazem; před propuštěním poučte o prevenci pádů a léčbě osteoporózy."},"questions":[{"level":"Základní","q":"Která zlomenina je častá, když starší člověk upadne na nataženou ruku?","options":["Zlomenina os scaphoideum","Zlomenina distálního radiusu","Zlomenina olecranonu","Zlomenina metakarpů"],"answer":1,"exp":"U starších lidí je po pádu na nataženou ruku typická zlomenina distálního radiusu. Pokud se distální fragment posune dorzálně, hovoříme o Collesově zlomenině."},{"level":"Základní","q":"V jaké pozici se nachází dolní končetina při proximální zlomenině femuru?","options":["Delší a vnitřně rotovaná","Bez odchylky","Zkrácená a zevně rotovaná","Delší a v abdukci"],"answer":2,"exp":"U proximální zlomeniny femuru je končetina typicky zkrácená a zevně rotovaná, stoj a chůze jsou obtížné."},{"level":"Pokročilý","q":"Jaká je správná fyzioterapie ve fázi fixace zlomeniny?","options":["Silné pasivní ROM na fixované části","Před povolením plné zátěže","Hloubková masáž v místě zlomeniny","Pohyb nefixovaných kloubů"],"answer":3,"exp":"Během fixace chráníme zlomeninu a pohybem nefixovaných kloubů předcházíme otoku, kontraktuře a svalové slabosti."},{"level":"Pokročilý","q":"Jaký je hlavní cíl časné mobilizace u starších lidí po operaci proximální zlomeniny femuru?","options":["Určení typu zlomeniny","Prevence syndromu inaktivity","Nahrazení operace","Odstranění potřeby hojení kosti"],"answer":1,"exp":"U starších lidí se při dlouhodobém ležení rychle rozvíjí svalová slabost, zápal plic, dekubity a delirium, proto mobilizujeme časně."},{"level":"Klinický","q":"70letá žena, v sádře pro distální zlomeninu radia. Prsty má silně oteklé, mravenčí a jsou zbarvené. Jaký je správný postup?","options":["Zintenzivnění cvičení prstů","Tepelná terapie","Okamžitě informovat lékaře","Počkat na další ošetření"],"answer":2,"exp":"Silný otok, mravenčení a změna barvy pod fixací ukazují na oběhové potíže nebo compartment syndrom. Okamžitě to nahlaste lékaři."},{"level":"Klinický","q":"85letá žena, kompresivní zlomenina bederního obratle, bolest zad; lékař povolil mobilizaci. Jaký je správný postup?","options":["Mobilizace v povoleném rozsahu","Zůstat na lůžku, sledování","Silné flexní cviky trupu","Nácvik zvedání těžkých předmětů"],"answer":0,"exp":"Mobilizujeme v povolených mezích proti inaktivitě. U kompresivní zlomeniny jsou silná flexe trupu a zvedání těžkých předmětů zatěžující, je třeba se jim vyhnout."}],"seccion":"Zranění a rehabilitace","grupo":"Ortopedie a traumatologie","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"Bolesti zad a výhřez ploténky","lead":"Většina bolestí zad je nespecifická, příčina není identifikovatelná, ale je důležité odlišit kořenové příznaky a závažná onemocnění. Po vyloučení červených vlajek podporujeme udržení aktivity.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Většina bolestí zad je nespecifická. U výhřezu ploténky nucleus pulposus provaluje anulus fibrosus, vyhřezává a tlačí na nervový kořen. Nejčastější je v segmentech L4/5 a L5/S1."},{"h":"Hlavní příznaky","t":"Bolest v bederní oblasti a jednostranná bolest vyzařující do nohy (ischias), mravenčení, obtíže zhoršující se v předklonu a při sezení. Snížení citlivosti, síly a reflexů odpovídající postiženému kořenu."},{"h":"Vyšetřovací hlediska","t":"Test SLR (u horních bederních kořenů natahovací test n. femoralis), dermatomy, svalová síla (L5: dorzální flexe palce, S1: plantární flexe hlezna), reflexy (S1: achillový reflex)."},{"h":"Průběh léčby","t":"Edukací pacienta snižte strach, zachovejte aktivitu v rámci možností. Najděte polohu a cvičení zmírňující příznaky; cviky na trup a dolní končetiny, postupně zvyšovaná aktivita."},{"h":"Opatrnost, kontraindikace","t":"Nedoporučujte dlouhodobý klid na lůžku. Zastavte cvičení, při kterém se příznaky šíří směrem k prstům. Vyhýbání se aktivitě ze strachu a další psychosociální faktory hrají roli v chronifikaci."},{"h":"Indikace k odeslání k lékaři","t":"Poruchy močení a stolice, výpadek citlivosti v sedlové oblasti (syndrom caudy equiny), progredující slabost, horečka, nevysvětlitelný úbytek hmotnosti, nádorové onemocnění v anamnéze, silná bolest po úrazu."}]},"keypoints":["Většina bolestí zad je nespecifická","U výhřezu L4/5 je obvykle postižen kořen L5","SLR test vyšetřuje příznaky dolních bederních kořenů","Místo dlouhodobého odpočinku zachovejte aktivitu v rámci možností","Poruchy močení a defekace, výpadek citlivosti v sedlové oblasti: neprodleně k lékaři"],"case":{"text":"35letý muž, kancelářská práce. Od zvednutí těžkého předmětu bolest v bederní oblasti a mravenčení šířící se od vnější strany levého bérce k nártu. Levý SLR vyvolává bolest vyzařující do končetiny, dorzální flexe levého palce je slabá. Poruchy močení nejsou přítomny.","answer":"Podezíráme lézi kořene L5 způsobenou výhřezem ploténky L4/5. Edukace, zachování aktivity v rámci možností, cvičení nezhoršující příznaky; pravidelně vyšetřujte vývoj svalové slabosti. Při progresivní obrně nebo poruchách močení a defekace okamžitě k lékaři."},"questions":[{"level":"Základní","q":"Ve kterém segmentu je výhřez bederní ploténky nejčastější?","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"Výhřez bederní ploténky se nejčastěji vyskytuje v segmentu L4/5, následně v L5/S1."},{"level":"Základní","q":"Která tkáň vyhřezává u výhřezu ploténky především?","options":["Nucleus pulposus","Lig. flavum","Oblouk obratle","Processus spinosus"],"answer":0,"exp":"Centrální část ploténky, nucleus pulposus, vyhřezává prasklinou anulus fibrosus a tlačí na nervový kořen."},{"level":"Pokročilý","q":"Síla kterého pohybu se při lézi kořene L5 obvykle snižuje?","options":["Plantární flexe hlezna","Dorzální flexe palce","Extenze kolene","Flexe kyčle"],"answer":1,"exp":"Kořen L5 inervuje m. extensor hallucis longus, při jeho lézi dochází k oslabení dorzální flexe palce. Plantární flexe hlezna je S1."},{"level":"Pokročilý","q":"Který reflex se při lézi kořene S1 obvykle snižuje?","options":["Patelární reflex","Bicepsreflex","Reflex Achillovy šlachy","Brachioradialis reflex"],"answer":2,"exp":"Na reflexu Achillovy šlachy se podílí hlavně S1. Patelární reflex slouží primárně k vyšetření L4."},{"level":"Klinický","q":"40letá žena, akutní bolest bederní páteře, bez červených vlajek. Jaká je správná rada?","options":["2 týdny přísného klidu na lůžku","Pracovní neschopnost do odeznění bolesti","Zákaz jakéhokoli pohybu","Zachování aktivity v rámci možností"],"answer":3,"exp":"U akutní bolesti bederní páteře bez červených vlajek se místo dlouhodobého klidu doporučuje zachovat každodenní aktivitu v rámci možností."},{"level":"Klinický","q":"Pacient s bolestí beder, obě nohy mravenčí; stěžuje si na obtížné močení a tupou citlivost v okolí konečníku. Co je nutné udělat?","options":["Pokračovat v pohybové terapii","Trakční terapie","Okamžitě informovat lékaře","Počkat na další ošetření"],"answer":2,"exp":"Poruchy močení a vyprazdňování stolice a výpadek citlivosti v sedlové oblasti jsou naléhavým příznakem svědčícím pro syndrom cauda equina. Okamžitě informujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Páteř","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"Bolest krční páteře","lead":"Většina bolestí krční páteře je nespecifická, je však důležité odlišit radikulopatii a myelopatii. Po kontrole varovných příznaků aplikujeme pohybovou terapii a korigujeme držení těla.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Nejčastější je nespecifická bolest krku. Pokud ploténka nebo osteofyt tlačí na nervový kořen, vzniká radikulopatie, pokud na míchu, vzniká myelopatie. Po úrazu se objevuje také whiplash injury (poranění typu whiplash)."},{"h":"Hlavní příznaky","t":"Bolest krku, omezení pohybu, bolest v oblasti lopatky. U radikulopatie jednostranná bolest paže, mravenčení. U myelopatie mravenčení obou rukou, zhoršená jemná motorika (zapínání knoflíků, příbor), porucha chůze."},{"h":"Vyšetřovací hlediska","t":"Krční ROM, Spurlingův test, dermatomy, svalová síla, reflexy (C6: brachioradialis, C7: triceps), Hoffmannův reflex, chůze, držení těla."},{"h":"Průběh léčby","t":"Edukace a zachování aktivity, cviky na krk a ramenní pletenec (např. cviky hlubokých flexorů krku), úprava držení těla a pracovního prostředí. Manuální terapie na základě vyšetření, opatrně."},{"h":"Opatrnost, kontraindikace","t":"Při podezření na myelopatii se vyhněte silným manuálním technikám na krční páteři. Okamžitě zastavte techniku nebo cvičení, které vyvolává závratě, dvojité vidění nebo poruchu řeči."},{"h":"Indikace k odeslání k lékaři","t":"Mravenčení obou rukou, zhoršující se jemná motorika a porucha chůze, progresivní obrna, bolest po úrazu, horečka, závratě, porucha řeči nebo polykání, nevysvětlitelný úbytek hmotnosti."}]},"keypoints":["Většina bolestí krční páteře je nespecifická","Spurlingův test slouží k vyšetření radikulopatie","Zhoršující se obratnost obou rukou a porucha chůze: podezření na myelopatii","Provádějte cvičení hlubokých flexorů krku a ramenního pletence","Při podezření na myelopatii se vyhněte silným manuálním technikám na krční páteři"],"case":{"text":"45letá žena, kancelářská pracovnice. Jeden měsíc bolest krku a mravenčení pravého palce. Při extenzi a úklonu krku doprava se objevuje bolest vyzařující do pravé paže. Pravý brachioradialis reflex je snížený.","answer":"Myslíme na pravostrannou radikulopatii C6. V rámci nezhoršování příznaků proveďte edukaci, pohybovou terapii, úpravu držení těla a pracovního prostředí. V případě progresivní slabosti nebo známek myelopatie (mravenčení obou rukou, porucha chůze) odešlete pacientku k lékaři."},"questions":[{"level":"Základní","q":"Který příznak poukazuje na cervikální spondylotickou myelopatii?","options":["Pouze jednostranná bolest v oblasti lopatky","Zhoršující se obratnost obou rukou","Tuhost krčních svalů","Pouze bolest hlavy"],"answer":1,"exp":"Při kompresi mícha dochází k brnění obou rukou, zhoršení jemné motoriky (příbor, knoflíky) a objevují se poruchy chůze."},{"level":"Základní","q":"Které cvičení je typické pro hluboké flexory krku?","options":["Silná extenze krku","Rychlá rotace krku","Zasunovací pohyb brady (kraniokervikální flexe)","Krčení ramen"],"answer":2,"exp":"Kraniokervikální flexe prováděná s mírným zasunutím brady je typické cvičení zvyšující aktivitu hlubokých flexorů krku (např. m. longus colli)."},{"level":"Pokročilý","q":"Jaký je nález pozitivního Spurlingova testu?","options":["Extenze + lateroflexe: bolest vyzařující do paže","Flexe krku: bolest vystřelující do zad","Příznaky ustupující při abdukci ramene","Brnění objevující se při flexi zápěstí"],"answer":0,"exp":"Krční páteř extendujeme a ukloníme na postiženou stranu a aplikujeme axiální tlak; bolest vyzařující do paže nebo brnění poukazují na radikulopatii."},{"level":"Pokročilý","q":"Který reflex je typicky snížený při lézi kořene C7?","options":["Bicepsreflex","Brachioradialis reflex","Tricepsový reflex","Patelární reflex"],"answer":2,"exp":"Tricepsový reflex slouží hlavně k vyšetření C7, bicepsový reflex C5 a brachioradialisový reflex C6."},{"level":"Klinický","q":"60letý muž: v poslední době má potíže se zapínáním knoflíků, chůze je nestabilní, Hoffmannův reflex je pozitivní. Na co máte největší podezření?","options":["Nespecifická bolest krční páteře","Syndrom horního hruního otvoru (TOS)","Syndrom karpálního tunelu","Cervikální spondylotická myelopatie"],"answer":3,"exp":"Zhoršující se jemná motorika, porucha chůze a patologický reflex poukazují na myelopatii. Vyhněte se silovým technikám na krku, odeslete pacienta k lékařskému vyšetření."},{"level":"Klinický","q":"U pacienta s bolestmi krku se během rotačního cvičení krční páteře objevuje závrať a dvojité vidění. Jaký je správný postup?","options":["Pokračovat, aby si zvykl","Okamžitě zastavit, odeslat k lékaři","Další zvětšení rozsahu pohybu (ROM)","Přejít na tepelnou terapii"],"answer":1,"exp":"Závrať a dvojité vidění mohou poukazovat na cévní nebo neurologický problém. Okamžitě cvičení zastavte a odeslete pacienta k lékařskému vyšetření."}],"seccion":"Zranění a rehabilitace","grupo":"Páteř","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"Skolióza","lead":"Skolióza je boční vybočení páteře s rotací obratlů: trojrozměrná deformita. Během růstu má tendenci k progresivním změnám, proto je důležitá včasná diagnóza a pravidelná kontrola.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Páteř se ve frontální rovině vychyluje do strany: jde o trojrozměrnou deformitu spojenou s rotací obratlů. Většinou neznámého původu (idiopatická), častější u dospívajících dívek. Je nutné ji odlišit od funkční skoliózy."},{"h":"Hlavní příznaky","t":"Většinou je málo bolestivá; pozornost upoutá asymetrie ramen, lopatek, pasu nebo při předklonu patrný žeberní či bederní hrb. V závažných případech zhoršuje i plicní funkce."},{"h":"Vyšetřovací hlediska","t":"Ve stoji sledujte symetrii ramen, pánve a pasu, proveďte test předklonu, změřte rozdíl v délce končetin (odlišení od funkční skoliózy), flexibilitu a dýchání. Zakřivení měří lékař na rentgenu pomocí Cobbova úhlu."},{"h":"Průběh léčby","t":"O kontrole, ortéze či operaci rozhoduje lékař na základě růstové fáze a Cobbova úhlu. Fyzioterapeut vede cvičení trupu a dechová cvičení a podporuje nošení ortézy."},{"h":"Opatrnost, kontraindikace","t":"Během růstu má tendenci k progresi, proto je důležitá pravidelná kontrola. Netvrďte, že je korigovatelná pouze cvičením. Dobu nošení ortézy určuje lékař."},{"h":"Indikace k odeslání k lékaři","t":"Silná nebo noční bolest, neurologické příznaky (brnění, slabost), rychlá progrese, atypické zakřivení (např. levostranná hrudní křivka), horečka."}]},"keypoints":["Skolióza je trojrozměrná deformita spojená s rotací obratlů","Nejtypičtější je idiopatická skolióza častá u dospívajících dívek","Testem předklonu zkontrolujte žeberní hrb","Během růstu má tendenci k progresi, důležitá je pravidelná kontrola","Při skolióze s bolestí nebo neurologickými příznaky vyhledejte lékaře"],"case":{"text":"13letá dívka, při školním screeningovém vyšetření byla diagnostikována skolióza. Ve stoje je pravé rameno výše, při předklonu je patrný pravostranný gibus. Bolest a neurologické příznaky chybí. Ortoped předepsal korzet.","answer":"Podezříváme idiopatickou skoliózu dospívajících. Fyzioterapeut podporuje důsledné nošení ortézy a vede cvičení trupu a dechová cvičení. Netvrďte, že se pouze cvičením vyléčí. Při bolesti, neurologických příznacích nebo rychlé progresi odešlete k lékaři."},"questions":[{"level":"Základní","q":"Co sledujete při screeningu skoliózy v testu předklonu?","options":["Hyperextenzi kolene","Žeberní hrb","Pokles nožní klenby","Zvýšenou krční lordózu"],"answer":1,"exp":"Při předklonu sledujeme záda zezadu a hledáme žeberní nebo bederní hrb způsobený rotací obratlů."},{"level":"Základní","q":"Který ukazatel určuje míru zakřivení skoliózy?","options":["Q-úhel","Collodiaphysární úhel","Cobbův úhel","Femorotibiální úhel"],"answer":2,"exp":"Míru zakřivení měříme na rentgenu pomocí Cobbova úhlu na základě horního a dolního koncového obratle křivky."},{"level":"Pokročilý","q":"Co platí pro idiopatickou skoliózu?","options":["Častá u starších mužů","Častá u dospívajících dívek","Vždy provázena silnou bolestí","Pouze deformita ve frontální rovině"],"answer":1,"exp":"Idiopatická skolióza je častější u dospívajících dívek, většinou je málo bolestivá a jde o trojrozměrnou deformitu spojenou s rotací obratlů."},{"level":"Pokročilý","q":"Co může způsobit funkční skoliózu?","options":["Vrozená vada obratlů","Neuromuskulární onemocnění","Deformita s rotací obratlů","Rozdíl v délce končetin"],"answer":3,"exp":"Funkční skolióza způsobená rozdílem v délce končetin nebo úlevovým držením při bolesti se po odstranění příčiny zlepší; je nutné ji odlišit od strukturální."},{"level":"Klinický","q":"14letá dívka s ortézou; protože ji tlačí, z vlastního rozhodnutí ji nosí méně. Co má fyzioterapeut udělat?","options":["Vysazení ortézy, pouze cvičení","Podpořte nošení, konzultujte s lékařem","Další zkrácení doby nošení","Ujistěte pacienta, že je vše v pořádku"],"answer":1,"exp":"Ohledně doby nošení jsou rozhodující pokyny lékaře. Vyslechněte pacientovy potíže, podpořte ho v nošení ortézy a správné usazení konzultujte s lékařem nebo ortopedickým technikem."},{"level":"Klinický","q":"12letý chlapec se skoliózou se v noci budí silnou bolestí zad. Jaký je správný postup?","options":["Nácvik protažení","Sledování","Zvýšení zátěže","Odeslání k lékařskému vyšetření"],"answer":3,"exp":"Za silnou nebo noční bolestí u skoliózy může stát jiná příčina, např. nádor, proto je nutné odeslat pacienta k lékařskému vyšetření."}],"seccion":"Zranění a rehabilitace","grupo":"Páteř","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"Cévní mozková příhoda","lead":"Náhle vzniklé neurologické příznaky v důsledku uzávěru nebo ruptury mozkových cév. Časná mobilizace a úkolově orientovaný, opakovaný trénink jsou základem funkčního zlepšení.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Ischemická CMP (aterotrombotická, kardioembolická, lakunární), mozkové krvácení a subarachnoidální krvácení. Příznaky závisí na lokalizaci a rozsahu léze."},{"h":"Hlavní příznaky","t":"Hemiparéza, poruchy čití, spasticita, afázie, jednostranný neglect, dysartrie, dysfagie, dále poruchy pozornosti a další poruchy vyšších korových funkcí."},{"h":"Vyšetřovací hlediska","t":"Paréza: Brunnstromova stadia, SIAS, FMA; spasticita: MAS; rovnováha: BBS; ADL: FIM."},{"h":"Rehabilitace po fázích","t":"Akutní fáze: časná mobilizace při řízení rizik. Subakutní fáze: úkolově orientovaný trénink a nácvik chůze. Chronická fáze: udržení aktivity a participace."},{"h":"Opatrnost, kontraindikace","t":"V akutní fázi sledujte kolísání krevního tlaku, stav vědomí a neurologické příznaky. Tahání za paretickou paži nebo nesprávná asistence způsobují bolest ramene."},{"h":"Indikace k odeslání k lékaři","t":"Okamžitě hlaste, pokud dojde ke snížení úrovně vědomí, náhlému zhoršení parézy či dysartrie, nebo se objeví silná bolest hlavy, zvracení či náhlá změna krevního tlaku."}]},"keypoints":["Zahájení a ukončení mobilizace dle pokynů lékaře a kritérií pro ukončení","Paretické rameno netahejte, chraňte jej polohováním","U neglectu: úkoly zaměřené na zanedbávanou stranu a úprava prostředí","Základem funkčního zlepšení je úkolově orientovaný, opakovaný trénink","Ortézu zvažujte postupně, v závislosti na schopnosti chůze a cílech terapie"],"case":{"text":"68letý muž, 3 týdny po ischemické CMP v povodí a. cerebri media vpravo. Levostranná hemiparéza (DK: Brunnstrom III. stadium). Na invalidním vozíku často naráží do předmětů vlevo a jídlo na levé straně talíře nechává.","answer":"Podezření na levostranný neglect, vysoké riziko pádů a nárazů. Cvičení zaměřená na pozornost k levé straně, úprava prostředí a cvičení pod dohledem. Dokud neglect přetrvává, nepovolujte samostatný pohyb."},"questions":[{"level":"Základní","q":"Jaké rozložení hemiparézy je typické pro ischemickou CMP v povodí a. cerebri media?","options":["S převahou na dolní končetině","S převahou na horní končetině a obličeji","Paraparéza obou dolních končetin","Symetrická tetraparéza"],"answer":1,"exp":"A. cerebri media zásobuje laterální plochu hemisféry, včetně motorické kůry pro horní končetinu a obličej, proto jsou tyto oblasti postiženy více. Převaha na dolní končetině: a. cerebri anterior."},{"level":"Základní","q":"Která léze nejčastěji způsobuje levostranný neglect?","options":["Levý frontální lalok","Mozek","Pravý parietální lalok","Mozkový kmen"],"answer":2,"exp":"Levostranný neglect typicky vzniká při poškození pravé hemisféry, zejména pravého parietálního laloku."},{"level":"Pokročilý","q":"Ve kterém Brunnstromově stadiu se synergie objevují dobrovolně a plně?","options":["II. stadium","IV. stadium","VI. stadium","III. stadium"],"answer":3,"exp":"III.: synergie se objevují dobrovolně a v plném rozsahu. II.: asociované reakce, počínající synergie. IV.: částečně možný izolovaný pohyb."},{"level":"Pokročilý","q":"Kterou škálou měříte spasticitu po cévní mozkové příhodě?","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"MAS hodnotí svalový tonus na základě odporu proti pasivnímu pohybu. FIM měří ADL, BBS rovnováhu, MMSE kognitivní funkci."},{"level":"Klinický","q":"Po cévní mozkové příhodě je na paretickém rameni subluxace a pacient hlásí bolest ramene během přesunu. Co uděláte?","options":["Pomáháte tahem za paretickou paži","Podepřete rameno, netaháte za paži","Zcela zafixujete, dokud bolest neodezine","Provádíte denně silný pasivní protažení"],"answer":1,"exp":"Tah za subluxované rameno způsobuje bolest a zranění. Chraňte jej ortézou a polohováním, rozsah pohybu udržujte v bezbolestných mezích."},{"level":"Klinický","q":"Akutní ischemická cévní mozková příhoda: během mobilizace se náhle zhorší dysartrie a paréza. Co uděláte?","options":["Pokračujete v nácviku chůze","Po odpočinku pokračujete ve cvičení","Zastavíte a okamžitě informujete lékaře","Druhý den přehodnotíte"],"answer":2,"exp":"Náhlé zhoršení neurologických příznaků může naznačovat šíření léze nebo recidivu. Zastavte cvičení, zajistěte pacienta a okamžitě informujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Neurologie","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"Parkinsonova nemoc","lead":"Progresivní neurodegenerativní onemocnění spojené s degenerací dopaminergních neuronů substantia nigra v mezencefalu, způsobující motorické příznaky. Klíčový je pohyb založený na vnějších podnětech (cueing) a prevence pádů.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Dopaminergní neurony substantia nigra degenerují, v striatu vzniká nedostatek dopaminu a je narušena regulace pohybu. Příznaky pomalu progredují."},{"h":"Hlavní příznaky","t":"Klidový tremor, rigor, akineze/bradykineze, posturální instabilita. Dále freezing, chůze v drobných krocích, předkloněné držení těla a nemotorické příznaky (např. obstipace)."},{"h":"Vyšetřovací hlediska","t":"Stádium dle Hoehn–Yahrové, MDS-UPDRS, BBS, TUG, rychlost chůze, přítomnost freezingu, anamnéza pádu a denní kolísání účinku léků."},{"h":"Průběh léčby","t":"V počáteční fázi zachování obecného pohybu a kondice; s progresí cvičení chůze podpořené vizuálními/akustickými podněty, cvičení rovnováhy, prevence pádů a úprava prostředí."},{"h":"Opatrnost, kontraindikace","t":"Čas cvičení přizpůsobte kolísání účinku léků (wearing-off, dyskineze). Dbejte také na ortostatickou hypotenzi."},{"h":"Indikace k odeslání k lékaři","t":"Upozorněte na náhlé zhoršení příznaků, zkrácení doby účinku léků, halucinace, opakované pády, zhoršení dysfagie nebo vysokou horečku se silným rigorem."}]},"keypoints":["Cvičení načasujte na období účinnosti léků, tzv. „on“ fázi","Vnější signální podněty (pruhy na podlaze, rytmický zvuk) snižují freezing","Opakovaně procvičujte pomalé pohyby o velké amplitudě","Při otáčení a duálním úkolu je vysoké riziko pádu","Proti předkloněnému držení těla zařaďte extenzní a rotační cviky trupu"],"case":{"text":"72letá žena, Parkinsonova choroba (Hoehn–Yahr III). V úzkých dveřích a při otáčení jí tuhnou nohy, doma několikrát upadla. Příznaky jsou silnější, když účinek léků odeznívá.","answer":"Kvůli freezingu a posturální instabilitě je vysoké riziko pádu. V „on“ fázi procvičujte chůzi a otáčení pomocí vizuálních/akustických podnětů a upravte domácí prostředí. Medikaci proberte s lékařem; pacient ji nesmí měnit sám."},"questions":[{"level":"Základní","q":"Která struktura degeneruje primárně u Parkinsonovy choroby?","options":["Mozek","Substantia nigra","Přední roh míchy","Motorická kůra"],"answer":1,"exp":"Dopaminergní neurony substantia nigra degenerují; pokles hladiny dopaminu ve striatu způsobuje motorické příznaky."},{"level":"Základní","q":"Co je charakteristické pro tremor u Parkinsonovy choroby?","options":["Intenční tremor","Zhoršuje se při pohybu","Klidový tremor","Přetrvává i během spánku"],"answer":2,"exp":"Objevuje se v klidu a při volním pohybu ustupuje. Intenční tremor je k vidění při mozečkovém poškození."},{"level":"Pokročilý","q":"Co charakterizuje III. stádium dle Hoehn–Yahrové?","options":["Objavuje se posturální instabilita","Pouze jednostranné příznaky","Vozík, upoutání na lůžko","Oboustranné příznaky, intaktní posturální reflexy"],"answer":0,"exp":"III.: oboustranné příznaky s posturální instabilitou. I.: jednostranné; II.: oboustranné se zachovanými posturálními reflexy; V.: vozík nebo upoutání na lůžko."},{"level":"Pokročilý","q":"Čím lze omezit freezing?","options":["Chůze se zavřenýma očima","Náhlé zvýšení rychlosti chůze","Opakovaná chůze v úzké chodbě","Vizuální podnět, např. pruhy na podlaze"],"answer":3,"exp":"Vnější signální podněty (pruhy na podlaze, zvuk metronomu) snižují freezing a zlepšují délku kroku."},{"level":"Klinický","q":"Pacient s Parkinsonovou chorobou užívá léky ráno a v poledne; pozdě odpoledne zpomaluje, cvičení vázne. Co uděláte?","options":["Odpoledne zvýšíte objem cvičení","Cvičení plánujte na období „on”.","Pacient si dávku upravuje sám.","Ukončete fyzioterapii."],"answer":1,"exp":"Podezření na wearing-off. Cvičení načasujte na dobu účinku léku, kolísání stavu oznamte lékaři. Medikaci nastavuje lékař."},{"level":"Klinický","q":"Pacient s Parkinsonovou nemocí náhle vysadil léky; objevuje se vysoká horečka, výrazná rigidita a porucha vědomí. Co uděláte?","options":["Vyčkejte s mírným pohybem.","Zvyšte intenzitu protahování.","Přestaňte, okamžitě informujte lékaře.","Druhý den přehodnotíte"],"answer":2,"exp":"Horečka, rigor a porucha vědomí po náhlém vysazení léků jsou podezřením na maligní syndrom (stav podobný NMS), vyžadují urgentní péči. Okamžitě informujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Neurologie","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"Roztroušená skleróza","lead":"Zánět poškozuje myelinovou pochvu v centrálním nervovém systému; často se střídají relapsy a remise. Klíčem je dávkování zátěže s ohledem na únavu a zvýšení tělesné teploty.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Autoimunitní onemocnění: v mozku, míše a zrakovém nervu vznikají demyelinizační ložiska diseminovaná v čase a prostoru. Častější u mladých dospělých, zejména žen."},{"h":"Hlavní příznaky","t":"Poruchy zraku (optická neuritida), svalová slabost, poruchy citlivosti, spasticita, ataxie, únavnost, poruchy funkce močového měchýře a střev, Lhermittův příznak atd."},{"h":"Vyšetřovací hlediska","t":"EDSS, svalový test, MAS, rovnováha, schopnost chůze a míra únavy. Sledujte také změny příznaků v závislosti na denní době a teplotě."},{"h":"Průběh léčby","t":"V relapsu odpočinek a šetrná cvičení ROM; v remisi aerobní, posilovací a balanční cvičení, přizpůsobená únavě, postupně."},{"h":"Opatrnost, kontraindikace","t":"Zvýšení tělesné teploty přechodně zhoršuje příznaky (Uhthoffův fenomén): vyhněte se teplému prostředí a přetěžování, zařazujte pauzy."},{"h":"Indikace k odeslání k lékaři","t":"Nové zhoršení zraku, brnění nebo paralýza, případně náhlé zhoršení příznaků trvající déle než 24 hodin, může značit relaps: informujte lékaře."}]},"keypoints":["Cvičte v chladném prostředí, vyhněte se zvýšení tělesné teploty.","Při silné únavě snižte zátěž, zařazujte odpočinek.","V relapsu a remisi aplikujte odlišný soubor cviků.","Do nácviku ADL integrujte techniky šetření energií.","Spasticitu ošetřujte protahováním a polohováním."],"case":{"text":"32letá žena, roztroušená skleróza (remise). Během cvičení v teplé tělocvičně se zvýšila slabost a brnění dolních končetin, ale po odpočinku a ochlazení se stav do cca 30 minut upravil.","answer":"Pravděpodobně jde o přechodné zhoršení příznaků v důsledku zvýšení tělesné teploty (Uhthoffův fenomén). Pokračujte v chladném prostředí, s pauzami a sníženou intenzitou. Pokud se stav nelepší ani po odpočinku a příznaky přetrvávají, pomýšlejte na relaps a informujte lékaře."},"questions":[{"level":"Základní","q":"Která struktura je primárně poškozena u roztroušené sklerózy?","options":["Myelin periferních nervů","Myelin centrálního nervového systému","Neuromuskulární ploténka","Kosterní svalová vlákna"],"answer":1,"exp":"Dochází k poškození myelinové pochvy mozku, míchy a zrakového nervu, tedy centrálního nervového systému. Periferní demyelinizace se vyskytuje např. u Guillainova–Barrého syndromu."},{"level":"Základní","q":"Který jev představuje přechodné zhoršení příznaků při zvýšení tělesné teploty?","options":["Lhermittův příznak","Rombergův příznak","Babinského reflex","Uhthoffův fenomén"],"answer":3,"exp":"Uhthoffův fenomén: při zvýšení tělesné teploty se přechodně zhoršují příznaky. Lhermittův příznak: při flexi krku vystřeluje bolest podobná elektrickému výboji přes záda do končetin."},{"level":"Pokročilý","q":"Jaká je vhodná fyzioterapie při relapsu roztroušené sklerózy?","options":["Vysokointenzivní posilování","Dlouhotrvající aerobní trénink","Šetrná cvičení v rozsahu pohybu (ROM)","Cvičení v teplém prostředí"],"answer":2,"exp":"Při relapsu je zánět aktivní, proto se vyhněte přetížení; do popředí vystupují šetrná cvičení v rozsahu pohybu a polohování."},{"level":"Pokročilý","q":"Který příznak: při flexi krku vystřeluje bolest podobná elektrickému výboji přes záda do končetin?","options":["Lhermittův příznak","Uhthoffův fenomén","Hoffmannův reflex","Trendelenburgův příznak"],"answer":0,"exp":"Lhermittův příznak je častý u lézí krční míchy a je jedním z charakteristických znaků roztroušené sklerózy."},{"level":"Klinický","q":"Pacient s RS se večer silně unaví, jeho chůze se stává nejistou. Co doporučíte?","options":["Zvyšte pohybovou aktivitu na večer","Rozložte aktivitu do vhodnějších částí dne","Pokračujte bez odpočinku","Cvičte v teplé místnosti"],"answer":1,"exp":"Únavu řešte s využitím principů šetření energií: aktivitu rozložte do vhodnějších částí dne a plánovaně zařazujte odpočinek."},{"level":"Klinický","q":"Pacient s RS v remisi: již několik dní přetrvává zhoršení zraku na jednom oku a nové brnění dolní končetiny. Jak postupujete?","options":["Zvýšíte intenzitu cvičení","Přidáte termoterapii","S podezřením na relaps informujete lékaře","Za měsíc provedete přehodnocení"],"answer":2,"exp":"Dlouhodobě přetrvávající nový neurologický příznak může naznačovat relaps. Nezvyšujte zátěž a co nejdříve informujte lékaře."}],"seccion":"Zranění a rehabilitace","grupo":"Neurologie","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"Poranění míchy","lead":"Poranění míchy poškozuje motorické, senzorické a vegetativní funkce pod úrovní léze. V centru pozornosti stojí cíle přizpůsobené zachovaným funkcím a prevence komplikací.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Příčinou je pád, dopravní nehoda nebo onemocnění; rozlišujeme kompletní a inkompletní poranění. Poranění krční páteře způsobuje tetraplegii, poranění hrudní a bederní páteře paraplegii."},{"h":"Hlavní příznaky","t":"Pod úrovní poranění se vyskytuje motorická obrna a poruchy citlivosti, poruchy funkce močového měchýře a střev, vegetativní poruchy (ortostatická hypotenze, poruchy termoregulace) a spasticita."},{"h":"Vyšetřovací hlediska","t":"Podle kritérií ASIA určete neurologickou úroveň a AIS; segment po segmentu vyšetřete sílu klíčových svalů a citlivost. ADL hodnotíte pomocí škál FIM nebo SCIM."},{"h":"Průběh léčby","t":"V akutní fázi se zaměřte na dechovou rehabilitaci, polohování a udržení ROM; v subakutní fázi na posilování zachovaných svalů a nácvik ADL: sed, transfery, ovládání vozíku."},{"h":"Opatrnost, kontraindikace","t":"Při poranění nad úrovní Th6 sledujte známky autonomní dysreflexie. Naučte pacienta odlehčovací techniky k prevenci dekubitů; při ortostatické hypotenzi postupujte při vertikalizaci pozvolna."},{"h":"Indikace k odeslání k lékaři","t":"Sledujte náhlé zvýšení krevního tlaku provázené bolestí hlavy, pocením a zčervenáním obličeje; dále neurologické zhoršení, horečku, zhoršení dekubitů a otok dolní končetiny (podezření na hlubokou žilní trombózu)."}]},"keypoints":["Neurologická úroveň: nejkaudálnější segment se zachovanou funkcí.","Při poranění C6 využijte k úchopu tenodézový efekt.","Při autonomní dysreflexii pacienta posaďte a odstraňte vyvolávající příčinu (např. plný močový měchýř).","Pravidelnými odlehčovacími pohyby předcházejte vzniku dekubitů.","Při poranění krční páteře vyšetřete dechové funkce a asistujte při odkašlávání."],"case":{"text":"25letý muž, kompletní poranění C6 (AIS A), 2 měsíce po nehodě. Během cvičení se náhle objevuje silná bolest hlavy, zčervenání obličeje a pocení, krevní tlak výrazně stoupá. Plánovaný čas cévkování již uplynul.","answer":"Podezření na autonomní dysreflexii vyvolanou plným močovým měchýřem. Cvičení ukončete, pacienta posaďte (hlava zvýšená), uvolněte oděv, hledejte a odstraňte příčinu a okamžitě informujte lékaře a sestru. Nenechávejte pacienta v leže."},"questions":[{"level":"Základní","q":"Který sval je klíčovým svalem pro segment C7, jenž umožňuje přesun pomocí odrazu (push-up)?","options":["m. biceps brachii","m. triceps brachii","m. iliopsoas","m. quadriceps femoris"],"answer":1,"exp":"Klíčovým svalem pro C7 je m. triceps brachii (extenze lokte). m. biceps brachii je klíčovým svalem pro C5, m. iliopsoas pro L2 a m. quadriceps femoris pro L3."},{"level":"Základní","q":"Pro kterou úroveň poranění je typické využití tenodézového efektu k úchopu?","options":["C4","Th6","C6","L3"],"answer":2,"exp":"Při poranění C6 je možná extenze zápěstí; při extenzi prsty pasivně flektují (tenodézový efekt), což lze využít k úchopu."},{"level":"Pokročilý","q":"Co znamená stupeň A na škále poškození ASIA (AIS)?","options":["Inkompletní, zachována pouze citlivost","Částečně zachovaná motorická funkce","Neurologicky intaktní","V S4–5 není přítomna žádná motorická ani senzorická funkce"],"answer":3,"exp":"AIS A: kompletní poranění, v nejnižších sakrálních segmentech (S4–5) není přítomna žádná motorická ani senzorická funkce. AIS B: inkompletní, zachována pouze citlivost."},{"level":"Pokročilý","q":"U které úrovně poranění je častá autonomní dysreflexie?","options":["Th6 a výše","Th12 a níže","L3 a níže","Cauda equina"],"answer":0,"exp":"Při poranění nad úrovní Th6 vzniká v reakci na podněty pod úrovní léze (např. plný močový měchýř) nadměrná sympatická odpověď a náhlé zvýšení krevního tlaku."},{"level":"Klinický","q":"Pacient s poraněním C6: při zvyšování náklonu na polohovacím stole se objevuje závrať, bledost a pokles krevního tlaku. Co uděláte?","options":["Zvýšíte náklon dále, aby si zvykl","Stůl okamžitě vrátíte do vodorovné polohy","Budete pokračovat ve cvičení","V sedě necháte pacienta předklonit hlavu"],"answer":1,"exp":"Podezření na ortostatickou hypotenzi. Vraťte stůl do původní polohy, zkontrolujte příznaky a krevní tlak. Prevence: břišní pás, kompresní punčochy, postupná vertikalizace."},{"level":"Klinický","q":"Pacient s kompletním poraněním hrudní míchy na vozíku: sakrální zarudnutí při tlaku nebledne a přetrvává. Co uděláte?","options":["Zarudnutí silně masírujete","Zvykáte ho na delší sezení","Zkontrolujete způsob a frekvenci odlehčování","Není třeba dělat nic"],"answer":2,"exp":"Přetrvávající zarudnutí je časným příznakem dekubitu. Přehodnoťte odlehčování a sedací polštář, informujte ošetřující tým. Masírování zarudnutí zhoršuje poškození tkáně."}],"seccion":"Zranění a rehabilitace","grupo":"Neurologie","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"Poranění periferních nervů","lead":"Periferní nerv je poškozen v důsledku traumatu nebo komprese, což vede k poklesu motorických, senzorických a vegetativních funkcí v inervované oblasti. Je důležité sledovat závažnost poranění a průběh regenerace.","sheet":{"kind":"condition","items":[{"h":"Klinický obraz","t":"Seddonova klasifikace: přechodná porucha vedení (neurapraxie), přerušení axonu (axonotméza), úplné přerušení nervu (neurotméza)."},{"h":"Hlavní příznaky","t":"Ochablá obrna a atrofie inervovaných svalů, poruchy citlivosti a pocení v dané oblasti. Šlachové reflexy jsou snížené nebo vyhaslé."},{"h":"Vyšetřovací hlediska","t":"Manuální svalový test, vyšetření citlivosti (dotek, bolest, diskriminace dvou bodů), změna místa Tinelova příznaku, výsledky EMG a vyšetření vedení nervu."},{"h":"Průběh léčby","t":"Ortézou předcházejte přetažení paralyzovaných svalů a udržujte rozsah pohybu (ROM). V tempu reinervace postupujte od aktivních asistovaných cvičení směrem k posilování."},{"h":"Opatrnost, kontraindikace","t":"V oblasti výpadku citlivosti dbejte na prevenci popálenin a otlaků. Vyhněte se přetěžování ochrnutých svalů a nadměrnému protahování po sutuře nervu."},{"h":"Indikace k odeslání k lékaři","t":"Nahlaste náhlou progresi obrny, silnou bolest nebo otok, změnu barvy kůže, případně pokud nedochází ke zlepšení v očekávaném čase."}]},"keypoints":["Pokud Tinelův příznak putuje distálně, je to známka regenerace nervu","U vázne ruky a vázne nohy předcházejte ortézou kontrakturám a přetažení","Naučte pacienta, aby oblast se sníženou citlivostí vizuálně kontroloval a chránil","Zlepšení postupuje od svalů blíže k místu poranění směrem k distálním","Po sutuře nervu dodržujte dobu fixace předepsanou lékařem"],"case":{"text":"45letý muž: od zlomeniny diafýzy humeru není schopen extenze zápěstí a prstů. Na hřbetu ruky, mezi palcem a ukazovákem, je snížená citlivost. Extenze v lokti je možná.","answer":"Podezření na obrnu n. radialis (vázne ruka) vzniklou v úrovni diafýzy humeru. Ortézou udržující zápěstí v dorzální flexi předcházejte přetažení a kontrakturám, udržujte ROM. Zlepšení sledujte pomocí Tinelova příznaku a svalového testu; pokud se nedostaví, informujte lékaře."},"questions":[{"level":"Základní","q":"Obrna kterého nervu způsobuje vázne ruku?","options":["n. medianus","n. ulnaris","n. radialis","n. musculocutaneus"],"answer":2,"exp":"N. radialis inervuje extenzory zápěstí a prstů; při jeho obrně nelze provést extenzi zápěstí a vzniká tzv. kapající ruka (drop hand)."},{"level":"Základní","q":"Obrna kterého nervu způsobuje drápovité postavení IV.–V. prstu?","options":["n. ulnaris","n. radialis","n. axillaris","n. femoralis"],"answer":0,"exp":"Při obrně n. ulnaris jsou ochrnuty interossei a lumbrikální svaly IV.–V. prstu, čímž prsteníček a malíček zaujmou drápovité postavení."},{"level":"Pokročilý","q":"Podle Seddona, ve kterém stavu je axon intaktní a porucha vedení je pouze přechodná?","options":["Neurotméza","Neurapraxie","Axonotméza","Wallerova degenerace"],"answer":1,"exp":"Neurapraxie je přechodná porucha vedení při zachování kontinuity axonu; není spojena s Wallerovou degenerací a hojí se relativně rychle."},{"level":"Pokročilý","q":"Který nález je vhodný pro sledování regenerace periferních nervů?","options":["Zvýšené šlachové reflexy","Babinského reflex","Rigor","Posun místa Tinelova příznaku"],"answer":3,"exp":"Poklep na regenerující se axonální zakončení vyvolá vystřelující brnění; pokud se tento bod posouvá distálně, je to známka regenerace."},{"level":"Klinický","q":"Po sádrové fixaci bérce není kvůli tlaku na hlavičku fibuly možná dorzální flexe v hleznu. Co uděláte?","options":["Udržujete hlezno v plantární flexi","Léčíte padající nohu pomocí hlezenní ortézy","Posilujete paralyzovaný sval velkým odporem","Aplikujete silné teplo na oblast se sníženou citlivostí"],"answer":1,"exp":"U padající nohy při paréze n. peroneus communis předchází hlezenní ortéza zakopávání a kontraktuře v plantární flexi. V oblasti se sníženou citlivostí hrozí při aplikaci tepla popálení."},{"level":"Klinický","q":"Po řezné ráně na volární straně zápěstí není možná opozice palce a atrofuje thenar. Které nervové poškození je pravděpodobné?","options":["n. ulnaris","n. radialis ramus superficialis","n. medianus","n. musculocutaneus"],"answer":2,"exp":"n. medianus inervuje svaly thenaru (např. m. opponens pollicis); při jeho obrně je opozice obtížná a vzniká opičí ruka."}],"seccion":"Zranění a rehabilitace","grupo":"Neurologie","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"Manuální terapie (Maitland)","lead":"Systém založený na vyšetření kloubních akcesorních pohybů a stupňovaných oscilačních pasivních pohybech, který ovlivňuje bolest a rozsah pohybu. Charakteristické je opakované vyšetření a znovuvyšetření.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Využitím akcesorních kloubních pohybů snižuje bolest a zlepšuje mobilitu kloubu. Techniku a intenzitu volíte na základě reakce pacienta."},{"h":"Hlavní techniky a typy","t":"Oscilační pasivní pohyby v I.–IV. stupni. V. stupeň je vysokorychlostní thrust o malé amplitudě (manipulace)."},{"h":"Indikace","t":"Bolest kloubního původu a omezení hybnosti v důsledku zkrácení pouzdra nebo vazů (bolesti beder, krční páteře, zmrzlé rameno atd.)."},{"h":"Kontraindikace, opatrnost","t":"Nelze aplikovat při zlomeninách, maligních nádorech, infekcích, akutní fázi zánětlivých onemocnění, těžké osteoporóze, progredujících neurologických příznacích nebo podezření na poškození krčních cév."},{"h":"Tipy pro provedení","t":"Při převaze bolesti volte I.–II. stupeň, při převaze ztuhlosti III.–IV. stupeň. Před ošetřením a po něm zkontrolujte srovnávací znaky, abyste posoudili účinek."},{"h":"Evidence","t":"V kombinaci s terapeutickým cvičením může krátkodobě snížit bolest. Samostatná aplikace má omezený dlouhodobý účinek."}]},"keypoints":["Při bolesti I.–II., při ztuhlosti III.–IV. stupeň","Před ošetřením a po něm posuďte účinek pomocí srovnávacích znaků","Akcesorní pohyb vyšetřete na základě stranového rozdílu a konečného pocitu (end-feel)","Před technikou vylučte červené vlajky","Dosažený rozsah pohybu udržujte pomocí domácích cvičení."],"case":{"text":"50letý muž, chronická ztuhlost pravé strany krku. Klidovou bolest téměř nemá; na konci rotace doprava cítí odpor a mírnou bolest. Červené vlajky nejsou přítomny.","answer":"Ztuhlost převažuje nad bolestí, proto přichází v úvahu III.–IV. stupeň zasahující do odporu. Před ošetřením a po něm znovu vyšetřete rotační ROM a bolest a převeďte je do domácích cvičení. Bez vyšetření neaplikujte silný thrust."},"questions":[{"level":"Základní","q":"Který popis správně charakterizuje IV. stupeň dle Maitlanda?","options":["Velká amplituda před odporem","Malá amplituda na začátku rozsahu","Malá amplituda na konci rozsahu","Velká amplituda v odporu"],"answer":2,"exp":"IV. stupeň je pohyb s malou amplitudou v odporu, na konci rozsahu pohybu. Malá amplituda na začátku rozsahu: I.; velká amplituda v odporu: III."},{"level":"Základní","q":"Který stupeň zvolíte primárně pro tlumení bolesti?","options":["I.–II. stupeň","III.–IV. stupeň","Pouze V. stupeň","Pouze IV. stupeň"],"answer":0,"exp":"I.–II. stupeň probíhá v rozsahu před odporem, hlavně pro tlumení bolesti. III.–IV. je určen pro ztuhlost a omezení pohybu."},{"level":"Pokročilý","q":"Jakou techniku označuje V. stupeň dle Maitlanda?","options":["Velká amplituda před odporem","Vysokorychlostní thrust s malou amplitudou","Trvalá trakce","Masáž měkkých tkání"],"answer":1,"exp":"V. stupeň je vysokorychlostní thrust s malou amplitudou prováděný na konci rozsahu pohybu, tedy manipulace."},{"level":"Pokročilý","q":"Co porovnáváte před ošetřením a po něm pro posouzení účinku?","options":["Laboratorní hodnoty","Nálezy zobrazovacích metod","Změnu tělesné hmotnosti","Srovnávací znaky (asterisk)"],"answer":3,"exp":"Před ošetřením zaznamenejte reprodukovatelné příznaky a rozsah pohybu jako srovnávací znaky, poté zkontrolujte změnu."},{"level":"Klinický","q":"Pacient s akutní bolestí beder: při pohybu silná bolest a obranné svalové napětí. Kterým stupněm začnete?","options":["IV. stupeň","V. stupeň","I.–II. stupeň","III. stupeň"],"answer":2,"exp":"Při silné bolesti a zvýšené reaktivitě tlumte bolest I.–II. stupněm, který nezasahuje do odporu."},{"level":"Klinický","q":"Pacient s bolestí krku: při rotaci krku se objevuje závrať, dvojité vidění a dysartrie. Co uděláte?","options":["Přestanete a oznámíte to lékaři","Zesílíte IV. stupeň","Zkusíte zlepšení thrustem","Zvýšíte počet opakování"],"answer":0,"exp":"Závrať, dvojité vidění a dysartrie jsou příznaky naznačující cévní poškození v oblasti krku. Ukončete manuální terapii a oznamte to lékaři."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"Proprioceptivní neuromuskulární facilitace (PNF)","lead":"Stimulací proprioceptorů podněcuje nervosvalové odpovědi. Charakteristické jsou spirálně-diagonální pohybové vzorce; používáme je ke zlepšení svalové síly, koordinace a rozsahu pohybu.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Drážděním proprioceptorů facilituje motorickou odpověď a zlepšuje svalovou sílu, koordinaci, stabilitu a rozsah pohybu (ROM)."},{"h":"Hlavní techniky a typy","t":"Diagonální vzorce pletence ramenního, pánevního a končetin v kombinaci s rytmickou iniciací, výdrží–uvolněním, rytmickou stabilizací a dalšími technikami."},{"h":"Indikace","t":"Onemocnění centrálního nervového systému a ortopedické diagnózy, sportovní úrazy, pokud se vyskytuje svalová slabost, porucha koordinace, omezení rozsahu pohybu nebo kloubní nestabilita."},{"h":"Kontraindikace, opatrnost","t":"Nelze aplikovat u nezhojených zlomenin, v pooperačních oblastech, kde ještě není povolen odpor, a při silné bolesti. U kardiovaskulárních rizik dbejte na to, aby pacient nezadržoval dech."},{"h":"Tipy pro provedení","t":"Kombinujte manuální kontakt, verbální instrukce, vizuální zpětnou vazbu, trakci/aproximaci, protažení, optimální odpor a časování. Odpor nesmí bránit plynulému pohybu."},{"h":"Evidence","t":"Podle zpráv zlepšuje rozsah pohybu (ROM) a svalovou funkci. Účinek závisí na diagnóze a cíli; aplikujte v kombinaci s dalšími terapeutickými cvičeními."}]},"keypoints":["Při omezení pohybu z důvodu bolesti: výdrž–uvolnění","Pokud je obtížné zahájit pohyb: rytmická iniciace","Odpor musí být „optimální“: nesmí bránit plynulému pohybu","Při normálním časování začíná pohyb distálně","Vyhněte se zadržování dechu, pacient musí plynule dýchat"],"case":{"text":"60letá žena, omezená abdukce po periarthritis humeroscapularis. Při pohybu je přítomna silná bolest, při pasivním protažení se zvyšuje obranné svalové napětí.","answer":"Při omezení pohybu provázeném bolestí je vhodná technika výdrž–uvolnění využívající izometrickou kontrakci. Provádějte bez zvyšování bolesti, před a po změřte ROM. Vyhněte se opakovanému silnému pasivnímu protahování."},"questions":[{"level":"Základní","q":"Co je charakteristické pro pohybové vzorce PNF?","options":["Jednorovinný, přímočarý pohyb","Spirálně-diagonální pohyb","Pouze izokinetický pohyb","Pouze pasivní pohyb"],"answer":1,"exp":"Vzorce PNF jsou spirálně-diagonální pohyby spojující komponenty flexe–extenze, addukce–abdukce a rotace."},{"level":"Základní","q":"Který základní prvek PNF zprostředkovává směr pohybu skrze ruce fyzioterapeuta?","options":["Chladový podnět","Elektrická stimulace","Manuální kontakt","Ultrazvuk"],"answer":2,"exp":"Manuální kontakt vede svalovou kontrakci a směr pohybu pacienta tlakem působícím ve směru pohybu."},{"level":"Pokročilý","q":"Kterou techniku PNF aplikujete, pokud má pacient potíže se zahájením pohybu?","options":["Výdrž–uvolnění","Kontrakce–uvolnění","Ritmická stabilizace","Rytmická iniciace"],"answer":3,"exp":"Rytmická iniciace probíhá v pořadí pasivní → aktivní asistovaný → aktivní → odporový pohyb, což pomáhá při zahájení a učení se pohybu."},{"level":"Pokročilý","q":"Která technika zvyšuje kloubní stabilitu střídavými izometrickými kontrakcemi?","options":["Ritmická stabilizace","Rytmická iniciace","Kontrakce–uvolnění","Opakované protažení"],"answer":0,"exp":"Při rytmické stabilizaci antagonistické svalové skupiny střídavě izometricky kontrahují bez pohybu, což zvyšuje stabilitu."},{"level":"Klinický","q":"Flexe kolena je omezená kvůli bolesti. Která PNF technika je vhodná ke zlepšení rozsahu pohybu?","options":["Kontrakce–uvolnění","Výdrž–uvolnění","Opakované protažení","Rytmická iniciace"],"answer":1,"exp":"Při technice výdrž-relaxace následuje po izometrické kontrakci omezujícího svalu uvolnění; používá se při omezení pohybu provázeném bolestí."},{"level":"Klinický","q":"Během odporového PNF cvičení pacient zadržuje dech a červená v obličeji. Co uděláte?","options":["Ještě zvýšíte odpor","Zvýšíte počet opakování","Upozorníte ho, aby nezadržoval dech","Požádáte ho o rychlejší tempo"],"answer":2,"exp":"Zadržování dechu způsobje zvýšení krevního tlaku. Upravte odpor a požádejte ho, aby prováděl cvičení s plynulým dýcháním."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"Elektroterapie","lead":"Elektrickou stimulací tlumí bolest nebo vyvolává svalovou kontrakci. Typ a parametry stimulačního proudu se volí s ohledem na cíl, kontraindikace je nutné vždy zkontrolovat.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Tlumení bolesti, zachování a zvýšení svalové síly vyvoláním svalové kontrakce, opětné učení pohybu, snížení otoků."},{"h":"Hlavní techniky a typy","t":"TENS (transkutánní elektrická nervová stimulace), NMES (neuromuskulární elektrická stimulace), FES (funkční elektrická stimulace), interferenční proud, vysokonapěťový pulzní proud atd."},{"h":"Indikace","t":"Akutní a chronická bolest, svalová slabost po operaci nebo imobilizaci, facilitace paretických svalů po cévní mozkové příhodě, stimulace padající špičky při chůzi."},{"h":"Kontraindikace, opatrnost","t":"Je nutné se jí vyhnout v případě kardiostimulátoru a jiných implantovaných elektronických zařízení, u těhotných na břiše a bedrech, nad sinus caroticus, v oblasti nádorů, porušené kůže a poruch citlivosti."},{"h":"Tipy pro provedení","t":"Zkontrolujte stav kůže a citlivost; umístění a velikost elektrody, frekvenci, šířku impulzu, intenzitu a dobu ošetření přizpůsobte cíli."},{"h":"Evidence","t":"Podle zpráv je užitečná při pooperační slabosti quadricepsu a funkčním zlepšení po cévní mozkové příhodě. Výsledky vlivu na bolest jsou kontroverzní."}]},"keypoints":["Před ošetřením zkontrolujte stav kůže a případnou poruchu citlivosti","V anamnéze se vždy zeptejte na implantovaná elektronická zařízení","Na bolest zvolte TENS, k vyvolání svalové kontrakce NMES","Po ošetření sledujte, zda je pod elektrodou začervenání nebo horkost","Kombinujte elektrickou stimulaci s aktivním cvičením"],"case":{"text":"65letý muž po operaci endoprotézy kolene. Volní kontrakce m. quadriceps je slabá, při testu SLR se koleno úplně natahuje (extenční deficit). Pacemaker nemá, kožní léze nejsou přítomny.","answer":"Při slabosti kvadricepsu a nedostatečné kontrakci lze zvážit NMES v kombinaci s aktivním cvičením. Elektrody umístěte mimo operační ránu, sledujte reakci kůže a bolesti. Do rány a oblasti se sníženou citlivostí proud nezadávejte."},"questions":[{"level":"Základní","q":"Která elektroterapie slouží se senzorickou stimulací hlavně k tlumení bolesti?","options":["FES","TENS","NMES","Ultrazvuk"],"answer":1,"exp":"TENS transkutánně stimuluje senzitivní nervy za účelem tlumení bolesti. NMES vyvolává svalovou kontrakci, FES pomáhá s pohybem."},{"level":"Základní","q":"Která elektroterapie stimuluje sval s načasováním na pohyb (např. chůzi) a nahrazuje funkci?","options":["TENS","Ultrazvuk","FES","Teplý obklad"],"answer":2,"exp":"FES (funkční elektrická stimulace) stimuluje svaly v rytmu pohybu a nahrazuje funkci, např. při padající špičce během chůze."},{"level":"Pokročilý","q":"Která je kontraindikace elektroterapie?","options":["Chronická bolest v dolní části zad","Svalová slabost po operaci","Vázne noha (drop foot)","Implantovaný kardiostimulátor"],"answer":3,"exp":"Implantovaná elektronická zařízení mohou vlivem stimulačního proudu selhat, proto představují kontraindikaci. Ostatní možnosti jsou indikace."},{"level":"Pokročilý","q":"Která metoda kříží dva středofrekvenční proudy tak, aby v hloubce vznikl nízkofrekvenční podnět?","options":["Interferenční proud","TENS","FES","Iontoforéza"],"answer":0,"exp":"Interferenční proud kříží dva středofrekvenční proudy o různých frekvencích; nízkofrekvenční podnět odpovídající jejich rozdílu vzniká v hloubce."},{"level":"Klinický","q":"Po náhradě kolenního kloubu je aktivní kontrakce kvadricepsu slabá. Co je správnou volbou?","options":["Pouze tepelná terapie","NMES v kombinaci s aktivním cvičením","Elektroda na operační ránu","Odpočinek, dokud se kontrakce nevrátí"],"answer":1,"exp":"NMES se používá při nedostatečné kontrakci kvadricepsu po operaci, v kombinaci s aktivním cvičením. Elektrodu přiložte tak, abyste se vyhnuli ráně."},{"level":"Klinický","q":"Po elektrické stimulaci je v místě elektrody vidět začervenání a puchýř. Co uděláte?","options":["Pokračujte s větší intenzitou","Nalepte ji znovu na stejné místo","Zastavte, zkontrolujte kůži a nahlaste to","Vyčkejte s ohřevem"],"answer":2,"exp":"Začervenání a puchýř pod elektrodou mohou poukazovat na poranění kůže. Zastavte léčbu, zaznamenejte stav kůže a nahlaste to."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"Ultrazvuk, laser, teplo a chlad","lead":"Působí na bolest a stav tkání pomocí tepla, zvukových vln, světla nebo chlazení. Na základě fáze a cíle se rozhodněte pro zahřátí nebo chlazení a zkontrolujte kontraindikace.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Tlumení bolesti, snížení svalového tonu, zlepšení tažnosti tkání, zmírnění akutního zánětlivého otoku; před nebo po terapeutických cvičeních."},{"h":"Hlavní techniky a typy","t":"Ultrazvuk (kontinuální, impulzní), nízkovýkonový laser, povrchová tepelná terapie (teplý obklad, parafín), mikrovlnná diatermie, kryoterapie (ledový obklad atd.)."},{"h":"Indikace","t":"Teplo: chronická bolest, tuhost, kontraktura; chlad: bolest a otok po akutním zranění; ultrazvuk: mimo jiné zlepšení tažnosti měkkých tkání."},{"h":"Kontraindikace, opatrnost","t":"Teplu se vyhněte při akutním zánětu, krvácivých stavech, v oblasti nádorů; ultrazvuku na okně oka, těhotném břiše, růstové chrupavce; chladu v oblasti postižené Raynaudovým syndromem."},{"h":"Tipy pro provedení","t":"Před ošetřením zkontrolujte kůži a vnímání tepla a chladu, během něj kůži sledujte. Ultrazvukovou hlavici neustále pohybujte, nezastavujte se na jednom bodě."},{"h":"Evidence","t":"Používá se k-krátkodobému tlumení bolesti jako doplněk terapeutických cvičení. Samostatný účinek je dle většiny zpráv omezený; hlavním prvkem je pohybová terapie."}]},"keypoints":["Na akutní otok a horkost chlad, na chronickou tuhost teplo","Předem zkontrolujte vnímání tepla a chladu, vyhněte se oblasti s poruchou citlivosti","Ultrazvukovou hlavici pohybujte bez zastavení","Po tepelné terapii lze dobře navázat protažením a pohybovou terapií","Fyzikální terapie je doplňkem pohybové terapie"],"case":{"text":"22letý muž utrpěl při fotbale inverzní podvrtnutí hlezna; druhý den po zranění. Kolem vnějšího kotníku je otok, horkost a citlivost na tlak, při zátěži silná bolest. Lékař vyloučil zlomeninu.","answer":"Přítomny jsou známky akutního zánětu, proto chladovou terapií, kompresí a polohováním snižte bolest a otok. Teplo může v této fázi otok zvětšit, vyhněte se mu. Pro prevenci omrzlin během ošetření sledujte kůži."},"questions":[{"level":"Základní","q":"Kterou fyzikální terapii použijete ke snížení akutního otoku a bolesti?","options":["Teplý obklad","Parafín","Kryoterapie","Mikrovlnná diatermie"],"answer":2,"exp":"Chlad způsobuje vazokonstrikci, snižuje akutní bolest a otok. Ostatní možnosti jsou tepelná terapie, při akutním zánětu nevhodné."},{"level":"Základní","q":"Která patří mezi povrchové tepelné terapie?","options":["Mikrovlnná diatermie","Teplý obklad","Kontinuální ultrazvuk","Nízkoúrovňový laser"],"answer":1,"exp":"Teplý obklad a parafín zahřívají od kůže povrchové tkáně. Mikrovlnná diatermie a kontinuální ultrazvuk jsou hloubkové tepelné terapie."},{"level":"Pokročilý","q":"Která oblast je kontraindikována pro ultrazvukovou terapii?","options":["m. quadriceps femoris","Oblast ramene","m. triceps surae","Oční bulva"],"answer":3,"exp":"Oční bulva je oblast kontraindikovaná pro ultrazvuk. Dále je nutné se vyhnout těhotnému břichu, růstové chrupavce a nádorové oblasti."},{"level":"Pokročilý","q":"Jaké je správné provedení ultrazvukové terapie?","options":["Hlavici neustále pohybujete","Držíte hlavici na jednom bodě","Aplikujete bez gelu","Pokračujete i při bolesti"],"answer":0,"exp":"Pokud hlavice stojí na místě, teplo se koncentruje a může způsobit poškození tkáně, proto ji aplikujeme s gelem a za neustálého pohybu."},{"level":"Klinický","q":"Podvrtnutí hlezna, den po úrazu: výrazný otok a horkost. Jaká je vhodná fyzikální terapie?","options":["Teplý obklad","Chlad, komprese, polohování","Parafín","Mikrovlnná diatermie"],"answer":1,"exp":"Při známkách akutního zánětu snižte chladem, kompresí a polohováním bolest a otok. Teplo může otok zvětšit."},{"level":"Klinický","q":"V důsledku diabetické neuropatie je snížena citlivost nohy; na nohu je plánován teplý obklad. Co uděláte?","options":["Aplikujete při vyšší teplotě po krátkou dobu","Aplikujete obvyklým způsobem","Na oblast se sníženou citlivostí teplo neaplikujete","Aplikujete dlouze během spánku"],"answer":2,"exp":"Oblast s poruchou citlivosti nevnímá teplo dobře, hrozí velké riziko popálení. Vyhněte se tepelné terapii a zvolte jinou metodu."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"Hydroterapie, masáž a manuální lymfodrenáž","lead":"Hydroterapie využívá vztlak, tlak a teplotu vody, masáž a manuální lymfodrenáž působí rukama na měkké tkáně. Klíčem je přesné zvážení indikací a kontraindikací.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Hydroterapie pomáhá s pohybem a úlevou od bolesti pomocí vztlaku, tlaku vody a tepla. Masáž uvolňuje svalový tonus, manuální lymfodrenáž redukuje lymfedém."},{"h":"Hlavní techniky a typy","t":"Vířivka, Hubbardova vana, léčebný tělocvik v bazénu. Masáž: tření, hnětení, tlak atd. U lymfedému komplexní fyzikální protiedémová terapie (péče o kůži, manuální drenáž, komprese, pohyb)."},{"h":"Indikace","t":"Po kloubních onemocněních a operacích vyžadujících omezení zátěže, při bolesti a zvýšeném svalovém tonu, sekundárním lymfedému (např. po operaci nádoru), primárním lymfedému."},{"h":"Kontraindikace, opatrnost","t":"Horečka, akutní infekce (např. celulitida), akutní hluboká žilní trombóza, otevřená rána, dekompenzované srdeční selhání. Ve vodě hydrostatický tlak zvyšuje zátěž srdce."},{"h":"Tipy pro provedení","t":"Lymfodrenáž začněte centrálně od edematózní oblasti, mírným tlakem pohybujícím pouze kůží. Při cvičení ve vodě zkontrolujte teplotu vody, dobu trvání, stav a vitální parametry."},{"h":"Evidence","t":"U lymfedému se doporučuje komplexní terapie včetně komprese. Masáž má sama o sobě omezený účinek, proto se používá spolu s terapeutickými cvičeními."}]},"keypoints":["Uvolňovací síla odlehčuje zátěž; zátěž se mění s hloubkou vody.","Hydrostatický tlak pomáhá žilnímu návratu, ale zatěžuje srdce.","Lymfodrenáž začněte centrálně, mírným tlakem","Začervenání, horkost, horečka: podezření na infekci, zastavte činnost","U lymfedému komplexní terapie včetně komprese"],"case":{"text":"65letá žena. Sekundární lymfedém po operaci rakoviny prsu; obvod postižené horní končetiny je větší než u zdravé. Nejsou přítomny začervenání, horkost ani horečka, hluboká žilní trombóza nebyla diagnostikována.","answer":"Bez známek infekce a trombózy je indikována komplexní terapie. Kombinujte péči o kůži, centrálně zahájenou manuální drenáž mírným tlakem, kompresi a pohyb pod kompresí. V případě začervenání nebo horečky přestaňte a oškrťte pacienta k lékaři."},"questions":[{"level":"Základní","q":"Která vlastnost vody snižuje zátěž tělesné hmotnosti působící na klouby?","options":["Vztlaková síla","Viskozita","Měrné teplo","Povrchové napětí"],"answer":0,"exp":"Vztlak působí proti tělesné hmotnosti, čímž snižuje zátěž. Viskozita je odpor proti pohybu, měrné teplo souvisí s tepelným účinkem."},{"level":"Základní","q":"Kterou oblast ošetřujete jako první při manuální lymfodrenáži?","options":["Nejvýraznější distální část edému","Oblast centrálnější od edematózní oblasti","Konce prstů rukou a nohou","Pouze nejbolestivější část"],"answer":1,"exp":"Nejprve drenujete centrální část (mízní uzliny, stranu blíže k trupu), abyste uvolnili cestu, a poté postupujete distálně."},{"level":"Pokročilý","q":"Která je nejtypičtější kontraindikace manuální lymfodrenáže?","options":["Chronický sekundární lymfedém","Lymfedém horní končetiny v udržovací fázi","Akutní hluboká žilní trombóza","Mírná suchost kůže"],"answer":2,"exp":"U akutní hluboké žilní trombózy se trombus může uvolnit, proto je kontraindikována. Chronický lymfedém je indikací, suchost kůže ošetřujeme péčí o kůži."},{"level":"Pokročilý","q":"Co NENÍ součástí komplexní terapie lymfedému?","options":["Péče o kůži","Manuální lymfodrenáž","Kompresní terapie","Dlouhodobé uvedení postižené končetiny do klidu"],"answer":3,"exp":"Prvky komplexní terapie: péče o kůži, manuální drenáž, komprese a cvičení pod kompresí. Dlouhodobá imobilizace není součástí."},{"level":"Klinický","q":"60letá žena, edém paže po operaci rakoviny prsu. Během drenáže se na končetině náhle objeví začervenání, horkost a horečka. Co uděláte?","options":["Zvýšíte tlak drenáže","Ukončete léčbu a nahlaste to lékaři","Přidejte tepelnou terapii","Pokračujte silnější kompresí"],"answer":1,"exp":"Známky akutní infekce (např. celulitida). Zastavte drenáž, kompresi i tepelnou terapii a neprodleně odešlete pacienta k lékaři."},{"level":"Klinický","q":"Muž ve věku 70 let, srdeční selhání, dušnost i v klidu. Zvažujete cvičení v bazénu. Jaké je správné rozhodnutí?","options":["Zátěž na srdce se zvyšuje, poraďte se s lékařem","Díky vzlaku lze provádět bez omezení","Provádějte v hluboké vodě a dlouho","Provádějte v teplejší vodě"],"answer":0,"exp":"Hydrostatický tlak ve vodě zvyšuje venózní návrat a zátěž srdce. U nestabilního srdečního selhání konzultujte indikaci s lékařem."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"Kineziotaping","lead":"Na kůži aplikujeme elastickou pásku pro poskytnutí senzorického podnětu a podporu kloubního pohybu. Oboznamte se se základy aplikace a prevencí kožních problémů; používejte jako doplňěk terapeutických cvičení.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Pomocí senzorického podnětu přes kůži podporuje svalovou aktivitu, řídí pohyb kloubů, zlepšuje uvědomění si držení těla a může pomoci snížit edém a krvácení. Silná fixace není cílem."},{"h":"Hlavní techniky a typy","t":"Tvary: I, Y, X a vějíř (lymfatický). Existují aplikace zaměřené na svaly, podporu kloubů a edém. K fixaci používáme neelastické (pevné) tape."},{"h":"Indikace","t":"Pomozte snížit bolest a otok po sportovním zranění, naučte se znovu používat svaly, uvědomte si držení těla a osové postavení vedle terapeutických cvičení."},{"h":"Kontraindikace, opatrnost","t":"Poranění kůže, infekce, ekzém, předchozí alergie na tape, podezření na hlubokou žilní trombózu, starší osoba s křehkou kůží. V oblasti s poruchou citlivosti lze kožní problém těžko rozeznat."},{"h":"Tipy pro provedení","t":"Kůže musí být čistá a suchá, rohy stříhněte do kulata. Oba konce nalepte bez napnutí. Nejdříve vyzkoušejte malý kousek a požádejte pacienta, aby v případě svědění nebo začervenání tape okamžitě odstranil."},{"h":"Evidence","t":"Podle většiny studií je účinek na bolest krátkodobý a omezený, proto se nejedná o samostatnou léčbu, nýbrž o doplněk terapeutických cvičení."}]},"keypoints":["Cílem elastického tapu je podpora, nikoliv fixace","Oba konce přiložte na kůži bez napnutí","Čistá, suchá kůže; rohy stříhněte do kulata","V případě svědění nebo začervenání je nutné ihned odstranit","Účinek je omezený, kombinujte s terapeutickými cvičeními"],"case":{"text":"22letý muž, 3 dny po inverzním podvrtnutí hlezna. Kolem vnějšího kotníku je viditelný otok a podlitina, při zátěži mírná bolest. Nikdy nebyl tapován, kožní onemocnění neměl.","answer":"Nejprve zkontrolujte stav kůže a nalepte malý zkušební kousek. Na otok aplikujte vějířovitý tvar s mírným napnutím, vedle terapeutických cvičení. Netvrďte, že tape vyléčí; požádejte pacienta, aby jej v případě svědění nebo začervenání sundal."},"questions":[{"level":"Základní","q":"S jakým napnutím nalepíte oba konce elastického tapu?","options":["S maximálním natažením","Pouze s prudce nataženými konci","Bez napnutí","Seštípnutím kůže"],"answer":2,"exp":"Oba konce (kotvy) přiložte na kůži bez napětí. Napětí na koncích táhne kůži, což vede k odlepení a podráždění kůže."},{"level":"Základní","q":"Který tvar se používá, když tape rozstřihnete na dva cípky a obemknete jím svalové bříško?","options":["Tvar I","X tvar","Vějířovitý tvar","Tvar Y"],"answer":3,"exp":"Základnu Y tvaru upevníte v jednom bodě a dvěma cípky obemknete svalové bříško. Vějířovitý tvar nastříháte na tenké proužky a rozprostřete přes otok."},{"level":"Pokročilý","q":"Při jakém příznaku je nutné tape po nalepení ihned odstranit?","options":["Svědění nebo začervenání v místě nalepení","Mírné svalové napětí po tréninku","Budete lépe vnímat své držení těla","Pocit lehčího pohybu"],"answer":0,"exp":"Svědění a začervenání jsou známkou podráždění kůže (např. alergie na tape). Pro zamezení zhoršení požádejte pacienta, aby jej ihned sundal."},{"level":"Pokročilý","q":"Co zvolíte, pokud chcete pohyb kloubu silně omezit a zafixovat jej?","options":["Elastický tape ve tvaru I","Neelastický (pevný) tape","Elastický tape ve tvaru vějíře","Y tvar bez napětí"],"answer":1,"exp":"Pro silnou fixaci je nutný neelastický tape. Elastický tape pohyb téměř neomezuje; jeho cílem je opora a senzorický podnět."},{"level":"Klinický","q":"U 20letého muže plánujete tapování otoku po podvrtnutí kotníku. Co je nejdůležitější zkontrolovat před nalepením?","options":["Rychlost chůze","Klidovou tepovou frekvenci","Stav pokožky a předchozí alergii na tapy","Šikovnější nohu"],"answer":2,"exp":"Před nalepením zkontrolujte poranění kůže, ekzém a předchozí alergie na tape. Při kožních problémech netapujte."},{"level":"Klinický","q":"30letá žena po tapování ramene říká: „bolí to méně“. Co jí odpovíte?","options":["Tkáň se zregenerovala a uzdravila","Účinek je často přechodný, je nutné jej kombinovat se cvičením","Musí jej nosit neustále","Její svalová síla se okamžitě zvýšila"],"answer":1,"exp":"Účinek tapování je krátkodobý a omezený. Nevytvářejte přehnaná očekávání; vysvětlete, že se jedná o doplněk terapeutického cvičení."}],"seccion":"Léčba a intervence","grupo":"Techniky a fyzioterapie","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"Léčebná tělesná výchova","lead":"Jádro fyzioterapie: předepsanými cviky zlepšujeme svalovou sílu, flexibilitu, vytrvalost a rovnováhu pro zlepšení ADL. Znejte zásady zátěže a kritéria pro ukončení cvičení k zajištění bezpečného postupu.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Zlepšení rozsahu pohybu, svalové síly, svalové a celkové vytrvalosti, flexibility, rovnováhy a koordinace s cílem zlepšit základní pohyby, ADL a zapojení."},{"h":"Hlavní techniky a typy","t":"Cvičení ROM (pasivní, aktivně asistované, aktivní), posilování (izometrické, izotonické – koncentrické, excentrické –, izokinetické), protažení, aerobní trénink, cvičení rovnováhy a koordinace."},{"h":"Indikace","t":"Široce: muskoskeletální onemocnění, po operacích, neurologická a interní onemocnění, inaktivační syndrom, ztráta funkcí ve stáří."},{"h":"Kontraindikace, opatrnost","t":"Nestabilní srdeční onemocnění, špatně korigovaná hypertenze, akutní zánět, nezajištěná zlomenina: opatrnost nebo kontraindikace. Zkontrolujte kritéria pro ukončení zátěže."},{"h":"Tipy pro provedení","t":"Zátěž nastavte podle principu přetížení, specificity a reverzibility, sledujte subjektivní vnímání zátěže a vitální parametry. Všimněte si kompenzace; zadržujte dech."},{"h":"Evidence","t":"U mnoha muskoskeletálních a chronických onemocnění je terapeutické cvičení doporučeným základem léčby. Účinek závisí na tom, zda je program dlouhodobě proveditelný."}]},"keypoints":["Zátěž budujte podle principu přetížení, specificity a reverzibility","V časné pooperační fázi začněte izometrickým cvičením bez pohybu v kloubu","Vyhněte se zadržování dechu (tlačení), dýchejte plynule","Všimněte si kompenzace, pracujte se správným pohybem","Bolest na hrudi, studený pot, silná dušnost: okamžitě zastavte, nahlaste"],"case":{"text":"72letá žena, 3 týdny po TEP kolena. Svalová síla m. quadriceps je stupeň 3: aktivně pohybuje v plném rozsahu pohybu, ale nevydrží odpor. Vitální parametry jsou stabilní.","answer":"Začněte aktivním pohybem proti gravitaci, poté postupně přidejte mírný odpor. Sledujte kompenzaci a bolest, vyhněte se zadržování dechu. Nedávejte maximální zátěž hned první den."},"questions":[{"level":"Základní","q":"Která forma svalové kontrakce je ta, při které sval vyvíjí napětí a zároveň se prodlužuje?","options":["Koncentrická kontrakce","Excentrická kontrakce","Izometrická kontrakce","Izokinetická kontrakce"],"answer":1,"exp":"Při excentrické kontrakci vyvíjí sval sílu během prodlužování. Při koncentrické během zkracování, při izometrické bez změny délky."},{"level":"Základní","q":"Podle kterého principu je nutné podat větší zátěž než obvykle pro zvýšení svalové síly?","options":["Princip specificity","Princip reverzibility","Princip přetížení","Princip individuálnosti"],"answer":2,"exp":"Podle principu přetížení dochází k adaptaci vlivem podnětu přesahujícího obvyklou zátěž."},{"level":"Pokročilý","q":"Které cvičení posiluje bez pohybu v kloubu, a proto se dobře hodí brzy po operaci?","options":["Izometrický cvik","Izokinetické cvičení","Plyometrické cvičení","Vysokozátěžové excentrické cvičení"],"answer":0,"exp":"Při izometrickém cvičení se sval stahuje bez pohybu v kloubu, čímž šetří kloub a ránu, proto jej lze provádět brzy."},{"level":"Pokročilý","q":"Čemu je třeba se vyhnout během posilovacího cvičení?","options":["Plynulému dýchání","Kontrole kompenzace","Zahřátí","Zadržování dechu"],"answer":3,"exp":"Zadržování dechu (tlačení) náhle zvyšuje krevní tlak. Hlavně u starších lidí a srdečních pacientů dýchejte plynule."},{"level":"Klinický","q":"Muž v 70 letech, svalová síla m. quadriceps je 3. Jak zahájíte posilování?","options":["Izokinetickým cvičením s maximálním odporem","Aktivním pohybem proti gravitaci, postupnou zátěží","Pouze pasivním pohybem","Vysokointenzivním plyometrickým cvičením"],"answer":1,"exp":"Síla 3 znamená pohyb v plném rozsahu proti gravitaci. Začněte aktivním pohybem a postupně přidejte mírný odpor."},{"level":"Klinický","q":"Muž v 60 letech, během jízdy na rotopedu se objevuje bolest na hrudi a studený pot. Co uděláte?","options":["Zastavte, změřte vitální funkce, nahlaste lékaři","Snižte zátěž a pokračujte","Po odpočinku pokračujte se stejnou zátěží","Přejděte na protažení"],"answer":0,"exp":"Bolest na hrudi a studený pot jsou kritéria pro ukončení, mohou ukazovat na srdeční onemocnění. Okamžitě cvičení zastavte, změřte vitální funkce a nahlaste to lékaři."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"Můstek","rotulo":"Posiluje","texto":"hýžďové svaly a hamstringy","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"Zvedání natažené nohy","rotulo":"Posiluje","texto":"quadriceps","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"Dřep","rotulo":"Posiluje","texto":"kvadriceps a hýžďové svaly","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"Respirační fyzioterapie","lead":"Učením dýchacích technik, podporou vykašlávání a terapeutickými cvičeními zlepšuje ventilaci a snižuje dušnost. Má klíčovou roli u CHOPN a v prevenci pooperačních plicních komplikací.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Zlepšení ventilace, podpora clearance dýchacích cest, snížení dušnosti, zlepšení zátěžové tolerance a ADL, prevence pooperačních plicních komplikací."},{"h":"Hlavní techniky a typy","t":"Dýchání přes špulené rty, brániční dýchání, polohová drenáž, huffing a nácvik kašle, podpora dýchání, trénink dýchacích svalů, obecné vytrvalostní a posilovací cviky."},{"h":"Indikace","t":"Chronická respirační onemocnění (např. COPD), pneumonie, před a po hrudních a břišních operacích, ventilační poruchy způsobené neuromuskulárním onemocněním, bronchiektázie s nadměrnou tvorbou hlenu."},{"h":"Kontraindikace, opatrnost","t":"Drenáž v polohách se zavěšenou hlavou je nutné vynechat při zvýšeném nitrolebečním tlaku, nestabilní cirkulaci a hemoptýze. Dávejte pozor na neléčený pneumotorax, závažnou arytmii; sledujte SpO2 a příznaky."},{"h":"Tipy pro provedení","t":"Místo výskytu hlenu určete auskultací a z rentgenového či zobrazovacího nálezu a podle toho zvolte polohu. Sledujte SpO2, dechovou frekvenci, tepovou frekvenci a upravenou Borgovu škálu; pohyb přizpůsobte rytmu dýchání."},{"h":"Evidence","t":"U COPD se doporučuje respirační rehabilitace založená na terapeutických cvičeních ke snížení dušnosti a zlepšení zátěžové tolerance."}]},"keypoints":["Dýchání přes špulené rty předchází výdechovému kolapsu dýchacích cest","Při polohové drenáži je segment plic s hlenem nahoře","Huffing: silný, rychlý výdech s otevřenou hlasovou štěrbinou","Poloha hlavy níže než tělo se má vyhnout při zvýšení nitrolebečního tlaku a hemoptýze","Základem respirační rehabilitace u COPD je terapeutické cvičení"],"case":{"text":"74letý muž, COPD, bez domácí kyslíkové terapie. Silná dušnost při chůzi a oblékání; po uspěchaném pohybu klesá SpO2. Málo hlenu, klidový stav je stabilní.","answer":"Naučte pacienta dýchání přes špulené rty a rozvržení tempa pohybu, poté za sledování SpO2 a dušnosti provádějte vytrvalostní cvičení a posilování dolních končetin. Požádejte ho, aby nepospíchal se zadrženým dechem."},"questions":[{"level":"Základní","q":"Kterou dýchací techniku učíte u COPD k prevenci výdechového kolapsu dýchacích cest?","options":["Rychlé, povrchní hrudní dýchání","Zadržení dechu","Dýchání přes špulené rty","Hyperventilace"],"answer":2,"exp":"Dýchání přes špulené rty klade odpor při výdechu, udržuje tlak v dýchacích cestách, předchází kolapsu a pomáhá s výdechem."},{"level":"Základní","q":"Při které metodě umístíte segment plic s hlenem nahoru, aby gravitace pomohla pohybu hlenu?","options":["Huffing","Polohová drenáž","Trénink dýchacích svalů","Dýchání přes špulené rty"],"answer":1,"exp":"Během polohové (posturální) drenáže je segment s hlenem nahoře a gravitace posouvá hlen směrem k centrálním dýchacím cestám."},{"level":"Pokročilý","q":"Která je to technika, při které pohybujete hlenem silným a rychlým výdechem s otevřenou hlasovou štěrbinou?","options":["Potlačení kašle","Brániční dýchání","Valsalvův manévr","Huffing"],"answer":3,"exp":"Huffing je usilovný výdech s otevřenou hlasivkovou štěrbinou; pohybuje hlenem při menším vzestupu intratorakálního tlaku než kašel."},{"level":"Pokročilý","q":"U kterého stavu je kontraikceptována polohová drenáž v polohování hlavou níže?","options":["Zvýšený nitrolebeční tlak","Chronická bronchiektázie","Pneumonie s nadměrnou tvorbou hlenu","Atektáza dolního laloku"],"answer":0,"exp":"Poloha hlavou níže zvyšuje nitrolebeční tlak, proto je při jeho zvýšení kontraindikována. Ostatní stavy mohou být indikací k drenáži."},{"level":"Klinický","q":"Muž v 70 letech, COPD. Při chůzi se zhoršuje dušnost a klesá SpO2. Co ho naučíte?","options":["Chodit rychle, abyste to měl rychle za sebou","Dýchání přes špulené rty a rozvržení tempa pohybu","Pohybovat se se zadrženým dechem","Zcela přestat chodit"],"answer":1,"exp":"Přizpůsobte tempo pohybu dýchání a používejte dýchání přes špulené rty. Úplná inaktivita urychluje dekondici."},{"level":"Klinický","q":"Pacient prvního dne po břišní operaci. Co pomáhá v prevenci pooperačních plicních komplikací?","options":["Několikatenný klid na lůžku","Vynechání dechových cvičení kvůli bolesti","Časná mobilizace, nácvik hlubokého dýchání a kašle","Dlouhodobá poloha hlavou níže"],"answer":2,"exp":"Časná mobilizace a nácvik hlubokého dýchání a kašle (s oporou rány) jsou důležité v prevenci atektázy a pneumonie."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"Kardiovaskulární rehabilitace","lead":"Komplexní program kombinující léčebný tělocvik, edukaci pacienta a poradenství v oblasti životního stylu. Cílem je zlepšit zatížitelnost a kvalitu života a předcházet relapsům. Bezpečnost je na prvním místě.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Zlepšení zatížitelnosti a kvality života, korekce rizikových faktorů ICHS, prevence relapsů, snížení úzkosti a podpora návratu do práce a společnosti."},{"h":"Hlavní techniky a typy","t":"Aerobní trénink (chůze, rotoped), odporový trénink, edukace pacienta, poradenství v oblasti životního stylu (užívání léků, strava, zanechání kouření). Postupuje ve třech fázích: akutní, rehabilitační, udržovací."},{"h":"Indikace","t":"Po akutním infarktu myokardu, angina pectoris, po srdečních operacích, chronické srdeční selhání, onemocnění velkých cév, periferní arteriální onemocnění. Podmínkou je stabilní stav."},{"h":"Kontraindikace, opatrnost","t":"Nestabilní angina, nekontrolovaná arytmie, dekompenzované srdeční selhání, symptomatická těžká aortální stenóza, akutní myokarditida: léčebný tělocvik je kontraindikován."},{"h":"Tipy pro provedení","t":"Intenzitu nastavte na základě spiroergometrického anaerobního prahu (AT) nebo subjektivního vnímání zátěže. Při užívání beta-blokátorů tepová frekvence téměř stoupá: sledujte také příznaky, krevní tlak a EKG."},{"h":"Evidence","t":"U ischemické chorobné srdeční a chronického srdečního selhání doporučují guidelines komplexní kardiologickou rehabilitaci zahrnující i léčebný tělocvik."}]},"keypoints":["Cvičení, edukace a poradenství ohledně životního stylu dohromady","Intenzitu nastavte podle AT nebo subjektivního vnímání zátěže","Při užívání beta-blokátorů se nerozhodujte pouze podle tepové frekvence","Bolest na hrudi, odchylka ST, arytmie: cvičení ukončete","Náhlý přírůstek hmotnosti, edém: podezření na zhoršení srdečního selhání"],"case":{"text":"63letý muž po léčbě akutního infarktu myokardu cvičí ambulantně v rehabilitační fázi. Užívá beta-blokátor. Během jízdy na rotopedu nemá potíže na hrudi, ale tepová frekvence se mu téměř zvedá.","answer":"Beta-blokátor tlumí reakci tepové frekvence, proto zvyšujte zátěž nejen podle ní: rozhodujte se podle subjektivního pocitu zátěže, krevního tlaku a EKG. Při bolesti na hrudi nebo odchylce ST cvičení ukončete a informujte lékaře."},"questions":[{"level":"Základní","q":"Co NENÍ součástí kardiologické rehabilitace?","options":["Terapeutické cvičení","Edukace pacienta","Korekce rizikových faktorů koronárních tepen","Dlouhodobý klid na lůžku"],"answer":3,"exp":"Kardiologická rehabilitace je komplexní program obsahující cvičení, edukaci pacienta, poradenství v oblasti životního stylu a psychickou podporu. Dlouhodobý klid na lůžku vede k dekondici."},{"level":"Základní","q":"Který ukazatel získaný ze spiroergometrie používáte k nastavení intenzity?","options":["Manuální svalový test","Anaerobní práh (AT)","Rozsah pohybu (ROM)","Síla stisku"],"answer":1,"exp":"Anaerobní práh (AT) je častým ukazatelem intenzity aerobního tréninku; určuje se spiroergometrií."},{"level":"Pokročilý","q":"Co je kontraindikací terapeutického cvičení?","options":["Stabilní chronické srdeční selhání","Rehabilitační fáze po operaci bypassu","Nestabilní angina pectoris","Stabilní stadium po infarktu"],"answer":2,"exp":"Nestabilní angina pectoris je kontraindikací terapeutického cvičení. Stabilní chronické srdeční selhání a rehabilitační fáze po operaci nebo infarktu jsou indikací."},{"level":"Pokročilý","q":"Co je užitečné pro posouzení intenzity u pacienta užívajícího beta-blokátory?","options":["Subjektivní pocit zátěže (Borgova stupnice)","Pouze tepová frekvence","Tělesná hmotnost","Tělesná teplota"],"answer":0,"exp":"Beta-blokátor inhibuje nárůst tepové frekvence, takže pouze na jejím základě můžete nastavit příliš velkou zátěž. Využijte i subjektivní pocit zátěže."},{"level":"Klinický","q":"Muž v 60 letech, rehabilitační fáze po infarktu. Během chůze se objevuje bolest na hrudi a deprese úseku ST. Co uděláte?","options":["Zvýšíte rychlost chůze","Pokračujete a sledujete pacienta","Po doplnění tekutin se stejnou zátěží","Cvičení ukončíte a informujete lékaře"],"answer":3,"exp":"Bolest na hrudi a deprese úseku ST jsou signálem k ukončení cvičení poukazujícím na ischemii myokardu. Cvičení okamžitě zastavte a informujte lékaře."},{"level":"Klinický","q":"Žena v 70 letech, chronické srdeční selhání. Během několika dnů jí náhle narostla hmotnost, zhoršil se otok bérce a dušnost. Co uděláte?","options":["Zvýšíte intenzitu","Máte podezření na zhoršení srdečního selhání, informujete lékaře","Cvičíte obvyklým způsobem","Přidáte pouze posilovací trénink"],"answer":1,"exp":"Rychlý nárůst hmotnosti, edém a zhoršující se dušnost jsou známkou zhoršení srdečního selhání. Cvičení odložte a informujte lékaře."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"Pánevní dno a zdraví žen","lead":"Zabývá se močovou inkontinencí způsobenou disfunkcí svalů pánevního dna, sestupem pánevních orgánů a tělesnými změnami po těhotenství a porodu. Základem je výuka správné kontrakce a screening červených vlajek.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Zlepšení svalové síly, vytrvalosti a koordinace svalů pánevního dna, zmírnění inkontinence a prolapsu orgánů; úprava lumbopelvické bolesti a funkce trupu po těhotenství a porodu."},{"h":"Hlavní techniky a typy","t":"Cvičení pánevního dna, biofeedback, výuka kontroly intraabdominálního tlaku a dýchání, výuka držení těla a pohybu, poradenství v oblasti životního stylu (vyprázdňovací návyky, kontrola hmotnosti atd.)."},{"h":"Indikace","t":"Stresová a smíšená inkontinence, mírný sestup pánevních orgánů, slabost pánevního dna po porodu, diastáza přímých břišních svalů, inkontinence u mužů po radikální prostatektomii."},{"h":"Kontraindikace, opatrnost","t":"Vnitřní (vaginální) vyšetření vyžaduje specializované školení, důkladné poučení a informovaný souhlas. V pozdním těhotenství může dlouhé ležení na zádech způsobit syndrom duté žíly. Hematurie, horečka, necitlivost v hradzi: vyhledejte lékaře."},{"h":"Tipy pro provedení","t":"Zkontrolujte stiskací a zvedací kontrakci; vyvarujte se napínání břišních, hýžďových a adduktorových svalů a tlačení. Procvičujte rychlou a vytrvalou kontrakci způsobem, který lze provádět i v každodenním životě."},{"h":"Evidence","t":"U stresové inkontinence je cvičení pánevního dna léčbou první volby. Účinek závisí na vytrvalosti pacienta při cvičení."}]},"keypoints":["Učte svaly pánevního dna pokynem „stiskněte a vytáhněte nahoru“","Tlačení a napínání hýžďových svalů jsou kompenzace, je třeba se jim vyhnout","Únik při kašli a kýchání: stresová inkontinence","V pozdním těhotenství může dlouhé ležení na zádech způsobit pokles krevního tlaku","Náhlé potíže s močením, necitlivost v hradzi: okamžitě navštivte lékaře"],"case":{"text":"38letá žena, rok po porodu. Při kašli a kýchání uniká moč. Při sedu se středová čára břicha klene. Žádná hematurie, horečka ani porucha citlivosti v oblasti hradze.","answer":"Myslete na stresovou inkontinenci a diastázu přímých břišních svalů. Učte správnou kontrakci pánevního dna a kontrolu intraabdominálního tlaku bez tlačení. Vyhněte se náhlému a opakovanému provádění silných sedů-lehů."},"questions":[{"level":"Základní","q":"Který je hlavní sval pánevního dna?","options":["M. iliopsoas","M. gluteus maximus","m. levator ani","m. rectus femoris"],"answer":2,"exp":"M. levator ani tvoří spolu s m. coccygeus pánevní bránici, což je hlavní sval pánevního dna. Ostatní jsou svaly kolem kyčle."},{"level":"Základní","q":"Při kterém typu inkontinence dochází k úniku moči, když se při kašli nebo kýchání zvýší intraabdominální tlak?","options":["Urgentní inkontinencia","Stresová inkontinence","Inkontinence z přetečení","Funkční inkontinencia"],"answer":1,"exp":"Při stresové inkontinenci je uzavření močové trubice při zvýšení intraabdominálního tlaku nedostatečné. Urgentní inkontinenci provází silné nutkání na močení."},{"level":"Pokročilý","q":"Jak správně vyučujete kontrakci při cvičení pánevního dna?","options":["Se zadrženým dechem, břišním lisem","Silným stisknutím hýžďových svalů","Vytlačování břicha dopředu","Stisknutí a zvednutí močové trubice, pochvy a konečníku"],"answer":3,"exp":"Stáhněte svaly pánevního dna stiskem a zvednutím. Tlačení, napínání hýžďových svalů a vytlačování břicha dopředu jsou kompenzace."},{"level":"Pokročilý","q":"Na co je nutné dávat pozor, pokud v pozdním těhotenství dlouze ležíte na zádech?","options":["Syndrom duté žíly (hypotonie v polohách na zádech)","Zlepšení diastázy přímých břišních svalů","Hypertrofie svalů pánevního dna","Vymizení inkontinence"],"answer":0,"exp":"V pozdním těhotenství při lehu na zádech děloha tlačí na dolní dutou žílu a může dojít k poklesu krevního tlaku. Otočte ji například do polohy na boku."},{"level":"Klinický","q":"38letá žena, rok po porodu, při kašli dochází k úniku moče, při sedu se vyklenuje střední čára břicha. Jaký je správný postup?","options":["Denně mnoho silných sedů-lehů","Cvičení pánevního dna a kontrola intraabdominálního tlaku","Drastické snížení příjmu tekutin","Doporučení pouze odpočinku"],"answer":1,"exp":"Pravděpodobně se jedná o stresovou inkontinenci a diastázu přímých břišních svalů. Začněte správnou kontrakcí pánevního dna a kontrolou intraabdominálního tlaku."},{"level":"Klinický","q":"Žena v 50 letech dochází na rehabilitaci s bolestmi zad. Udává náhlé potíže s močením a necitlivost v hýžďové oblasti. Co uděláte?","options":["Zintenzivníte cvičení pánevního dna","Počkáte do příští návštěvy","Okamžitě informujete lékaře","Provedete protažení bederní páteře"],"answer":2,"exp":"Náhlé potíže s močením a poruchy citlivosti v oblasti hýždí jsou varovným příznakem (červenou vlajkou) poukazujícím na syndrom cauda equina. Okamžitě odešlete pacientku k lékaři."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"Dětská fyzioterapie","lead":"Oblast podporující motorický vývoj, aktivitu a zapojení vyvíjejícího se dítěte. Staví na znalosti normálního vývoje, probíhá formou hry a ve spolupráci s rodinou.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Podpora motorického vývoje, osvojení základních pohybů a lokomoce, prevence sekundárních poškození (kontraktury, deformity), rozšíření zapojení doma, ve školce a ve škole, podpora rodiny."},{"h":"Hlavní techniky a typy","t":"Neurovývojový přístup, cvičení orientované na úkol, hravý pohyb, management polohování, používání ortéz, pomůcek usnadňujících sed a chodítek, zaškolení rodiny."},{"h":"Indikace","t":"Dětská mozková obrna, vývojové prodlení, Downův syndrom, spina bifida, Duchenneova svalová dystrofie, předčasně narozené děti s nízkou porodní hmotností, ortopedická onemocnění."},{"h":"Kontraindikace, opatrnost","t":"U spastické dětské mozkové obrny je důležitá kontroly subluxace a luxace kyčle. U svalové dystrofie se vyhněte velké zátěži vedoucí k vyčerpání. Dávejte pozor na epileptické záchvaty a únavu."},{"h":"Tipy pro provedení","t":"K vyšetření použijte škály GMFM, GMFCS, primitivní reflexy a posturální reakce. Cvičte formou zábavné hry, denní cíle sdílejte s rodinou, aby v nich bylo možné pokračovat i doma."},{"h":"Evidence","t":"Evidence podporuje cvičení orientované na úkol postavené na jasných cílech a intervenci ve spolupráci s rodinou. Každodenní praxe je důležitější než jednotlivé techniky."}]},"keypoints":["Očekávaná doba pro zvládnutí držení hlavy je 3–4 měsíce věku","GMFCS klasifikuje hrubou motoriku u dětské mozkové obrny do 5 úrovní","U spastické DMO pravidelně kontrolujte luxaci kyčle","U svalové dystrofie se vyhýbejte vysoké zátěži vedoucí k únavě","Cíl sdílejte s rodinou, cvičte hrou"],"case":{"text":"5letý chlapec, spastická diplegie. V bytě se pohybuje s chodítkem, ale je patrná chůze po špičkách. Rodina si přeje, aby „se mohl ve školce pohybovat společně s kamarády”.","answer":"Přání rodiny ať je každodenním cílem: nácvik chůze s chodítkem propojte se hrou a školkovými aktivitami. Předcházejte zkrácení m. triceps surae, zvažte ortézu a zkontrolujte kyčle. Nelpěte pouze na pořadí normálního vývoje."},"questions":[{"level":"Základní","q":"Kdy lze očekávat fixaci hlavičky?","options":["Do 1 měsíce věku","Do 3–4 měsíců věku","Do 7–8 měsíců věku","Do 12 měsíců věku"],"answer":1,"exp":"Fixace hlavičky se očekává kolem 3.–4. měsíce věku. Následuje otáčení, sed, stoj s oporou a samostatná chůze."},{"level":"Základní","q":"Která škála rozděluje hrubou motoriku dětí s dětskou mozkovou obrnou do 5 úrovní?","options":["GMFM","MRC","FIM","GMFCS"],"answer":3,"exp":"GMFCS klasifikuje hrubou motoriku do 5 úrovní. GMFM měří úroveň hrubé motoriky pomocí bodového skóre."},{"level":"Pokročilý","q":"Jakému pohybu se vyhýbejte u Duchennovy svalové dystrofie?","options":["Pohybu s vysokou zátěží vedoucí k únavě","Cvičení ROM","Dechová cvičení","Pohyb hrou"],"answer":0,"exp":"Svalová vlákna se snadno poškodí, proto se vyhýbejte vysoké zátěži vedoucí k únavě. Prevence kontraktur a dechová gymnastika jsou důležité."},{"level":"Pokročilý","q":"Kterou komplikaci je důležité u spastické dětské mozkové obrny pravidelně kontrolovat?","options":["Ruptura předního zkříženého vazu","Ruptura rotátorové manžety","Subluxaci, luxaci kyčle","Podvrtnutí kotníku"],"answer":2,"exp":"Kvůli spasticitě a svalové nerovnováze v okolí kyčle je častá subluxace či luxace kyčle, proto je nutná pravidelná kontrola."},{"level":"Klinický","q":"4leté dítě, spastická diplegie. Jak správně stanovíte cíl chůze?","options":["Fyzioterapeut rozhodne sám","Společně s rodinou stanovíte každodenní cíl","Přísně jen podle pořadí normálního vývoje","Bez hry, cvičíte pouze opakováním"],"answer":1,"exp":"Cíl sdílejte s rodinou a propojte jej s konkrétními domácími či školkovými aktivitami. Hra pomáhá udržet kontinuitu cvičení."},{"level":"Klinický","q":"7letý chlapec, Duchennova svalová dystrofie, stále hůře chodí po schodech. Jaký je správný přístup k pohybu?","options":["Aktivita bez únavy, prevence kontraktur","Excentrické posilování s vysokou zátěží","Zákaz jakéhokoli pohybu","Denně nechat chodit až do úplného vyčerpání"],"answer":0,"exp":"Nadměrná zátěž může urychlit poškození svalů. Udržujte aktivitu v míře, která nevede k únavě, a pokračujte v prevenci kontraktur."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"Fyzioterapie seniorů","lead":"V centru pozornosti je ztráta funkcí spojená se stárnutím, frailty (křehkost), sarkopenie a řešení pádů. Na základě vyšetření pomáháme bezpečně pokračovat v pohybu při zachování soběstačnosti a participace.","sheet":{"kind":"method","items":[{"h":"Cíl","t":"Zachování a zlepšení ADL, životních funkcí a participace; prevence pádů; prevence a zlepšení frailty a sarkopenie; prevence inaktivačního syndromu; odlehčení pečujícím osobám."},{"h":"Hlavní techniky a typy","t":"Posilování dolních končetin a trupu, balanční cvičení, nácvik chůze, trénink dvojích úkolů, nácvik sedu, stoje a přesunů, výběr kompenzačních pomůcek, úprava domácího prostředí."},{"h":"Indikace","t":"Frailty, sarkopenie, po předchozím pádu, zlomenině či operaci, inaktivita v důsledku chronického onemocnění, dekondice po hospitalizaci, podpora aktivity u osob s demencí."},{"h":"Kontraindikace, opatrnost","t":"Sledujte ortostatickou hypotenzi, osteoporotickou zlomeninu obratle, vedlejší účinky polyfarmacie, dehydrataci, křehkou kůži a kognitivní úpadek. Náhlá bolest, změna příznaků: lékař."},{"h":"Tipy pro provedení","t":"Vyšetřete pomocí TUG, stoje na jedné noze, vstávání ze židle, rychlosti chůze, síly stisku a stanovte individuální cíle. Zátěž zvyšujte postupně, v kombinaci s výživou podpořte vytrvalost."},{"h":"Evidence","t":"Pohybové programy obsahující prvky rovnováhy a posilování jsou účinné v prevenci pádů u seniorů žijících doma. Je důležité, aby byly dlouhodobě proveditelné."}]},"keypoints":["Mezi Friedova kritéria frailty patří zpomalená chůze","Sarkopenie: snížená svalová hmota a svalová síla nebo fyzická funkce","Prevence pádů: rovnováha a svalová síla společně","Při mobilizaci po dlouhodobém ležení sledujte ortostatickou hypotenzi","U osteoporózy je náhlá bolest zad podezřelá ze zlomeniny obratle"],"case":{"text":"82letá žena, v uplynulém roce dvakrát spadla. Čas TUG je prodloužený, ze židle vstává pouze s oporou rukou. Léčí se s osteoporózou, bolesti zad nemá. Žije sama, z domova vychází zřídka.","answer":"Vysoké riziko pádů. Postupně kombinujte balanční cvičení a posilování dolních končetin, upravte domácí prostředí a vytvořte příležitost k vycházkám. Nedoporučujte klid na lůžku a již první den nedávejte vysokou zátěž."},"questions":[{"level":"Základní","q":"Který z uvedených patří mezi Friedova kritéria frailty?","options":["Zhoršení zraku","Zvýšení krevního tlaku","Zpomalení rychlosti chůze","Zvýšení tělesné výšky"],"answer":2,"exp":"5 prvků Friedových kritérií: úbytek hmotnosti, vyčerpání, snížená aktivita, zpomalená chůze a snížená svalová síla (síla stisku)."},{"level":"Základní","q":"Který stav je charakterizován úbytkem svalové hmoty v důsledku stárnutí a zhoršením svalové síly nebo fyzické funkce?","options":["Sarkopenie","Osteoporóza","Artróza","Ortostatická hypotenze"],"answer":0,"exp":"U sarkopenie je k úbytku svalové hmoty přidruženo zhoršení svalové síly nebo fyzické funkce. Osteoporóza je úbytek kostní hmoty."},{"level":"Pokročilý","q":"Co měří TUG (Timed Up and Go test)?","options":["Sílu stisku","Pohyb zahrnující vstávání, chůzi a otočení","Pouze kognitivní funkci","Respirační funkci"],"answer":1,"exp":"TUG měří čas, za který pacient vstane ze židle, dojde k cíli, otočí se, vrátí se a sedne si; hodnotí mobilitu a riziko pádů."},{"level":"Pokročilý","q":"Na co je třeba dát zvláštní pozor při prvním posazení a vstávání staršího pacienta po dlouhodobém ležení?","options":["Ruptura rotátorové manžety","Podchlazení","Kontraktura prstů","Ortostatická hypotenze"],"answer":3,"exp":"Po dlouhodobém ležení se zhoršuje regulace krevního tlaku, při posazení či stoji tlak snadno klesá. Sledujte příznaky a krevní tlak."},{"level":"Klinický","q":"Žena v 80 letech, v anamnéze pád, prodloužený čas TUG, snížená síla dolních končetin. Jaký je vhodný postup?","options":["Kombinace balančních cvičení a posilování dolních končetin","Pouze protahování","Doporučení klidu","Posilování s maximální zátěží od prvního dne"],"answer":0,"exp":"V prevenci pádů je efektivní pohyb kombinující balanční a posilovací prvky. Zátěž zvyšujte postupně."},{"level":"Klinický","q":"85letá žena, osteoporóza. Po mírném pádu na hýždě se objevila náhlá silná bolest zad. Co uděláte?","options":["Zvýšíte intenzitu cviků na flexi trupu","Počkáte a aplikujete termoterapii","Pošlete pacientku k lékaři na zobrazovací vyšetření","Provedete protažení zádových svalů"],"answer":2,"exp":"Náhlá bolest zad u seniora s osteoporózou po malém traumatu je podezřelá z kompresivní zlomeniny obratle. Nepokračujte ve cvičení, odešlete k lékaři."}],"seccion":"Léčba a intervence","grupo":"Pohybová terapie a odbornosti","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"Klinické kazuistiky","lead":"Postup klinického uvažování: z anamnézy stanovíte hypotézu, vyšetřením ji ověříte, po shrnutí a interpretaci výsledků určíte cíl a léčbu. Opakovaným vyšetřením průběžně revidujete.","sheet":{"kind":"basics","items":[{"h":"Anamnéza","t":"Zjistěte hlavní potíže, průběh vzniku, lokalizaci a charakter bolesti, zhoršující a zmírňující faktory, anamnézu, léky, životní podmínky a přání pacienta. Prověřte také červené vlajky."},{"h":"Stanovení hypotézy","t":"Na základě anamnézy shromážděte více možných příčin a stavů a rozhodněte, co je třeba vyšetřením ověřit. Neupínejte se ihned k jedinému vysvětlení."},{"h":"Vyšetření","t":"Pohledem, pohmatem, měřením ROM, svalovým testem, speciálními testy, neurologickým vyšetřením a analýzou pohybu ověřte hypotézu. Sledujte stranové rozdíly a reprodukovatelnost."},{"h":"Shrnutí a interpretace","t":"Uspořádejte výsledky v rámci ICF (MKF) (tělesné funkce, aktivita, participace, prostředí) a promyslete souvislosti a pořadí jednotlivých problémů."},{"h":"Stanovení cílů","t":"Společně s pacientem a rodinou stanovte konkrétní, měřitelné, časově ohraničené krátkodobé a dlouhodobé cíle. Důležité jsou cíle vázané na každodenní situace."},{"h":"Léčba a opakované vyšetření","t":"Zvolte intervenci přizpůsobenou cílům a stejnými ukazateli znovu ověřte změnu. Pokud nedochází ke zlepšení, vraťte se k hypotéze a vyšetření."}]},"keypoints":["Během anamnézy vždy prověřujte červené vlajky","Stanovte více hypotéz a každou postupně ověřte vyšetřením","Uspořádejte problémy v rámci ICF","Cíl stanovte společně s pacientem, musí být měřitelný a časově ohraničený.","Pokud nedochází ke zlepšení, přehodnoťte postup od stanovení hypotézy a vyšetření."],"case":{"text":"68letý muž, oboustranná artróza kolen. Při chůzi ho bolí pravé koleno; m. quadriceps vpravo je oslabený, extenze kolene omezená. Jeho přání: „Chci dojít s vnoučetem do blízkého parku“.","answer":"Zaměřte se na bolest, svalovou slabost, omezení pohybu a chůze, a stanovte si jako časově ohraničený cíl chůzi do parku. Provádějte posilovací a ROM cvičení, následně pacienta vyšetřete na základě bolesti a ušlé vzdálenosti. Nerozhodujte se pouze podle zobrazovacích metod."},"questions":[{"level":"Základní","q":"Co následuje v procesu klinického uvažování po anamnéze?","options":["Zahájení léčby","Stanovení hypotézy","Definitivní stanovení cíle","Poradenství při propuštění"],"answer":1,"exp":"Na základě informací z anamnézy stanovíte hypotézu o příčině a stavu a zvolíte vyšetření k jejímu ověření."},{"level":"Základní","q":"Jaký je správný způsob stanovení cíle?","options":["Fyzioterapeut rozhodne sám","Abstraktní formulace","Bez časového omezení","Měřitelný, časově ohraničený cíl"],"answer":3,"exp":"Cíl musí být společný s pacientem a rodinou, konkrétní, měřitelný a časově ohraničený. Tím lze při kontrolním vyšetření posoudit změnu."},{"level":"Pokročilý","q":"Kam podle ICF zařadíte „neschopnost chůze po schodech“?","options":["Aktivita","Participace","Tělesné funkce a struktury","Faktory prostředí"],"answer":0,"exp":"Činnost prováděná jednotlivcem, například chůze po schodech, spadá pod „aktivitu“. Zapojení do společenských rolí je „participace“."},{"level":"Pokročilý","q":"Co uděláte, pokud při kontrolním vyšetření po intervenci nedošlo ke zlepšení?","options":["Pokračujete ve stejné léčbě","Vynecháte vyšetření","Přehodnotíte hypotézu a vyšetření","Připíšete to nízkému úsilí pacienta"],"answer":2,"exp":"Pokud nedochází ke zlepšení, přehodnoťte, zda byla hypotéza a vyšetření správné, a znovu promyslete interpretaci stavu a intervenci."},{"level":"Klinický","q":"Muž v 50 letech: bolest ramene při zvedání ve středním rozsahu, Hawkinsův–Kennedyho test pozitivní, pasivní ROM v normě. Co předpokládáte?","options":["Zmrzlé rameno","Subakromiální impingement","Cervikální radikulopatie","Syndrom horního hruního otvoru (TOS)"],"answer":1,"exp":"Bolestivý oblouk při zvedání ve středním rozsahu a pozitivní Hawkinsův–Kennedyho test ukazují na subakromiální impingement. U zmrzlého ramene je omezen i pasivní ROM."},{"level":"Klinický","q":"Žena v 60 letech, bolest beder; v anamnéze onkologické onemocnění, noční bolesti a nevysvětlitelný úbytek hmotnosti. Co uděláte?","options":["Zahájíte cvičení pro bederní páteř","Provedete manipulaci","Počkáte a aplikujete termoterapii","Informujete lékaře a vyžádáte si vyšetření"],"answer":3,"exp":"Onkologická anamnéza, noční bolest a úbytek hmotnosti jsou červené vlajky naznačující závažné onemocnění. Před zahájením léčby odešlete pacienta k lékaři."}],"seccion":"Léčba a intervence","grupo":"Klinické kazuistiky","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
